module.exports = [{"id":"cat-9a-1-1","title":"第1课 古代埃及","subtitle":"九年级上册 · 第一单元 古代亚非文明","grade":"9a","tags":["九年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第一单元 古代亚非文明"},{"k":"课时","v":"第1课 古代埃及"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"古埃及文明发源于尼罗河流域。尼罗河定期泛滥，留下肥沃淤泥，孕育了发达的农业。约公元前 3100 年，埃及初步统一，法老掌握政治、经济、军事大权，被神化。金字塔是法老陵墓，也是古埃及文明的象征。"},{"type":"note","title":"本课主线 · 因果链","text":"尼罗河、两河流域与印度河—恒河流域的冲积平原提供了灌溉农业的条件，于是在北非、西亚、南亚先后诞生了古埃及、古巴比伦与古印度三个早期国家：它们都以农业立国，都创造了文字、制定了法律或形成了等级制度，构成人类文明最初的一批成果。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 3500 年","尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家","大河流域最早产生文明——这是「文明多诞生于大河流域」这一结论的史实起点 · 重点"],["约公元前 3100 年","古埃及初步实现统一","国王称「法老」，集军政大权与神权于一身，是全国最高统治者；约公元前 3000 年古埃及人创造了象形文字 · 重点"],["约公元前 2600 年","古埃及大规模修建金字塔（胡夫金字塔规模最大）","金字塔是法老的陵墓，也是古埃及文明的象征，是埃及人民劳动与智慧的结晶"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约公元前 3500 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"尼罗河两岸陆续出现若干小国；两河流域…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"约公元前 3100 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"古埃及初步实现统一","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"约公元前 2600 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"古埃及大规模修建金字塔（胡夫金字塔规…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"金字塔是古埃及国王（法老）的陵墓，是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","explain":""},{"level":"次重点","text":"古埃及人创造了象形文字，还制定了世界上最早的太阳历，对后世影响深远。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明大河流域是早期文明的共同摇篮。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用楔形文字刻写；象形文字是古埃及人创造的。","两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。"]]},{"type":"table","title":"古代亚非三大文明：同为大河文明，各有创造（亚非早期文明的横向比较）","head":["比较项","古埃及（尼罗河流域）与古巴比伦（两河流域）","古印度（印度河—恒河流域）"],"rows":[["文明出现","约公元前 3500 年出现小国","约公元前 23—前 18 世纪已有哈拉帕等早期文明"],["文字","象形文字、楔形文字","印章文字（后为梵文）"],["政治","法老集权制；汉谟拉比建立的统一奴隶制国家","长期邦国并立，等级制度森严"],["社会结构","奴隶主与奴隶；《汉谟拉比法典》区分三个社会等级","婆罗门、刹帝利、吠舍、首陀罗四大种姓及贱民"],["共同规律","都依托大河流域的灌溉农业，都是奴隶制国家","同左"]]},{"type":"table","title":"古代亚非文明与古代中国：同一时期的东西方（中外对比（中国早期国家与亚非早期文明））","head":["比较项","古代亚非（古埃及、古巴比伦、古印度）","古代中国（夏、商、西周）"],"rows":[["时间","约公元前 3500—前 6 世纪","约公元前 2070—前 771 年"],["地理条件","尼罗河、两河流域、印度河流域","黄河、长江流域"],["政治制度","法老集权、汉谟拉比的君主统治、种姓等级制","世袭制王朝、西周分封制与宗法制"],["文字","象形文字、楔形文字","甲骨文、金文"],["法律与制度","《汉谟拉比法典》、种姓制度","礼乐制度与「刑」的雏形"],["共同特征","都以农业立国、王权与神权结合、等级分明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["地理环境与文明起源","给出世界文明分布图，要求归纳早期文明的空间分布特点并分析原因。标准答法是：多分布于北纬 20°—40° 的大河流域，水源充足、土壤肥沃、便于灌溉农业与定居。"],["文献史料的信息提取","以《汉谟拉比法典》条文为材料，问「这段材料说明了什么」。答题要先说条文内容（同态复仇、等级差别），再说实质（维护奴隶主阶级利益），最后说地位。"],["宗教与等级制度的关系","以种姓制度与佛教教义为材料，考查「佛教为什么既受民众支持又受统治者扶植」，需分别从反对婆罗门特权、宣扬忍耐顺从两个角度作答。"]]},{"type":"note","title":"跨学科视角","text":"地理：尼罗河、两河、印度河的定期泛滥与农业；科学：金字塔的工程与测量。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["埃及是尼罗河的赠礼","古希腊历史学家希罗多德的名言，说明尼罗河对埃及文明的决定性作用。","希罗多德《历史》第二卷"]]},{"type":"kv","title":"人物卡片","items":[{"k":"胡夫","v":"古埃及第四王朝法老，下令修建胡夫金字塔。 出处：吴于廑、齐世荣《世界史·古代史编》"}]},{"type":"list","title":"延伸阅读","items":["胡夫金字塔：胡夫金字塔约建于公元前 2600 年，原高约 146 米，底边约 230 米，由约 230 万块巨石砌成，是现存最大的金字塔。 出处：吴于廑、齐世荣《世界史·古代史编》","象形文字与纸草：古埃及人使用象形文字，书写在纸草上。1822 年商博良借助罗塞塔石碑成功释读象形文字。 出处：2024 部编版九上第 1 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 1 课；吴于廑、齐世荣《世界史·古代史编》","希罗多德《历史》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u1-q5","type":"choice","stem":"古埃及金字塔的用途是","answer":"B","explain":"金字塔是古埃及国王的陵墓，其中胡夫金字塔规模最大。它是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","options":["神庙，用于祭祀神灵","国王（法老）的陵墓","天文观测台","抵御外敌的军事堡垒"],"tags":["金字塔","史料实证"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9a-1-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 古埃及初步实现统一\n③ 古埃及大规模修建金字塔（胡夫金字塔规模最大）","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②古埃及初步实现统一（约公元前 3100 年）→③古埃及大规模修建金字塔（胡夫金字塔规模最大）（约公元前 2600 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g2","type":"choice","stem":"下列关于「古代埃及」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》刻写用的文字说成象形文字——两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。正确表述：《汉谟拉比法典》用楔形文字刻写；象形文字是古埃及人创造的。","options":["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用楔形文字刻写；象形文字是古埃及人创造的。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明大河流域是早期文明的共同摇篮。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：胡夫金字塔约建于公元前 2600 年，原高约 146 米，底边约 230 米，由约 230 万块巨石砌成，是现存最大的金字塔。（吴于廑、齐世荣《世界史·古代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代埃及；金字塔是古埃及国王（法老）的陵墓，是古埃及文明的象征，反映了古埃及社会经济发展的较高水平和国王的无限权力。","explain":"材料出自吴于廑、齐世荣《世界史·古代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-1-2","title":"第2课 古代两河流域","subtitle":"九年级上册 · 第一单元 古代亚非文明","grade":"9a","tags":["九年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第一单元 古代亚非文明"},{"k":"课时","v":"第2课 古代两河流域"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"两河流域指幼发拉底河与底格里斯河流域，古希腊人称「美索不达米亚」（意为「两河之间的地方」）。约公元前 3500 年，这里出现小国；公元前 18 世纪，古巴比伦王国第六代国王汉谟拉比统一两河流域，颁布法典。"},{"type":"note","title":"本课主线 · 因果链","text":"尼罗河、两河流域与印度河—恒河流域的冲积平原提供了灌溉农业的条件，于是在北非、西亚、南亚先后诞生了古埃及、古巴比伦与古印度三个早期国家：它们都以农业立国，都创造了文字、制定了法律或形成了等级制度，构成人类文明最初的一批成果。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 3500 年","尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家","大河流域最早产生文明——这是「文明多诞生于大河流域」这一结论的史实起点 · 重点"],["约公元前 24 世纪","两河流域实现初步统一","苏美尔人创造的楔形文字是两河流域文明的重要标志"],["公元前 18 世纪","汉谟拉比统一两河流域中下游，定都巴比伦","为维护奴隶主阶级的利益，制定了《汉谟拉比法典》——迄今已知世界上第一部较为完整的成文法典 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约公元前 3500 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"尼罗河两岸陆续出现若干小国；两河流域…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"约公元前 24 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"两河流域实现初步统一","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"公元前 18 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"汉谟拉比统一两河流域中下游，定都巴比…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","explain":"要能写出两点：一是「迄今已知世界上第一部较为完整的成文法典」这一限定语一个字都不能少；二是法典严格维护奴隶主阶级的利益，体现了「同态复仇」与等级差别。"},{"level":"选择题","text":"古巴比伦王国是两河流域文明的代表；楔形文字是苏美尔人创造的，是世界最早的文字之一。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今已知世界上第一部较为完整的成文法典」。","限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。"],["把《汉谟拉比法典》刻写用的文字说成象形文字。","《汉谟拉比法典》用楔形文字刻写；象形文字是古埃及人创造的。","两河流域 = 楔形文字，尼罗河流域 = 象形文字，这是最容易被调换的一组搭配。"]]},{"type":"table","title":"古代亚非三大文明：同为大河文明，各有创造（亚非早期文明的横向比较）","head":["比较项","古埃及（尼罗河流域）与古巴比伦（两河流域）","古印度（印度河—恒河流域）"],"rows":[["文明出现","约公元前 3500 年出现小国","约公元前 23—前 18 世纪已有哈拉帕等早期文明"],["文字","象形文字、楔形文字","印章文字（后为梵文）"],["政治","法老集权制；汉谟拉比建立的统一奴隶制国家","长期邦国并立，等级制度森严"],["社会结构","奴隶主与奴隶；《汉谟拉比法典》区分三个社会等级","婆罗门、刹帝利、吠舍、首陀罗四大种姓及贱民"],["共同规律","都依托大河流域的灌溉农业，都是奴隶制国家","同左"]]},{"type":"table","title":"古代亚非文明与古代中国：同一时期的东西方（中外对比（中国早期国家与亚非早期文明））","head":["比较项","古代亚非（古埃及、古巴比伦、古印度）","古代中国（夏、商、西周）"],"rows":[["时间","约公元前 3500—前 6 世纪","约公元前 2070—前 771 年"],["地理条件","尼罗河、两河流域、印度河流域","黄河、长江流域"],["政治制度","法老集权、汉谟拉比的君主统治、种姓等级制","世袭制王朝、西周分封制与宗法制"],["文字","象形文字、楔形文字","甲骨文、金文"],["法律与制度","《汉谟拉比法典》、种姓制度","礼乐制度与「刑」的雏形"],["共同特征","都以农业立国、王权与神权结合、等级分明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["地理环境与文明起源","给出世界文明分布图，要求归纳早期文明的空间分布特点并分析原因。标准答法是：多分布于北纬 20°—40° 的大河流域，水源充足、土壤肥沃、便于灌溉农业与定居。"],["文献史料的信息提取","以《汉谟拉比法典》条文为材料，问「这段材料说明了什么」。答题要先说条文内容（同态复仇、等级差别），再说实质（维护奴隶主阶级利益），最后说地位。"],["宗教与等级制度的关系","以种姓制度与佛教教义为材料，考查「佛教为什么既受民众支持又受统治者扶植」，需分别从反对婆罗门特权、宣扬忍耐顺从两个角度作答。"]]},{"type":"note","title":"跨学科视角","text":"地理：尼罗河、两河、印度河的定期泛滥与农业；科学：金字塔的工程与测量。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["以眼还眼，以牙还牙","《汉谟拉比法典》中「同态复仇」原则的通俗概括，原文为「若自由民毁坏另一自由民之眼，则应毁其眼」。","《汉谟拉比法典》第 196 条"]]},{"type":"kv","title":"人物卡片","items":[{"k":"汉谟拉比","v":"古巴比伦王国国王，统一两河流域，颁布法典。 出处：《汉谟拉比法典》原文"}]},{"type":"list","title":"延伸阅读","items":["《汉谟拉比法典》：法典刻在黑色玄武岩石柱上，现存于巴黎卢浮宫。正文 282 条，涉及诉讼、财产、婚姻、继承、租赁等，是迄今已知世界上第一部较为完整的成文法典。 出处：《汉谟拉比法典》原文；卢浮宫藏品说明","楔形文字：苏美尔人用芦苇杆在泥板上压出楔形痕迹，形成楔形文字，是世界上最古老的文字之一。 出处：2024 部编版九上第 2 课"]},{"type":"list","title":"本课拓展出处","items":["《汉谟拉比法典》原文；2024 部编版九上第 2 课","吴于廑、齐世荣《世界史·古代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】倘自由民损毁任何自由民之眼，则应毁其眼。倘自由民击落与之同等之自由民之齿，则应击落其齿。——《汉谟拉比法典》\n【材料二】雅利安人进入印度后，逐渐形成严格的等级制度：第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗，由被征服者、贫困破产失去土地的人构成。此外还有被称为「不可接触者」的贱民。\n【材料三】公元前 6 世纪，乔达摩·悉达多创立佛教。佛教提出「众生平等」，反对婆罗门的特权地位；同时又宣扬「忍耐顺从」，认为人生皆苦，只有刻苦修行才能摆脱苦难。公元前 3 世纪后，佛教开始向外传播；公元前 1 世纪，佛教经中亚传入中国。","source":"材料研读 · 古代亚非文明：大河流域的早期国家"}],"questions":[{"id":"h9a-u1-m1-q1","type":"short","stem":"（1）材料一反映出《汉谟拉比法典》具有什么特点？该法典有怎样的历史地位？（4 分）","answer":"特点：实行「同态复仇」原则（以眼还眼、以牙还牙）；对不同社会等级的人处罚标准不同，严格维护奴隶主阶级的利益。历史地位：它是迄今已知世界上第一部较为完整的成文法典，表明人类社会的法制传统源远流长，是古巴比伦王国留给人类的宝贵文化遗产。","explain":"","tags":["《汉谟拉比法典》","史料实证"],"rubric":["答出「同态复仇」或以眼还眼、以牙还牙","答出维护奴隶主阶级利益或等级之间不平等","答出「迄今已知世界上第一部较为完整的成文法典」","答出法制传统源远流长或重要的文化遗产"]},{"id":"h9a-u1-q2","type":"choice","stem":"迄今已知世界上第一部较为完整的成文法典是","answer":"A","explain":"公元前 18 世纪，古巴比伦王国国王汉谟拉比为维护奴隶主阶级的利益制定了《汉谟拉比法典》，刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《汉谟拉比法典》","时空观念"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9a-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 尼罗河两岸陆续出现若干小国；两河流域南部出现苏美…\n② 两河流域实现初步统一\n③ 汉谟拉比统一两河流域中下游，定都巴比伦","answer":"A","explain":"按时间顺序应为：①尼罗河两岸陆续出现若干小国；两河流域南部出现苏美尔人的城邦国家（约公元前 3500 年）→②两河流域实现初步统一（约公元前 24 世纪）→③汉谟拉比统一两河流域中下游，定都巴比伦（公元前 18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g2","type":"choice","stem":"下列关于「古代两河流域」的表述，错误的是","answer":"A","explain":"把《汉谟拉比法典》说成「世界上第一部成文法典」——限定语是得分点：少了「已知」「较为完整」，就不符合史实——苏美尔人早有成文法，只是不如它完整地保存下来。正确表述：它是「迄今已知世界上第一部较为完整的成文法典」。","options":["把《汉谟拉比法典》说成「世界上第一部成文法典」。","它是「迄今已知世界上第一部较为完整的成文法典」。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。","《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g3","type":"choice","stem":"下列结论中，属于「古代两河流域」的是","answer":"A","explain":"本课结论：古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。","文明的产生与自然环境密切相关：大河流域的灌溉农业孕育了古埃及、古巴比伦、古印度等早期文明，这与中华文明诞生于黄河、长江流域完全一致，说明大河流域是早期文明的共同摇篮。","中华文明与古埃及、古巴比伦、古印度文明都是在本土独立起源的原创文明，不存在「中华文明西来说」的史实依据。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明古代亚非文明之间的交流早于新航路开辟，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：法典刻在黑色玄武岩石柱上，现存于巴黎卢浮宫。正文 282 条，涉及诉讼、财产、婚姻、继承、租赁等，是迄今已知世界上第一部较为完整的成文法典。（《汉谟拉比法典》原文；卢浮宫藏品说明）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代两河流域；《汉谟拉比法典》刻在黑色石柱上，用楔形文字写成，是迄今已知世界上第一部较为完整的成文法典。","explain":"材料出自《汉谟拉比法典》原文；卢浮宫藏品说明。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-1-3","title":"第3课 古代印度","subtitle":"九年级上册 · 第一单元 古代亚非文明","grade":"9a","tags":["九年级上册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第一单元 古代亚非文明"},{"k":"课时","v":"第3课 古代印度"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"古印度文明发源于印度河流域，后发展到恒河流域。约公元前 1500 年后，雅利安人进入印度，逐渐形成种姓制度。公元前 6 世纪，乔达摩·悉达多创立佛教。公元前 3 世纪，孔雀王朝阿育王基本统一印度半岛，佛教得到广泛传播。"},{"type":"note","title":"本课主线 · 因果链","text":"尼罗河、两河流域与印度河—恒河流域的冲积平原提供了灌溉农业的条件，于是在北非、西亚、南亚先后诞生了古埃及、古巴比伦与古印度三个早期国家：它们都以农业立国，都创造了文字、制定了法律或形成了等级制度，构成人类文明最初的一批成果。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 1500 年","雅利安人进入南亚次大陆，逐渐建立国家","在此过程中形成了森严的种姓制度"],["公元前 6 世纪","乔达摩·悉达多（释迦牟尼）在古印度创立佛教","主张「众生平等」，反对婆罗门特权；又宣扬「忍耐顺从」，公元前 3 世纪后开始向外传播 · 重点"],["公元前 1 世纪","佛教经中亚传入中国（西汉末年）","中外文明交流的最早例证之一，与中国史直接联动：佛教后成为中国影响最大的宗教之一 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"约公元前 1500 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"雅利安人进入南亚次大陆，逐渐建立国家","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"公元前 6 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"乔达摩·悉达多（释迦牟尼）在古印度创…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"公元前 1 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"佛教经中亚传入中国（西汉末年）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"古印度种姓制度把居民分为婆罗门、刹帝利、吠舍、首陀罗四个等级，等级之间界限森严、世代相袭。","explain":"常以「等级—职业」配对题或材料题出现。要记住顺序是「婆罗门（祭司）→ 刹帝利（国王、武士、官吏）→ 吠舍（农民、牧民、手工业者、商人）→ 首陀罗（被征服者、贫困破产者）」，此外还有「贱民」。"},{"level":"重点","text":"佛教创立于公元前 6 世纪的古印度，提出「众生平等」，反对婆罗门的特权地位，同时宣扬「忍耐顺从」。","explain":"要理解它为什么既能得到民众支持又能得到统治者扶植：反对婆罗门特权符合民众愿望，「忍耐顺从」的说教则有利于维护统治秩序。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明古代亚非文明之间的交流早于新航路开辟，文明从来不是彼此隔绝的。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把种姓制度与佛教的创立顺序记反，或认为佛教维护种姓制度。","种姓制度约在公元前 1500 年雅利安人进入南亚后逐渐形成，佛教创立于公元前 6 世纪，主张「众生平等」，是反对婆罗门特权的。","但要注意：佛教反对的是婆罗门特权，并不主张取消等级社会，其「忍耐顺从」的说教仍有利于统治者，所以后来得到统治者大力扶植。"]]},{"type":"table","title":"古代亚非三大文明：同为大河文明，各有创造（亚非早期文明的横向比较）","head":["比较项","古埃及（尼罗河流域）与古巴比伦（两河流域）","古印度（印度河—恒河流域）"],"rows":[["文明出现","约公元前 3500 年出现小国","约公元前 23—前 18 世纪已有哈拉帕等早期文明"],["文字","象形文字、楔形文字","印章文字（后为梵文）"],["政治","法老集权制；汉谟拉比建立的统一奴隶制国家","长期邦国并立，等级制度森严"],["社会结构","奴隶主与奴隶；《汉谟拉比法典》区分三个社会等级","婆罗门、刹帝利、吠舍、首陀罗四大种姓及贱民"],["共同规律","都依托大河流域的灌溉农业，都是奴隶制国家","同左"]]},{"type":"table","title":"古代亚非文明与古代中国：同一时期的东西方（中外对比（中国早期国家与亚非早期文明））","head":["比较项","古代亚非（古埃及、古巴比伦、古印度）","古代中国（夏、商、西周）"],"rows":[["时间","约公元前 3500—前 6 世纪","约公元前 2070—前 771 年"],["地理条件","尼罗河、两河流域、印度河流域","黄河、长江流域"],["政治制度","法老集权、汉谟拉比的君主统治、种姓等级制","世袭制王朝、西周分封制与宗法制"],["文字","象形文字、楔形文字","甲骨文、金文"],["法律与制度","《汉谟拉比法典》、种姓制度","礼乐制度与「刑」的雏形"],["共同特征","都以农业立国、王权与神权结合、等级分明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["地理环境与文明起源","给出世界文明分布图，要求归纳早期文明的空间分布特点并分析原因。标准答法是：多分布于北纬 20°—40° 的大河流域，水源充足、土壤肥沃、便于灌溉农业与定居。"],["文献史料的信息提取","以《汉谟拉比法典》条文为材料，问「这段材料说明了什么」。答题要先说条文内容（同态复仇、等级差别），再说实质（维护奴隶主阶级利益），最后说地位。"],["宗教与等级制度的关系","以种姓制度与佛教教义为材料，考查「佛教为什么既受民众支持又受统治者扶植」，需分别从反对婆罗门特权、宣扬忍耐顺从两个角度作答。"]]},{"type":"note","title":"跨学科视角","text":"地理：尼罗河、两河、印度河的定期泛滥与农业；科学：金字塔的工程与测量。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["众生平等","佛教基本主张之一，反对婆罗门宣扬的种姓不平等。","2024 部编版九上第 3 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"乔达摩·悉达多","v":"佛教创始人，被尊称为「释迦牟尼」。 出处：吴于廑、齐世荣《世界史·古代史编》"},{"k":"阿育王","v":"孔雀王朝国王，基本统一印度，弘扬佛教。 出处：吴于廑、齐世荣《世界史·古代史编》"}]},{"type":"list","title":"延伸阅读","items":["种姓制度：分为婆罗门（祭司）、刹帝利（武士）、吠舍（平民）、首陀罗（劳动者）四个等级，另有「不可接触者」贱民。等级世袭，界限森严。 出处：2024 部编版九上第 3 课","佛教的创立：公元前 6 世纪，乔达摩·悉达多创立佛教，主张「众生平等」，反对种姓制度。公元前 3 世纪阿育王定佛教为国教，派人到周边国家传教。 出处：吴于廑、齐世荣《世界史·古代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 3 课；吴于廑、齐世荣《世界史·古代史编》","《大唐西域记》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】倘自由民损毁任何自由民之眼，则应毁其眼。倘自由民击落与之同等之自由民之齿，则应击落其齿。——《汉谟拉比法典》\n【材料二】雅利安人进入印度后，逐渐形成严格的等级制度：第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗，由被征服者、贫困破产失去土地的人构成。此外还有被称为「不可接触者」的贱民。\n【材料三】公元前 6 世纪，乔达摩·悉达多创立佛教。佛教提出「众生平等」，反对婆罗门的特权地位；同时又宣扬「忍耐顺从」，认为人生皆苦，只有刻苦修行才能摆脱苦难。公元前 3 世纪后，佛教开始向外传播；公元前 1 世纪，佛教经中亚传入中国。","source":"材料研读 · 古代亚非文明：大河流域的早期国家"}],"questions":[{"id":"h9a-u1-m1-q2","type":"short","stem":"（2）依据材料二、三，说明佛教为什么能在古印度产生并得到广泛传播，并结合所学指出佛教传入中国的时间。（6 分）","answer":"产生与传播的原因：①种姓制度下婆罗门特权突出、等级森严，吠舍、首陀罗等广大群众深受压迫，社会矛盾尖锐；②佛教提出「众生平等」，反对婆罗门的特权地位，反映了被压迫群众的要求，得到民众支持；③佛教宣扬「忍耐顺从」，有利于统治者维护统治秩序，因而得到统治者的扶植；④公元前 3 世纪以后统治者大力向外推广。传入中国的时间：公元前 1 世纪（西汉末年），经中亚传入中国。","explain":"","tags":["种姓制度","佛教","中外交流"],"rubric":["答出种姓制度造成等级压迫或社会矛盾尖锐","答出「众生平等」、反对婆罗门特权","答出「忍耐顺从」适应统治需要","答出统治者扶植或向外推广","答出公元前 1 世纪（西汉末年）传入中国"]},{"id":"h9a-u1-q3","type":"choice","stem":"古印度种姓制度中，掌管祭祀、被视为最高等级的是","answer":"A","explain":"种姓制度第一等级是婆罗门，掌管祭祀；第二等级是刹帝利，掌管军政大权；第三等级是吠舍，从事农业、畜牧业和商业；第四等级是首陀罗。","options":["婆罗门","刹帝利","吠舍","首陀罗"],"tags":["种姓制度","历史解释"]},{"id":"h9a-u1-q4","type":"choice","stem":"佛教创立的时间和地区是","answer":"A","explain":"公元前 6 世纪，乔达摩·悉达多（释迦牟尼）在古印度创立佛教，提出「众生平等」，反对婆罗门的特权地位。","options":["公元前 6 世纪的古印度","公元前 6 世纪的两河流域","公元前 3 世纪的古埃及","公元前 1 世纪的古罗马"],"tags":["佛教","时空观念"]},{"id":"h9a-u1-q6","type":"choice","stem":"下列古代文明与其产生地区的搭配，错误的一项是","answer":"D","explain":"古希腊文明属于海洋文明，发源于爱琴海地区（希腊半岛、爱琴海诸岛和小亚细亚西岸），与尼罗河流域无关。其余三项搭配都正确。","options":["古埃及——尼罗河流域","古巴比伦——两河流域","古印度——印度河流域","古希腊——尼罗河流域"],"tags":["文明类型","时空观念"]},{"id":"cat-9a-1-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 雅利安人进入南亚次大陆，逐渐建立国家\n② 乔达摩·悉达多（释迦牟尼）在古印度创立佛教\n③ 佛教经中亚传入中国（西汉末年）","answer":"A","explain":"按时间顺序应为：①雅利安人进入南亚次大陆，逐渐建立国家（约公元前 1500 年）→②乔达摩·悉达多（释迦牟尼）在古印度创立佛教（公元前 6 世纪）→③佛教经中亚传入中国（西汉末年）（公元前 1 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-3-g2","type":"choice","stem":"下列关于「古代印度」的表述，错误的是","answer":"A","explain":"把种姓制度与佛教的创立顺序记反，或认为佛教维护种姓制度——但要注意：佛教反对的是婆罗门特权，并不主张取消等级社会，其「忍耐顺从」的说教仍有利于统治者，所以后来得到统治者大力扶植。正确表述：种姓制度约在公元前 1500 年雅利安人进入南亚后逐渐形成，佛教创立于公元前 6 世纪，主张「众生平等」，是反对婆罗门特权的。","options":["把种姓制度与佛教的创立顺序记反，或认为佛教维护种姓制度。","种姓制度约在公元前 1500 年雅利安人进入南亚后逐渐形成，佛教创立于公元前 6 世纪，主张「众生平等」，是反对婆罗门特权的。","古巴比伦的《汉谟拉比法典》、古印度的种姓制度都服务于奴隶主阶级的统治，说明早期国家的法律与制度都是维护统治阶级利益的工具。","佛教于公元前 1 世纪（西汉末年）经中亚传入中国，说明古代亚非文明之间的交流早于新航路开辟，文明从来不是彼此隔绝的。"],"difficulty":2,"tags":["九年级上册","第一单元","本课练习"]},{"id":"cat-9a-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：分为婆罗门（祭司）、刹帝利（武士）、吠舍（平民）、首陀罗（劳动者）四个等级，另有「不可接触者」贱民。等级世袭，界限森严。（2024 部编版九上第 3 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代印度；古印度种姓制度把居民分为婆罗门、刹帝利、吠舍、首陀罗四个等级，等级之间界限森严、世代相袭。","explain":"材料出自2024 部编版九上第 3 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-2-1","title":"第4课 希腊城邦和亚历山大帝国","subtitle":"九年级上册 · 第二单元 古代欧洲文明","grade":"9a","tags":["九年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第二单元 古代欧洲文明"},{"k":"课时","v":"第4课 希腊城邦和亚历山大帝国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"古希腊文明兴起于爱琴海地区，城邦林立，雅典和斯巴达最为著名。雅典在伯里克利时期民主政治发展到高峰。公元前 4 世纪，马其顿崛起，亚历山大东征，建立地跨欧亚非三洲的大帝国。"},{"type":"note","title":"本课主线 · 因果链","text":"希腊以「小国寡民」的城邦立国，雅典在伯里克利时代把公民民主推向高峰；马其顿的亚历山大东征把希腊文化带到东方。罗马则由城邦发展为共和国、再到横跨欧亚非三洲的帝国，用法律与行省制度维系统治，最终在日耳曼人的打击下灭亡。希腊是西方文明的源头，罗马是它的继承者与传播者。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 1000 年","罗马城邦在意大利半岛中部的台伯河畔逐渐兴起","罗马文明属于海洋文明中的陆地扩张型，与希腊城邦不同"],["公元前 8 世纪","希腊出现众多城邦，最著名的是雅典和斯巴达","城邦的突出特点是「小国寡民」，公民与非公民界限分明"],["公元前 5 世纪后半期","伯里克利主政时期，雅典奴隶制民主政治发展到高峰","此时中国进入战国时期（前 475 年起），百家争鸣兴起 · 重点"],["公元前 334 年","亚历山大开始东征","马其顿国王亚历山大率军进攻波斯帝国，此后建立了地跨欧亚非三洲的大帝国"],["公元前 330 年","亚历山大灭亡波斯帝国；公元前 323 年亚历山大病逝，帝国分裂","东征具有两面性：给东方人民带来灾难，也促进了东西方文化的大交汇"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"约公元前 1000 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"罗马城邦在意大利半岛中部的台伯河畔逐…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"公元前 8 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"希腊出现众多城邦，最著名的是雅典和斯…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"公元前 5 世纪后半期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"伯里克利主政时期，雅典奴隶制民主政治…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"公元前 334 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"亚历山大开始东征","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 330 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"亚历山大灭亡波斯帝国；公元前 323…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"雅典民主政治在伯里克利时期达到高峰，但只有成年男性公民享有政治权利，妇女、奴隶和外邦人被排除在外。","explain":"这是本单元最爱考也最爱错的一条。答题要会写：「雅典的民主政治是奴隶主阶级的民主，是成年男性公民的民主，具有明显的阶级性和局限性。」"},{"level":"重点","text":"亚历山大东征具有两面性：一方面给东方人民带来巨大灾难，另一方面促进了东西方文化的大交汇。","explain":"评价类题目必须「一分为二」，先说灾难（掠夺、奴役、杀戮），再说客观积极作用（文化交流、希腊化时代）。"},{"level":"重点","text":"希腊罗马古典文化成就：希腊有《荷马史诗》、帕特农神庙、德谟克利特的原子论、苏格拉底与亚里士多德；罗马有大竞技场、万神殿、引水道工程和儒略历。","explain":"常以「作品/建筑—所属文明」配对题出现，注意区分希腊与罗马：帕特农神庙属希腊，大竞技场、万神殿属罗马。"},{"level":"次重点","text":"希腊城邦的突出特点是「小国寡民」、独立自主；斯巴达实行寡头政治、崇尚武力，雅典实行民主政治。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["雅典民主政治是成年男性公民的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。"],["把亚历山大东征评价为「纯粹的侵略战争，没有任何积极作用」。","东征给东方人民带来了巨大灾难，但客观上促进了东西方文化的大交汇，具有两面性。","「一分为二」是评价历史事件的基本方法，只说一面会丢分。"]]},{"type":"table","title":"雅典民主政治与秦朝中央集权制度（中外对比：同一时期两种截然不同的政治制度）","head":["比较项","雅典（公元前 5 世纪后半期）","中国秦朝（公元前 221—前 207 年）"],"rows":[["权力归属","政权掌握在全体公民（成年男性公民）手中","一切权力集中于皇帝一人"],["主要机构","公民大会是最高权力机构，还有议事会、陪审法庭","皇帝之下设三公九卿，地方设郡县"],["官员产生","抽签选举、轮流执政，公职人员领取津贴","由皇帝直接任免，不世袭"],["参与范围","仅限于成年男性公民，妇女、奴隶、外邦人无权","臣民皆受统治，无参政权利"],["实质","奴隶主阶级的民主，具有阶级局限性","君主专制，服务于封建（秦为奴隶制向封建过渡）统治"],["共同点","都是当时历史条件下形成的、适应本国国情的政治制度","同左"]]},{"type":"table","title":"斯巴达与雅典：同是城邦，两种政治（希腊城邦内部的横向比较）","head":["比较项","斯巴达","雅典"],"rows":[["政治体制","寡头政治，少数贵族掌权","民主政治，公民参与国家管理"],["社会风尚","崇尚武力，重视军事训练","重视文化教育与公共生活"],["公民生活","公民终生从军，农业由希洛人耕种","公民参与公民大会、陪审法庭，享有津贴"],["共同特点","都是小国寡民的城邦，公民与非公民界限分明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度比较与史料解读","给出伯里克利关于民主政治的演说，要求说明雅典民主的范围与局限。答题必须点出「成年男性公民」和「妇女、奴隶、外邦人无权」，这是稳定性最高的得分点。"],["法律文献的纵向串联","把《十二铜表法》《罗马民法大全》与近代《拿破仑法典》放在一起考「西方法制传统的源流」，要求按时间排序并说明各自地位。"],["文明交流与战争评价","以亚历山大东征或罗马扩张为材料，考查「暴力交往在客观上促进了文化交流」，注意既要写灾难，也要写客观作用。"],["中外同期联动","把雅典民主、亚历山大东征与战国、秦朝放在同一年代尺上，考查学生能否在时间坐标中定位中国，这是近年常出现的「时空观念」题型。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：雅典民主的局限；语文：希腊神话与史诗。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["认识你自己","刻于德尔斐阿波罗神庙的箴言，成为古希腊哲学的重要命题。","2024 部编版九上第 4 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"伯里克利","v":"雅典政治家，推动民主政治发展到高峰。 出处：修昔底德《伯罗奔尼撒战争史》"},{"k":"亚历山大","v":"马其顿国王，东征建立大帝国。 出处：吴于廑、齐世荣《世界史·古代史编》"}]},{"type":"list","title":"延伸阅读","items":["雅典民主：伯里克利时期，公民大会是最高权力机构，抽签选举、轮流坐庄，发放陪审津贴。但妇女、外邦人和奴隶没有政治权利。 出处：2024 部编版九上第 4 课；修昔底德《伯罗奔尼撒战争史》","亚历山大东征：公元前 334—前 324 年，亚历山大率军东征，灭波斯帝国，兵锋直抵印度河流域，建立地跨欧亚非三洲的帝国。东征具有侵略性质，也促进了东西方文化交流。 出处：吴于廑、齐世荣《世界史·古代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 4 课；修昔底德《伯罗奔尼撒战争史》","吴于廑、齐世荣《世界史·古代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】我们的制度之所以被称为民主政治，是因为政权是在全体公民手中，而不是在少数人手中。……一个公民只要有任何长处，他就会受到提拔，担任公职；这是作为对他优点的奖赏，跟特权是两码事。——伯里克利在阵亡将士葬礼上的演说\n【材料二】在雅典，公民大会每十天左右召开一次，凡年满 20 岁的男性公民都可参加，在会上可以自由发言、投票表决。但妇女、奴隶和外邦人都没有政治权利，不能参加公民大会。\n【材料三】亚历山大每征服一个地方，就在那里建立城市，其中不少城市成为希腊文化传播的中心。他的部下把希腊的雕塑、戏剧、哲学带到了东方，同时也把东方的天文、数学知识带回希腊世界。","source":"材料研读 · 古代欧洲文明：希腊城邦、罗马帝国与古典文化"}],"questions":[{"id":"h9a-u2-m1-q1","type":"short","stem":"（1）材料一中伯里克利所说的「全体公民」实际上指哪些人？据此说明雅典民主政治的实质。（5 分）","answer":"实际指成年男性公民。雅典的妇女、奴隶和外邦人被排斥在公民之外，没有任何政治权利，不能参加公民大会，也不能担任公职。因此雅典的民主政治只是成年男性公民的民主，是奴隶主阶级的民主，具有明显的阶级性和局限性，而不是全体居民的民主。","explain":"","tags":["雅典民主","史料实证"],"rubric":["答出「成年男性公民」","答出妇女、奴隶、外邦人无权","答出「奴隶主阶级的民主」","答出民主的范围狭小或具有局限性"]},{"id":"h9a-u2-m1-q2","type":"short","stem":"（2）依据材料三，指出亚历山大东征对东西方文化交流产生的影响，并说明应如何全面评价亚历山大东征。（5 分）","answer":"影响：亚历山大东征建立了地跨欧亚非三洲的大帝国，沿途建立的城市成为希腊文化传播的中心，把希腊的雕塑、戏剧、哲学传到东方，也把东方的天文、数学知识带回希腊世界，促进了东西方文化的大交汇。全面评价：一方面，东征是侵略战争，给东方人民带来了巨大灾难（掠夺财富、奴役人民、屠杀反抗者）；另一方面，东征在客观上打通了东西方交通，促进了东西方经济文化的交流，因此要一分为二地评价。","explain":"","tags":["亚历山大东征","历史解释"],"rubric":["答出东征促进东西方文化交汇","答出希腊文化东传或东方文化西传的具体表现","答出东征的侵略性与给东方人民带来的灾难","答出「一分为二」的评价方法"]},{"id":"h9a-u2-q1","type":"choice","stem":"伯里克利主政时期，雅典的民主政治发展到高峰。雅典民主政治的实质是","answer":"B","explain":"雅典的成年男性公民才有权参加公民大会、担任公职；妇女、奴隶和外邦人被排斥在外，因此它本质上是奴隶主阶级的民主，具有明显的阶级局限性。","options":["全体雅典居民的民主","成年男性公民的民主，即奴隶主阶级的民主","全体自由民的民主","妇女与奴隶同样享有权利的民主"],"tags":["雅典民主","历史解释"]},{"id":"h9a-u2-q4","type":"choice","stem":"对亚历山大东征的评价，最恰当的是","answer":"B","explain":"东征使东方人民饱受掠夺、奴役之苦，但在客观上打通了东西方交通，促进了东西方文化的大交汇，因此要一分为二地评价。C 项是布匿战争的结果，D 项是伯里克利时期的成就。","options":["只是一场侵略战争，没有任何积极作用","给东方人民带来巨大灾难，但客观上促进了东西方文化的大交汇","使罗马成为整个地中海地区的霸主","使希腊的民主政治发展到高峰"],"tags":["亚历山大东征","历史解释"]},{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 希腊出现众多城邦，最著名的是雅典和斯巴达\n③ 伯里克利主政时期，雅典奴隶制民主政治发展到高峰\n④ 亚历山大开始东征","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②希腊出现众多城邦，最著名的是雅典和斯巴达（公元前 8 世纪）→③伯里克利主政时期，雅典奴隶制民主政治发展到高峰（公元前 5 世纪后半期）→④亚历山大开始东征（公元前 334 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g2","type":"choice","stem":"下列关于「希腊城邦和亚历山大帝国」的表述，错误的是","answer":"A","explain":"认为雅典的民主政治是全体雅典居民（或全体自由民）的民主——选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。正确表述：雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","options":["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","雅典民主政治是成年男性公民的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g3","type":"choice","stem":"下列结论中，属于「希腊城邦和亚历山大帝国」的是","answer":"A","explain":"本课结论：雅典民主政治是成年男性公民的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["雅典民主政治是成年男性公民的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","中外联动：公元前 221 年秦朝建立统一的中央集权帝国，同期罗马还在共和国阶段；到公元 2 世纪罗马帝国全盛时，中国正值东汉，两大帝国通过丝绸之路有了间接的经济文化交流（东汉时「大秦王安敦」遣使来华）。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：伯里克利时期，公民大会是最高权力机构，抽签选举、轮流坐庄，发放陪审津贴。但妇女、外邦人和奴隶没有政治权利。（2024 部编版九上第 4 课；修昔底德《伯罗奔尼撒战争史》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"希腊城邦和亚历山大帝国；雅典民主政治在伯里克利时期达到高峰，但只有成年男性公民享有政治权利，妇女、奴隶和外邦人被排除在外。","explain":"材料出自2024 部编版九上第 4 课；修昔底德《伯罗奔尼撒战争史》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-2-2","title":"第5课 罗马城邦和罗马帝国","subtitle":"九年级上册 · 第二单元 古代欧洲文明","grade":"9a","tags":["九年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第二单元 古代欧洲文明"},{"k":"课时","v":"第5课 罗马城邦和罗马帝国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"罗马城邦兴起于意大利半岛台伯河畔。公元前 509 年，罗马建立共和国，由元老院和两名执政官掌握权力。经过长期扩张，公元前 2 世纪罗马成为地中海霸主。公元前 27 年，屋大维建立元首制，罗马进入帝国时期。"},{"type":"note","title":"本课主线 · 因果链","text":"希腊以「小国寡民」的城邦立国，雅典在伯里克利时代把公民民主推向高峰；马其顿的亚历山大东征把希腊文化带到东方。罗马则由城邦发展为共和国、再到横跨欧亚非三洲的帝国，用法律与行省制度维系统治，最终在日耳曼人的打击下灭亡。希腊是西方文明的源头，罗马是它的继承者与传播者。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["约公元前 1000 年","罗马城邦在意大利半岛中部的台伯河畔逐渐兴起","罗马文明属于海洋文明中的陆地扩张型，与希腊城邦不同"],["公元前 509 年","罗马建立共和国","元老院掌握决策权，两名执政官由公民大会选举产生；与西周（前 771 年结束）之后的中国春秋时期大致同期 · 重点"],["公元前 450 年左右","罗马颁布《十二铜表法》","罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源 · 重点"],["公元前 334 年","亚历山大开始东征","马其顿国王亚历山大率军进攻波斯帝国，此后建立了地跨欧亚非三洲的大帝国"],["公元前 330 年","亚历山大灭亡波斯帝国；公元前 323 年亚历山大病逝，帝国分裂","东征具有两面性：给东方人民带来灾难，也促进了东西方文化的大交汇"],["公元前 3 世纪初—前 2 世纪","罗马统一意大利半岛，经过布匿战争成为整个地中海地区的霸主","布匿战争是与迦太基的三次战争；公元前 73 年斯巴达克发动奴隶起义"],["公元前 27 年","屋大维开始独揽国家大权，罗马帝国建立","他采用「元首制」的统治形式，实际是披着共和外衣的君主专制 · 重点"],["2 世纪","罗马帝国进入全盛时期，地跨欧亚非三洲，地中海成为它的「内湖」","此时中国处于东汉时期，两大帝国通过丝绸之路有了间接往来"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"约公元前 1000 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"罗马城邦在意大利半岛中部的台伯河畔逐…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"公元前 509 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"罗马建立共和国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"公元前 450 年左右","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"罗马颁布《十二铜表法》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"公元前 334 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"亚历山大开始东征","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"公元前 330 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"亚历山大灭亡波斯帝国；公元前 323…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"公元前 3 世纪初—前 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"罗马统一意大利半岛，经过布匿战争成为…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 27 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"屋大维开始独揽国家大权，罗马帝国建立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"《十二铜表法》的颁布使罗马有了成文法，是罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源。","explain":"要能把罗马法的发展脉络串起来：《十二铜表法》（成文法开端）→ 公民法与万民法 → 《罗马民法大全》（民法基础），这条链条与第 3 单元的拜占庭合起来考。"},{"level":"重点","text":"希腊罗马古典文化成就：希腊有《荷马史诗》、帕特农神庙、德谟克利特的原子论、苏格拉底与亚里士多德；罗马有大竞技场、万神殿、引水道工程和儒略历。","explain":"常以「作品/建筑—所属文明」配对题出现，注意区分希腊与罗马：帕特农神庙属希腊，大竞技场、万神殿属罗马。"},{"level":"次重点","text":"罗马共和国时期，元老院掌握国家决策权，两名执政官主持日常政务，公民大会是形式上的最高权力机关。","explain":""},{"level":"选择题","text":"罗马帝国在 3 世纪以后陷入政治腐败、经济危机与外族入侵的困境，最终分裂并走向灭亡。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","中外联动：公元前 221 年秦朝建立统一的中央集权帝国，同期罗马还在共和国阶段；到公元 2 世纪罗马帝国全盛时，中国正值东汉，两大帝国通过丝绸之路有了间接的经济文化交流（东汉时「大秦王安敦」遣使来华）。","中国以郡县制、文书行政维系大一统，罗马以行省制与法律体系维系庞大疆域，治理方式不同，但都说明大国的稳定需要有效的制度与法律。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《十二铜表法》与《罗马民法大全》混为一谈，或把《十二铜表法》当成罗马帝国的法律。","《十二铜表法》颁布于公元前 450 年左右的罗马共和国时期；《罗马民法大全》是公元 6 世纪拜占庭帝国查士丁尼在位时编成的。","两者相差近千年，前者是罗马法制建设的第一步，后者奠定了欧洲民法的基础。"],["看到「476 年西罗马帝国灭亡」就认为罗马帝国就此终结。","西罗马帝国灭亡后，东罗马帝国（拜占庭帝国）继续存在，直到 1453 年被奥斯曼帝国灭亡。","476 年标志的是西欧奴隶社会的结束，而不是整个罗马文明的终结。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度比较与史料解读","给出伯里克利关于民主政治的演说，要求说明雅典民主的范围与局限。答题必须点出「成年男性公民」和「妇女、奴隶、外邦人无权」，这是稳定性最高的得分点。"],["法律文献的纵向串联","把《十二铜表法》《罗马民法大全》与近代《拿破仑法典》放在一起考「西方法制传统的源流」，要求按时间排序并说明各自地位。"],["文明交流与战争评价","以亚历山大东征或罗马扩张为材料，考查「暴力交往在客观上促进了文化交流」，注意既要写灾难，也要写客观作用。"],["中外同期联动","把雅典民主、亚历山大东征与战国、秦朝放在同一年代尺上，考查学生能否在时间坐标中定位中国，这是近年常出现的「时空观念」题型。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：雅典民主的局限；语文：希腊神话与史诗。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["条条大路通罗马","形容罗马道路网发达，后比喻达到目的的方式多种多样。","2024 部编版九上第 5 课"],["罗马不是一天建成的","西方谚语，比喻伟大事业需要长期积累。","西方传统谚语"]]},{"type":"kv","title":"人物卡片","items":[{"k":"屋大维","v":"罗马帝国首位皇帝，公元前 27 年获「奥古斯都」称号。 出处：吴于廑、齐世荣《世界史·古代史编》"}]},{"type":"list","title":"延伸阅读","items":["从共和国到帝国：共和国后期，内战频仍，凯撒、屋大维相继崛起。公元前 27 年屋大维获「奥古斯都」称号，元首制确立，共和国名存实亡。 出处：吴于廑、齐世荣《世界史·古代史编》","罗马的分裂与灭亡：395 年罗马帝国分裂为东西两部分；476 年西罗马帝国在日耳曼人打击下灭亡，标志西欧奴隶社会结束。 出处：2024 部编版九上第 5 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 5 课；吴于廑、齐世荣《世界史·古代史编》","《罗马史》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u2-q2","type":"choice","stem":"罗马共和国时期，掌握国家决策权的机构是","answer":"B","explain":"罗马共和国时期，国家统治的决策权掌握在由贵族组成的元老院手中；两名权力相等的执政官主持日常政务，公民大会是形式上的最高权力机关。","options":["执政官","元老院","公民大会","保民官"],"tags":["罗马共和国","历史解释"]},{"id":"h9a-u2-q3","type":"choice","stem":"被称为罗马法制建设第一步、后世罗马法典乃至欧洲法学渊源的文献是","answer":"B","explain":"公元前 450 年左右，罗马颁布了刻在 12 块青铜板上的《十二铜表法》，使量刑定罪有了成文依据，是罗马法制建设的第一步，也是后世罗马法典乃至欧洲法学的渊源。","options":["《汉谟拉比法典》","《十二铜表法》","《罗马民法大全》","《拿破仑法典》"],"tags":["《十二铜表法》","时空观念"]},{"id":"h9a-u2-q4","type":"choice","stem":"对亚历山大东征的评价，最恰当的是","answer":"B","explain":"东征使东方人民饱受掠夺、奴役之苦，但在客观上打通了东西方交通，促进了东西方文化的大交汇，因此要一分为二地评价。C 项是布匿战争的结果，D 项是伯里克利时期的成就。","options":["只是一场侵略战争，没有任何积极作用","给东方人民带来巨大灾难，但客观上促进了东西方文化的大交汇","使罗马成为整个地中海地区的霸主","使希腊的民主政治发展到高峰"],"tags":["亚历山大东征","历史解释"]},{"id":"h9a-u2-q5","type":"choice","stem":"公元前 27 年，罗马发生的重要事件是","answer":"B","explain":"公元前 27 年，屋大维开始独揽国家大权，采用「元首制」的统治形式，罗马帝国由此建立。共和国建立是公元前 509 年，帝国分裂是 395 年。","options":["建立共和国","屋大维开始独揽国家大权，罗马帝国建立","帝国分裂为东西两部分","灭掉迦太基"],"tags":["罗马帝国","时空观念"]},{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 罗马建立共和国\n③ 罗马颁布《十二铜表法》\n④ 亚历山大开始东征","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②罗马建立共和国（公元前 509 年）→③罗马颁布《十二铜表法》（公元前 450 年左右）→④亚历山大开始东征（公元前 334 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-2-g2","type":"choice","stem":"下列关于「罗马城邦和罗马帝国」的表述，错误的是","answer":"A","explain":"把《十二铜表法》与《罗马民法大全》混为一谈，或把《十二铜表法》当成罗马帝国的法律——两者相差近千年，前者是罗马法制建设的第一步，后者奠定了欧洲民法的基础。正确表述：《十二铜表法》颁布于公元前 450 年左右的罗马共和国时期；《罗马民法大全》是公元 6 世纪拜占庭帝国查士丁尼在位时编成的。","options":["把《十二铜表法》与《罗马民法大全》混为一谈，或把《十二铜表法》当成罗马帝国的法律。","《十二铜表法》颁布于公元前 450 年左右的罗马共和国时期；《罗马民法大全》是公元 6 世纪拜占庭帝国查士丁尼在位时编成的。","希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：共和国后期，内战频仍，凯撒、屋大维相继崛起。公元前 27 年屋大维获「奥古斯都」称号，元首制确立，共和国名存实亡。（吴于廑、齐世荣《世界史·古代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"罗马城邦和罗马帝国；《十二铜表法》的颁布使罗马有了成文法，是罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源。","explain":"材料出自吴于廑、齐世荣《世界史·古代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-2-3","title":"第6课 希腊罗马古典文化","subtitle":"九年级上册 · 第二单元 古代欧洲文明","grade":"9a","tags":["九年级上册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第二单元 古代欧洲文明"},{"k":"课时","v":"第6课 希腊罗马古典文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"古希腊罗马文化是西方文明的源头之一。《荷马史诗》是古希腊最早的文学成就；帕特农神庙是雅典建筑艺术的代表；亚里士多德是古希腊哲学的集大成者。罗马法从《十二铜表法》发展到《万民法》，影响深远。"},{"type":"note","title":"本课主线 · 因果链","text":"希腊以「小国寡民」的城邦立国，雅典在伯里克利时代把公民民主推向高峰；马其顿的亚历山大东征把希腊文化带到东方。罗马则由城邦发展为共和国、再到横跨欧亚非三洲的帝国，用法律与行省制度维系统治，最终在日耳曼人的打击下灭亡。希腊是西方文明的源头，罗马是它的继承者与传播者。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["约公元前 1000 年","罗马城邦在意大利半岛中部的台伯河畔逐渐兴起","罗马文明属于海洋文明中的陆地扩张型，与希腊城邦不同"],["公元前 8 世纪","希腊出现众多城邦，最著名的是雅典和斯巴达","城邦的突出特点是「小国寡民」，公民与非公民界限分明"],["公元前 509 年","罗马建立共和国","元老院掌握决策权，两名执政官由公民大会选举产生；与西周（前 771 年结束）之后的中国春秋时期大致同期 · 重点"],["公元前 450 年左右","罗马颁布《十二铜表法》","罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源 · 重点"],["公元前 5 世纪后半期","伯里克利主政时期，雅典奴隶制民主政治发展到高峰","此时中国进入战国时期（前 475 年起），百家争鸣兴起 · 重点"],["公元前 334 年","亚历山大开始东征","马其顿国王亚历山大率军进攻波斯帝国，此后建立了地跨欧亚非三洲的大帝国"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"约公元前 1000 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"罗马城邦在意大利半岛中部的台伯河畔逐…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"公元前 8 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"希腊出现众多城邦，最著名的是雅典和斯…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"公元前 509 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"罗马建立共和国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"公元前 450 年左右","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"罗马颁布《十二铜表法》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"公元前 5 世纪后半期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"伯里克利主政时期，雅典奴隶制民主政治…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"公元前 334 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"亚历山大开始东征","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"《十二铜表法》的颁布使罗马有了成文法，是罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源。","explain":"要能把罗马法的发展脉络串起来：《十二铜表法》（成文法开端）→ 公民法与万民法 → 《罗马民法大全》（民法基础），这条链条与第 3 单元的拜占庭合起来考。"},{"level":"重点","text":"希腊罗马古典文化成就：希腊有《荷马史诗》、帕特农神庙、德谟克利特的原子论、苏格拉底与亚里士多德；罗马有大竞技场、万神殿、引水道工程和儒略历。","explain":"常以「作品/建筑—所属文明」配对题出现，注意区分希腊与罗马：帕特农神庙属希腊，大竞技场、万神殿属罗马。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。"],["把亚历山大东征评价为「纯粹的侵略战争，没有任何积极作用」。","东征给东方人民带来了巨大灾难，但客观上促进了东西方文化的大交汇，具有两面性。","「一分为二」是评价历史事件的基本方法，只说一面会丢分。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度比较与史料解读","给出伯里克利关于民主政治的演说，要求说明雅典民主的范围与局限。答题必须点出「成年男性公民」和「妇女、奴隶、外邦人无权」，这是稳定性最高的得分点。"],["法律文献的纵向串联","把《十二铜表法》《罗马民法大全》与近代《拿破仑法典》放在一起考「西方法制传统的源流」，要求按时间排序并说明各自地位。"],["文明交流与战争评价","以亚历山大东征或罗马扩张为材料，考查「暴力交往在客观上促进了文化交流」，注意既要写灾难，也要写客观作用。"],["中外同期联动","把雅典民主、亚历山大东征与战国、秦朝放在同一年代尺上，考查学生能否在时间坐标中定位中国，这是近年常出现的「时空观念」题型。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：雅典民主的局限；语文：希腊神话与史诗。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["阿基米德与「尤里卡」","传说阿基米德在浴盆中悟出浮力原理，高呼「尤里卡」（我发现了），后成为发现真理的代称。","2024 部编版九上第 6 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"荷马","v":"古希腊盲诗人，相传为《荷马史诗》作者。 出处：《荷马史诗》"},{"k":"亚里士多德","v":"古希腊哲学家、科学家，著作涵盖逻辑学、物理学、伦理学等。 出处：吴于廑、齐世荣《世界史·古代史编》"}]},{"type":"list","title":"延伸阅读","items":["《荷马史诗》：包括《伊利亚特》和《奥德赛》，相传为盲诗人荷马所作，描写特洛伊战争及英雄返乡的故事。 出处：《荷马史诗》","罗马法：公元前 450 年颁布《十二铜表法》，是罗马第一部成文法；帝国时期形成适用于各民族居民的《万民法》。 出处：吴于廑、齐世荣《世界史·古代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 6 课；《荷马史诗》","吴于廑、齐世荣《世界史·古代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u2-q6","type":"choice","stem":"下列希腊罗马古典文化成就与其所属文明的搭配，错误的一项是","answer":"D","explain":"《天方夜谭》（《一千零一夜》）是阿拉伯文学的瑰宝，属于阿拉伯文化，与古罗马无关。儒略历由罗马统治者凯撒命人以古埃及太阳历为蓝本编制。","options":["《荷马史诗》——古希腊","帕特农神庙——古希腊","儒略历——古罗马","《天方夜谭》——古罗马"],"tags":["古典文化","史料实证"]},{"id":"cat-9a-2-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 罗马城邦在意大利半岛中部的台伯河畔逐渐兴起\n② 希腊出现众多城邦，最著名的是雅典和斯巴达\n③ 罗马建立共和国\n④ 罗马颁布《十二铜表法》","answer":"A","explain":"按时间顺序应为：①罗马城邦在意大利半岛中部的台伯河畔逐渐兴起（约公元前 1000 年）→②希腊出现众多城邦，最著名的是雅典和斯巴达（公元前 8 世纪）→③罗马建立共和国（公元前 509 年）→④罗马颁布《十二铜表法》（公元前 450 年左右）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-3-g2","type":"choice","stem":"下列关于「希腊罗马古典文化」的表述，错误的是","answer":"A","explain":"认为雅典的民主政治是全体雅典居民（或全体自由民）的民主——选择题常把「公民」偷换成「居民」「自由民」。记住：雅典的「公民」是一个有严格条件限制的群体。正确表述：雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","options":["认为雅典的民主政治是全体雅典居民（或全体自由民）的民主。","雅典只有成年男性公民享有政治权利；妇女、奴隶、外邦人都被排斥在外。","罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","《十二铜表法》的颁布使罗马有了成文法，是罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-3-g3","type":"choice","stem":"下列结论中，属于「希腊罗马古典文化」的是","answer":"A","explain":"本课结论：罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["罗马法的发展体现了「从习惯法到成文法、从公民法到万民法」的进步，是欧洲法学的渊源，对近代欧洲乃至世界法律体系影响深远。","雅典民主政治是成年男性公民的民主，是奴隶主阶级的民主，妇女、奴隶、外邦人没有任何政治权利；它既是雅典繁荣的重要原因，也埋下了直接民主容易导致权力滥用的隐患。","希腊是西方文明的源头，罗马是希腊文化的继承者与传播者，二者共同构成西方古典文明。","中外联动：公元前 221 年秦朝建立统一的中央集权帝国，同期罗马还在共和国阶段；到公元 2 世纪罗马帝国全盛时，中国正值东汉，两大帝国通过丝绸之路有了间接的经济文化交流（东汉时「大秦王安敦」遣使来华）。"],"difficulty":2,"tags":["九年级上册","第二单元","本课练习"]},{"id":"cat-9a-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：包括《伊利亚特》和《奥德赛》，相传为盲诗人荷马所作，描写特洛伊战争及英雄返乡的故事。（《荷马史诗》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"希腊罗马古典文化；《十二铜表法》的颁布使罗马有了成文法，是罗马法制建设的第一步，是后世罗马法典乃至欧洲法学的渊源。","explain":"材料出自《荷马史诗》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-3-1","title":"第7课 基督教的兴起和法兰克王国","subtitle":"九年级上册 · 第三单元 封建时代的欧洲","grade":"9a","tags":["九年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第三单元 封建时代的欧洲"},{"k":"课时","v":"第7课 基督教的兴起和法兰克王国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1 世纪，基督教产生于巴勒斯坦地区。4 世纪末，罗马帝国将基督教定为国教。西罗马灭亡后，日耳曼人建立一系列王国，其中法兰克王国最为强大。800 年，教皇为查理曼加冕，史称「查理大帝」。"},{"type":"note","title":"本课主线 · 因果链","text":"西罗马帝国灭亡后，日耳曼人建立的西欧国家逐渐形成以土地封赐为纽带的封君封臣制，庄园成为自给自足的经济和政治单位，基督教会在西欧社会取得精神统治地位；10 世纪以后城市重新兴起、大学出现，市民阶层成长为早期的资产阶级；东部的拜占庭帝国则以《罗马民法大全》保存并发展了罗马法，最终在 1453 年被奥斯曼帝国灭亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1 世纪","基督教产生于罗马帝国统治下的巴勒斯坦地区","早期主张「忍受苦难，死后可以升入天堂」，遭到罗马统治者的迫害"],["4 世纪末","罗马皇帝将基督教确定为国教","此后基督教在西欧广泛传播，成为中世纪西欧的精神支柱"],["481 年","日耳曼人建立法兰克王国，克洛维是建立者","西罗马帝国灭亡前后，法兰克王国是最强大的日耳曼人国家 · 重点"],["8 世纪前期","法兰克王国改革土地分封形式，实行有条件的土地分封（查理·马特改革）","不再无偿赏赐土地，受到封地的人必须提供兵役服务——封君封臣制由此形成 · 重点"],["800 年","教皇为查理曼加冕，称为「罗马人的皇帝」","史称查理大帝；说明教会与世俗王权相互利用、彼此支撑"],["843 年","查理曼帝国一分为三","此后逐渐形成德意志、法兰西、意大利三个国家的雏形——今日欧洲政治版图的源头 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"基督教产生于罗马帝国统治下的巴勒斯坦…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"4 世纪末","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"罗马皇帝将基督教确定为国教","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"481 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"日耳曼人建立法兰克王国，克洛维是建立…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"8 世纪前期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"法兰克王国改革土地分封形式，实行有条…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"800 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"教皇为查理曼加冕，称为「罗马人的皇帝…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"843 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"查理曼帝国一分为三","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"封君封臣制以土地的封赐为纽带，封君要保护封臣，封臣要效忠封君、服兵役、提供金钱等；其特点是等级森严、权利与义务交织，带有一定的契约意义。","explain":"要能与中国西周分封制比较，并记住那句关键的话：「我的附庸的附庸，不是我的附庸」——说明封君封臣的关系是逐级、双向的，不能越级支配。"},{"level":"次重点","text":"基督教产生于 1 世纪的巴勒斯坦地区，4 世纪末被罗马皇帝定为国教；西罗马帝国灭亡后，教会成为西欧最大的土地所有者与精神统治者。","explain":""},{"level":"选择题","text":"843 年查理曼帝国一分为三，后来形成德意志、法兰西、意大利三个国家的雏形。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」。","西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","两者形式相似、实质不同，比较题必须先分清纽带（土地 / 血缘）与关系特点。"]]},{"type":"table","title":"西欧封君封臣制与中国西周分封制（中外对比：两种「分封」的异同）","head":["比较项","西欧封君封臣制","中国西周分封制"],"rows":[["纽带","土地的封赐（采邑）","血缘关系与功劳"],["双方义务","封君保护封臣，封臣效忠、服兵役、提供金钱","诸侯服从周王调遣、随从作战、缴纳贡赋"],["等级关系","逐级分封、双向义务，「我的附庸的附庸，不是我的附庸」","层层分封，周天子是天下共主"],["结果","形成严格的封建等级，王权相对软弱","初期巩固统治，后期诸侯割据、王室衰微"],["共同点","都以土地为核心、都造成地方势力坐大","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度与契约类材料题","给出封君封臣的权利义务誓词或庄园敕令，要求概括双方的权利义务并说明这一制度的特点，落脚点常在「等级性」「契约性」「以土地为纽带」。"],["「中世纪并不黑暗」的论证","以城市兴起、大学出现、市民阶层形成为材料，要求说明中世纪西欧社会孕育着新的因素，答题按「经济—社会—文化」三条线索组织。"],["法律文献的时间轴","把《十二铜表法》《罗马民法大全》《权利法案》《拿破仑法典》打乱排序并说明地位，考查法制传统的历史传承。"]]},{"type":"note","title":"跨学科视角","text":"地理：欧洲庄园与中世纪城镇分布；道德与法治：契约与权利。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"查理曼","v":"法兰克王国国王，800 年加冕称帝，史称查理大帝。 出处：吴于廑、齐世荣《世界史·中世纪史编》"}]},{"type":"list","title":"延伸阅读","items":["封君封臣制度：封君授予封臣土地，封臣效忠并服兵役，形成层层分封的等级制度，有「我的附庸的附庸不是我的附庸」之说。 出处：2024 部编版九上第 7 课","查理曼的扩张：查理在位期间，法兰克王国扩张到西欧大部分地区。800 年圣诞，教皇利奥三世为其加冕为「罗马人的皇帝」。 出处：吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 7 课；吴于廑、齐世荣《世界史·中世纪史编》","《法兰克人史》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u3-q1","type":"choice","stem":"西欧封君封臣制得以形成的纽带是","answer":"B","explain":"8 世纪前期，法兰克王国改革土地分封形式，不再无偿赏赐土地，受到封地的人必须提供兵役服务，封君封臣制由此形成，其纽带是土地的封赐。","options":["血缘关系","土地的封赐","共同的宗教信仰","军功的大小"],"tags":["封君封臣制","历史解释"]},{"id":"h9a-u3-q6","type":"choice","stem":"843 年查理曼帝国一分为三，后来逐渐形成三个国家的雏形，它们是","answer":"B","explain":"843 年查理曼帝国一分为三，此后逐渐形成德意志、法兰西、意大利三个国家的雏形，这是今日欧洲政治版图的源头之一。","options":["英国、法国、德国","德意志、法兰西、意大利","西班牙、葡萄牙、意大利","英国、荷兰、法国"],"tags":["查理曼帝国","时空观念"]},{"id":"cat-9a-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 基督教产生于罗马帝国统治下的巴勒斯坦地区\n② 罗马皇帝将基督教确定为国教\n③ 日耳曼人建立法兰克王国，克洛维是建立者\n④ 法兰克王国改革土地分封形式，实行有条件的土地分封…","answer":"A","explain":"按时间顺序应为：①基督教产生于罗马帝国统治下的巴勒斯坦地区（1 世纪）→②罗马皇帝将基督教确定为国教（4 世纪末）→③日耳曼人建立法兰克王国，克洛维是建立者（481 年）→④法兰克王国改革土地分封形式，实行有条件的土地分封（查理·马特改革）（8 世纪前期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g2","type":"choice","stem":"下列关于「基督教的兴起和法兰克王国」的表述，错误的是","answer":"A","explain":"把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」——两者形式相似、实质不同，比较题必须先分清纽带（土地 / 血缘）与关系特点。正确表述：西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","options":["把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」。","西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g3","type":"choice","stem":"下列结论中，属于「基督教的兴起和法兰克王国」的是","answer":"A","explain":"本课结论：中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。","拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：封君授予封臣土地，封臣效忠并服兵役，形成层层分封的等级制度，有「我的附庸的附庸不是我的附庸」之说。（2024 部编版九上第 7 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"基督教的兴起和法兰克王国；封君封臣制以土地的封赐为纽带，封君要保护封臣，封臣要效忠封君、服兵役、提供金钱等；其特点是等级森严、权利与义务交织，带有一定的契约意义。","explain":"材料出自2024 部编版九上第 7 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-3-2","title":"第8课 西欧庄园","subtitle":"九年级上册 · 第三单元 封建时代的欧洲","grade":"9a","tags":["九年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第三单元 封建时代的欧洲"},{"k":"课时","v":"第8课 西欧庄园"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"西欧庄园是一种自给自足的经济和政治单位，9 世纪开始流行。庄园土地分为领主自营地和佃户份地，佃户包括自由农民和农奴。庄园设有法庭，处理纠纷。"},{"type":"note","title":"本课主线 · 因果链","text":"西罗马帝国灭亡后，日耳曼人建立的西欧国家逐渐形成以土地封赐为纽带的封君封臣制，庄园成为自给自足的经济和政治单位，基督教会在西欧社会取得精神统治地位；10 世纪以后城市重新兴起、大学出现，市民阶层成长为早期的资产阶级；东部的拜占庭帝国则以《罗马民法大全》保存并发展了罗马法，最终在 1453 年被奥斯曼帝国灭亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["9 世纪—11 世纪","西欧庄园从开始流行到遍布欧洲","庄园是一个独立的自给自足的经济和政治单位，居民有自由农民和缺少自由的农奴"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"西欧庄园是一个独立的自给自足的经济和…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"中世纪的西欧是「封君封臣制 + 庄园…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"西欧庄园是一个独立的自给自足的经济和政治单位：土地分为领主的直领地和农民的份地，居民有自由农民和缺少自由的农奴，庄园法庭起着维护庄园秩序的作用。","explain":"庄园法庭由领主或其管家主持，主要维护领主利益，但也在一定程度上限制领主的专横、维护农民的一些权益，答题要写出这一「两面性」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为庄园法庭只维护领主的利益，与农民毫无关系。","庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","「从材料中概括庄园法庭的作用」这类题，只写一面就会丢掉另一半分值。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度与契约类材料题","给出封君封臣的权利义务誓词或庄园敕令，要求概括双方的权利义务并说明这一制度的特点，落脚点常在「等级性」「契约性」「以土地为纽带」。"],["「中世纪并不黑暗」的论证","以城市兴起、大学出现、市民阶层形成为材料，要求说明中世纪西欧社会孕育着新的因素，答题按「经济—社会—文化」三条线索组织。"],["法律文献的时间轴","把《十二铜表法》《罗马民法大全》《权利法案》《拿破仑法典》打乱排序并说明地位，考查法制传统的历史传承。"]]},{"type":"note","title":"跨学科视角","text":"地理：欧洲庄园与中世纪城镇分布；道德与法治：契约与权利。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["庄园法庭：庄园法庭由领主或其管家主持，处理佃户之间的纠纷，惩罚违法者，维护领主的利益和庄园秩序。 出处：2024 部编版九上第 8 课","农奴的生活：农奴没有人身自由，被束缚在土地上，须为领主服劳役，还要缴纳各种捐税，但有自己的份地和生产工具。 出处：吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 8 课；吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】封臣对封君要忠诚，在封君需要的时候，要无偿地为封君服兵役、提供金钱等；封君对封臣也有义务，封君不能任意侵害封臣的荣誉、人身和财产安全，当封臣受到外来攻击时，封君必须提供保护。——据教材与中世纪誓词摘编\n【材料二】庄园的土地分为两部分：一部分是领主自己保留的「直领地」，由农奴耕种，收入全部归领主；另一部分是农民的「份地」，农民必须先在直领地上无偿劳动若干天，才能耕种自己的份地。庄园设有法庭，由领主或其管家主持，惩罚各种违法行为。\n【材料三】城市居民通过金钱赎买和武力斗争等方式，争取城市的自由和自治。取得自治权的城市，市民可以自由经商、免交赋税，还可以选举市政官员。随着城市的发展和工商业的繁荣，市民阶层逐渐形成，其中分化出富裕的大手工业作坊主、银行家等。","source":"材料研读 · 封建时代的欧洲：基督教、庄园、城市与拜占庭"}],"questions":[{"id":"h9a-u3-m1-q2","type":"short","stem":"（2）依据材料二、三，说明西欧庄园与城市各有什么特点，并结合所学指出城市兴起对欧洲历史发展的影响。（6 分）","answer":"庄园的特点：是一个独立的自给自足的经济和政治单位，土地分为领主直领地和农民份地，农民要为领主无偿劳动，庄园法庭负责维护庄园秩序并惩罚违法行为。城市的特点：居民通过金钱赎买和武力斗争争取自由和自治，市民可以自由经商、免交赋税、选举市政官员。影响：城市工商业的发展使市民阶层逐渐形成并壮大，从中分化出富裕的大手工业作坊主、银行家等，成为早期的资产阶级，为文艺复兴的兴起和资本主义的产生准备了条件。","explain":"","tags":["西欧庄园","中世纪城市","历史解释"],"rubric":["答出庄园自给自足、分为直领地与份地","答出庄园法庭的作用","答出城市争取自由和自治的方式","答出市民阶层壮大","答出早期资产阶级出现","答出为文艺复兴或资本主义兴起准备条件"]},{"id":"h9a-u3-q2","type":"choice","stem":"下列关于西欧庄园的表述，正确的是","answer":"B","explain":"西欧庄园是一个独立的自给自足的经济和政治单位，居民有自由农民和缺少自由的农奴；庄园法庭由领主或其管家主持，领主在庄园内拥有较大权力。","options":["庄园以商品经济为主，产品主要面向市场","庄园是一个独立的自给自足的经济和政治单位","庄园完全由国王直接管理，领主没有权力","庄园里的居民全部是自由农民"],"tags":["西欧庄园","历史解释"]},{"id":"h9a-u3-q3","type":"choice","stem":"中世纪西欧城市居民争取自由和自治权最常用的手段是","answer":"A","explain":"城市居民常用的手段是金钱赎买和武力斗争，法国琅城人民起义争取自治就是典型事例。取得自治权的城市，市民可以自由经商、免交赋税、选举市政官员。","options":["金钱赎买和武力斗争","由议会立法授予","向教皇请愿","依靠庄园法庭判决"],"tags":["中世纪城市","历史解释"]},{"id":"h9a-u3-q5","type":"choice","stem":"被称为「中世纪最美好的花朵」的是","answer":"C","explain":"12 世纪西欧大学兴起，巴黎大学、牛津大学等先后出现，大学享有免赋税特权、司法特权和教育自主权，因此被称为「中世纪最美好的花朵」。","options":["庄园的兴起","城市的兴起","大学的兴起","骑士制度的形成"],"tags":["大学兴起","历史解释"]},{"id":"cat-9a-3-2-g2","type":"choice","stem":"下列关于「西欧庄园」的表述，错误的是","answer":"A","explain":"认为庄园法庭只维护领主的利益，与农民毫无关系——「从材料中概括庄园法庭的作用」这类题，只写一面就会丢掉另一半分值。正确表述：庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","options":["认为庄园法庭只维护领主的利益，与农民毫无关系。","庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","西欧庄园是一个独立的自给自足的经济和政治单位：土地分为领主的直领地和农民的份地，居民有自由农民和缺少自由的农奴，庄园法庭起着维护庄园秩序的作用。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-2-g3","type":"choice","stem":"下列结论中，属于「西欧庄园」的是","answer":"A","explain":"本课结论：中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：庄园法庭由领主或其管家主持，处理佃户之间的纠纷，惩罚违法者，维护领主的利益和庄园秩序。（2024 部编版九上第 8 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西欧庄园；西欧庄园是一个独立的自给自足的经济和政治单位：土地分为领主的直领地和农民的份地，居民有自由农民和缺少自由的农奴，庄园法庭起着维护庄园秩序的作用。","explain":"材料出自2024 部编版九上第 8 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-3-3","title":"第9课 中世纪城市和大学的兴起","subtitle":"九年级上册 · 第三单元 封建时代的欧洲","grade":"9a","tags":["九年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第三单元 封建时代的欧洲"},{"k":"课时","v":"第9课 中世纪城市和大学的兴起"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"10 世纪起，西欧城市重新兴起。市民通过金钱赎买或武装起义争取自治，如法国琅城起义。12 世纪，巴黎大学、牛津大学等相继建立，大学的兴起被认为是欧洲中世纪教育「最美好的花朵」。"},{"type":"note","title":"本课主线 · 因果链","text":"西罗马帝国灭亡后，日耳曼人建立的西欧国家逐渐形成以土地封赐为纽带的封君封臣制，庄园成为自给自足的经济和政治单位，基督教会在西欧社会取得精神统治地位；10 世纪以后城市重新兴起、大学出现，市民阶层成长为早期的资产阶级；东部的拜占庭帝国则以《罗马民法大全》保存并发展了罗马法，最终在 1453 年被奥斯曼帝国灭亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["10 世纪","西欧城市重新兴起","城市居民争取自由和自治，1312 年前后法国琅城人民起义是典型事例"],["12 世纪","西欧大学兴起，巴黎大学、牛津大学等先后出现","大学被称为「中世纪最美好的花朵」，享有免赋税特权、司法特权与教育自主权"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"10 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"西欧城市重新兴起","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"12 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"西欧大学兴起，巴黎大学、牛津大学等先…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"10 世纪以后西欧城市重新兴起，城市居民用金钱赎买和武力斗争等方式争取自由与自治；市民阶层的形成与发展为资本主义的兴起准备了条件。","explain":"要抓住因果链：城市兴起 → 工商业发展 → 市民阶层壮大并分化出富裕作坊主、银行家等 → 早期资产阶级出现 → 为文艺复兴与资本主义的兴起奠定基础。"},{"level":"次重点","text":"大学的兴起是中世纪西欧教育「最美好的花朵」，大学享有免赋税特权、司法特权和教育自主权，但仍受教会与国王的影响。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」。","西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","两者形式相似、实质不同，比较题必须先分清纽带（土地 / 血缘）与关系特点。"],["认为庄园法庭只维护领主的利益，与农民毫无关系。","庄园法庭主要维护领主利益，但也起到限制领主专横、维护庄园公共秩序的作用，农民可以依据习惯法在法庭上维护自己的某些权益。","「从材料中概括庄园法庭的作用」这类题，只写一面就会丢掉另一半分值。"]]},{"type":"table","title":"中世纪西欧城市与中国唐宋城市（中外对比：同一时期城市的不同命运）","head":["比较项","中世纪西欧城市（10 世纪以后）","中国唐宋城市（7—13 世纪）"],"rows":[["兴起原因","农业与手工业发展，工商业者聚居形成城市","农业、手工业与商业发展，坊市格局逐渐打破"],["政治地位","通过金钱赎买、武力斗争取得自由和自治权","始终处于中央集权的行政体系之下，无自治权"],["社会力量","市民阶层壮大，分化出早期资产阶级","商人、市民力量有所发展，但未能形成独立的资产阶级"],["文化","大学兴起，享有教育自主权","书院、科举教育发达，服务于官僚体制"],["历史影响","为文艺复兴与资本主义的兴起准备条件","推动了商品经济繁荣与市民文化发展，但未突破专制体制"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度与契约类材料题","给出封君封臣的权利义务誓词或庄园敕令，要求概括双方的权利义务并说明这一制度的特点，落脚点常在「等级性」「契约性」「以土地为纽带」。"],["「中世纪并不黑暗」的论证","以城市兴起、大学出现、市民阶层形成为材料，要求说明中世纪西欧社会孕育着新的因素，答题按「经济—社会—文化」三条线索组织。"],["法律文献的时间轴","把《十二铜表法》《罗马民法大全》《权利法案》《拿破仑法典》打乱排序并说明地位，考查法制传统的历史传承。"]]},{"type":"note","title":"跨学科视角","text":"地理：欧洲庄园与中世纪城镇分布；道德与法治：契约与权利。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["琅城起义：1112 年，法国琅城市民为争取自治，发动武装起义，杀死主教，成立自治公社。 出处：吴于廑、齐世荣《世界史·中世纪史编》","中世纪大学：大学设有文、法、医、神学等学院，享有一定自治权，教学内容既有神学，也包含古典文化和世俗知识。 出处：2024 部编版九上第 9 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 9 课；吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】封臣对封君要忠诚，在封君需要的时候，要无偿地为封君服兵役、提供金钱等；封君对封臣也有义务，封君不能任意侵害封臣的荣誉、人身和财产安全，当封臣受到外来攻击时，封君必须提供保护。——据教材与中世纪誓词摘编\n【材料二】庄园的土地分为两部分：一部分是领主自己保留的「直领地」，由农奴耕种，收入全部归领主；另一部分是农民的「份地」，农民必须先在直领地上无偿劳动若干天，才能耕种自己的份地。庄园设有法庭，由领主或其管家主持，惩罚各种违法行为。\n【材料三】城市居民通过金钱赎买和武力斗争等方式，争取城市的自由和自治。取得自治权的城市，市民可以自由经商、免交赋税，还可以选举市政官员。随着城市的发展和工商业的繁荣，市民阶层逐渐形成，其中分化出富裕的大手工业作坊主、银行家等。","source":"材料研读 · 封建时代的欧洲：基督教、庄园、城市与拜占庭"}],"questions":[{"id":"h9a-u3-m1-q2","type":"short","stem":"（2）依据材料二、三，说明西欧庄园与城市各有什么特点，并结合所学指出城市兴起对欧洲历史发展的影响。（6 分）","answer":"庄园的特点：是一个独立的自给自足的经济和政治单位，土地分为领主直领地和农民份地，农民要为领主无偿劳动，庄园法庭负责维护庄园秩序并惩罚违法行为。城市的特点：居民通过金钱赎买和武力斗争争取自由和自治，市民可以自由经商、免交赋税、选举市政官员。影响：城市工商业的发展使市民阶层逐渐形成并壮大，从中分化出富裕的大手工业作坊主、银行家等，成为早期的资产阶级，为文艺复兴的兴起和资本主义的产生准备了条件。","explain":"","tags":["西欧庄园","中世纪城市","历史解释"],"rubric":["答出庄园自给自足、分为直领地与份地","答出庄园法庭的作用","答出城市争取自由和自治的方式","答出市民阶层壮大","答出早期资产阶级出现","答出为文艺复兴或资本主义兴起准备条件"]},{"id":"h9a-u3-q3","type":"choice","stem":"中世纪西欧城市居民争取自由和自治权最常用的手段是","answer":"A","explain":"城市居民常用的手段是金钱赎买和武力斗争，法国琅城人民起义争取自治就是典型事例。取得自治权的城市，市民可以自由经商、免交赋税、选举市政官员。","options":["金钱赎买和武力斗争","由议会立法授予","向教皇请愿","依靠庄园法庭判决"],"tags":["中世纪城市","历史解释"]},{"id":"h9a-u3-q5","type":"choice","stem":"被称为「中世纪最美好的花朵」的是","answer":"C","explain":"12 世纪西欧大学兴起，巴黎大学、牛津大学等先后出现，大学享有免赋税特权、司法特权和教育自主权，因此被称为「中世纪最美好的花朵」。","options":["庄园的兴起","城市的兴起","大学的兴起","骑士制度的形成"],"tags":["大学兴起","历史解释"]},{"id":"cat-9a-3-3-g2","type":"choice","stem":"下列关于「中世纪城市和大学的兴起」的表述，错误的是","answer":"A","explain":"把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」——两者形式相似、实质不同，比较题必须先分清纽带（土地 / 血缘）与关系特点。正确表述：西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","options":["把西欧封君封臣制与西周分封制完全等同，认为两者都是「层层分封、天子统辖所有诸侯」。","西欧的封君封臣关系是逐级双向的，有「我的附庸的附庸，不是我的附庸」之说，带契约色彩；西周分封制以血缘宗法为纽带，周天子是天下共主。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中外联动：同一时期中国正处于唐宋时期，城市经济繁荣、市民生活丰富，但中国城市始终处在中央集权的行政体系之下，没有像西欧城市那样争取到自治权，这是理解中西历史走向差异的一个重要视角。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-3-g3","type":"choice","stem":"下列结论中，属于「中世纪城市和大学的兴起」的是","answer":"A","explain":"本课结论：城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。","拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1112 年，法国琅城市民为争取自治，发动武装起义，杀死主教，成立自治公社。（吴于廑、齐世荣《世界史·中世纪史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"中世纪城市和大学的兴起；10 世纪以后西欧城市重新兴起，城市居民用金钱赎买和武力斗争等方式争取自由与自治；市民阶层的形成与发展为资本主义的兴起准备了条件。","explain":"材料出自吴于廑、齐世荣《世界史·中世纪史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-3-4","title":"第10课 拜占庭帝国和《查士丁尼法典》","subtitle":"九年级上册 · 第三单元 封建时代的欧洲","grade":"9a","tags":["九年级上册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第三单元 封建时代的欧洲"},{"k":"课时","v":"第10课 拜占庭帝国和《查士丁尼法典》"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"拜占庭帝国即东罗马帝国，以君士坦丁堡为都城。6 世纪，查士丁尼组织编纂《查士丁尼法典》等法律文献，统称《罗马民法大全》。1453 年，奥斯曼帝国攻占君士坦丁堡，拜占庭帝国灭亡。"},{"type":"note","title":"本课主线 · 因果链","text":"西罗马帝国灭亡后，日耳曼人建立的西欧国家逐渐形成以土地封赐为纽带的封君封臣制，庄园成为自给自足的经济和政治单位，基督教会在西欧社会取得精神统治地位；10 世纪以后城市重新兴起、大学出现，市民阶层成长为早期的资产阶级；东部的拜占庭帝国则以《罗马民法大全》保存并发展了罗马法，最终在 1453 年被奥斯曼帝国灭亡。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["481 年","日耳曼人建立法兰克王国，克洛维是建立者","西罗马帝国灭亡前后，法兰克王国是最强大的日耳曼人国家 · 重点"],["529 年（6 世纪）","拜占庭帝国编成《查士丁尼法典》；后与《法学汇纂》《法理概要》《新法典》合称《罗马民法大全》","查士丁尼在位时间为 527—565 年；《罗马民法大全》奠定了欧洲民法的基础 · 重点"],["1453 年","奥斯曼帝国攻破君士坦丁堡，拜占庭帝国灭亡","此时中国处于明朝中期（1453 年为明代宗景泰四年），同年郑和下西洋已经结束 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"481 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"日耳曼人建立法兰克王国，克洛维是建立…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"529 年（6 世纪）","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"拜占庭帝国编成《查士丁尼法典》；后与…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1453 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"奥斯曼帝国攻破君士坦丁堡，拜占庭帝国…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"拜占庭帝国查士丁尼在位时编成《罗马民法大全》，包括《查士丁尼法典》等四部法律文献，奠定了欧洲民法的基础。","explain":"常与《十二铜表法》《拿破仑法典》联合考查「西方法制传统的源流」，要会按时间排序并说明各自的历史地位。"},{"level":"次重点","text":"基督教产生于 1 世纪的巴勒斯坦地区，4 世纪末被罗马皇帝定为国教；西罗马帝国灭亡后，教会成为西欧最大的土地所有者与精神统治者。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《查士丁尼法典》当成罗马共和国或罗马帝国的法律。","它是 6 世纪东罗马帝国（拜占庭帝国）皇帝查士丁尼在位时编成的，属于《罗马民法大全》的一部分。","《十二铜表法》是共和国时期，《罗马民法大全》是拜占庭时期，两者相隔近千年。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["制度与契约类材料题","给出封君封臣的权利义务誓词或庄园敕令，要求概括双方的权利义务并说明这一制度的特点，落脚点常在「等级性」「契约性」「以土地为纽带」。"],["「中世纪并不黑暗」的论证","以城市兴起、大学出现、市民阶层形成为材料，要求说明中世纪西欧社会孕育着新的因素，答题按「经济—社会—文化」三条线索组织。"],["法律文献的时间轴","把《十二铜表法》《罗马民法大全》《权利法案》《拿破仑法典》打乱排序并说明地位，考查法制传统的历史传承。"]]},{"type":"note","title":"跨学科视角","text":"地理：欧洲庄园与中世纪城镇分布；道德与法治：契约与权利。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"查士丁尼","v":"拜占庭帝国皇帝，组织编纂《罗马民法大全》。 出处：《查士丁尼法典》"}]},{"type":"list","title":"延伸阅读","items":["《罗马民法大全》：包括《查士丁尼法典》《法学汇纂》《法理概要》《新法典》，奠定了欧洲民法的基础。 出处：《查士丁尼法典》；2024 部编版九上第 10 课","君士坦丁堡的陷落：1453 年，奥斯曼帝国苏丹穆罕默德二世率军攻陷君士坦丁堡，拜占庭帝国灭亡，中世纪结束的标志之一。 出处：吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 10 课；《查士丁尼法典》","吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u3-q4","type":"choice","stem":"《罗马民法大全》在历史上的重要地位是","answer":"B","explain":"《罗马民法大全》包括《查士丁尼法典》《法学汇纂》《法理概要》《新法典》，奠定了欧洲民法的基础。罗马法制建设的第一步是《十二铜表法》。","options":["罗马法制建设的第一步","奠定了欧洲民法的基础","世界上第一部成文法典","确立了君主立宪制"],"tags":["《罗马民法大全》","时空观念"]},{"id":"cat-9a-3-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 日耳曼人建立法兰克王国，克洛维是建立者\n② 拜占庭帝国编成《查士丁尼法典》；后与《法学汇纂》…\n③ 奥斯曼帝国攻破君士坦丁堡，拜占庭帝国灭亡","answer":"A","explain":"按时间顺序应为：①日耳曼人建立法兰克王国，克洛维是建立者（481 年）→②拜占庭帝国编成《查士丁尼法典》；后与《法学汇纂》《法理概要》《新法典》合称《罗马民法大全》（529 年（6 世纪））→③奥斯曼帝国攻破君士坦丁堡，拜占庭帝国灭亡（1453 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-4-g2","type":"choice","stem":"下列关于「拜占庭帝国和《查士丁尼法典》」的表述，错误的是","answer":"A","explain":"把《查士丁尼法典》当成罗马共和国或罗马帝国的法律——《十二铜表法》是共和国时期，《罗马民法大全》是拜占庭时期，两者相隔近千年。正确表述：它是 6 世纪东罗马帝国（拜占庭帝国）皇帝查士丁尼在位时编成的，属于《罗马民法大全》的一部分。","options":["把《查士丁尼法典》当成罗马共和国或罗马帝国的法律。","它是 6 世纪东罗马帝国（拜占庭帝国）皇帝查士丁尼在位时编成的，属于《罗马民法大全》的一部分。","拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。","拜占庭帝国查士丁尼在位时编成《罗马民法大全》，包括《查士丁尼法典》等四部法律文献，奠定了欧洲民法的基础。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-4-g3","type":"choice","stem":"下列结论中，属于「拜占庭帝国和《查士丁尼法典》」的是","answer":"A","explain":"本课结论：拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["拜占庭帝国保存并发展了罗马法，还保存了大量古希腊、古罗马典籍，对东西方文化交流起了桥梁作用；1453 年帝国灭亡后，许多学者携带古典典籍西逃，客观上推动了西欧文艺复兴。","中世纪的西欧是「封君封臣制 + 庄园 + 基督教会」三位一体的社会结构：庄园提供经济基础，封君封臣制提供政治秩序，教会提供精神统治。","封君封臣制以土地为纽带、以契约为约束，与西周以血缘宗法为纽带的分封制有明显区别，但两者都造成了地方势力的膨胀与王权的相对软弱。","城市与大学是中世纪西欧社会的「异质因素」：它们孕育了市民阶层与早期资产阶级，是后来文艺复兴、新航路开辟与资产阶级革命的社会基础。"],"difficulty":2,"tags":["九年级上册","第三单元","本课练习"]},{"id":"cat-9a-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：包括《查士丁尼法典》《法学汇纂》《法理概要》《新法典》，奠定了欧洲民法的基础。（《查士丁尼法典》；2024 部编版九上第 10 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"拜占庭帝国和《查士丁尼法典》；拜占庭帝国查士丁尼在位时编成《罗马民法大全》，包括《查士丁尼法典》等四部法律文献，奠定了欧洲民法的基础。","explain":"材料出自《查士丁尼法典》；2024 部编版九上第 10 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-4-1","title":"第11课 古代日本","subtitle":"九年级上册 · 第四单元 封建时代的亚洲国家","grade":"9a","tags":["九年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第四单元 封建时代的亚洲国家"},{"k":"课时","v":"第11课 古代日本"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"6 世纪起，日本出现奴隶制国家。646 年，日本仿效唐朝制度进行大化改新，使日本发展为中央集权制封建国家。12 世纪末，源赖朝建立镰仓幕府，日本进入幕府统治时期，武士阶层崛起。"},{"type":"note","title":"本课主线 · 因果链","text":"日本在 646 年以大化改新全面学习唐朝制度，建立起中央集权制的封建国家，后因武士集团崛起于 12 世纪晚期进入幕府统治；阿拉伯半岛在伊斯兰教的旗帜下实现统一，8 世纪中期形成横跨欧亚非三洲的大帝国，阿拉伯人既是东西方文化交流的桥梁，也把中国的造纸术、火药等重大发明传入欧洲。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["5 世纪","大和政权基本统一日本","1 世纪前后日本已出现早期国家；大和政权最高统治者称「大王」"],["646 年","日本孝德天皇推行大化改新，效仿唐朝典章制度进行改革","7 世纪中期，日本以「大化」为年号，开始全面学习隋唐制度 · 重点"],["7 世纪末—8 世纪初","大化改新后日本继续派遣遣唐使，中日交流频繁","阿倍仲麻吕、鉴真东渡等都是这一时期中日交往的著名事例"],["12 世纪晚期","源赖朝获得「征夷大将军」称号，在镰仓设幕府","日本进入长达近 700 年的幕府统治时期，天皇成为象征，实权掌握在幕府将军手中 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"5 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"大和政权基本统一日本","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"646 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"日本孝德天皇推行大化改新，效仿唐朝典…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"7 世纪末—8 世纪初","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"大化改新后日本继续派遣遣唐使，中日交…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"12 世纪晚期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"源赖朝获得「征夷大将军」称号，在镰仓…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"大化改新的内容：政治上建立以天皇为中心的中央集权制度，地方设国、郡、里，官吏由国家任免；经济上把土地和部民收归国有，成为公地、公民，国家定期把土地分给公民耕种并收取赋税。","explain":"要点是「全面学习唐朝」：中国的三省六部、郡县、均田、租庸调都对日本产生了影响。意义必须背下来：「使日本发展成为一个中央集权制的封建国家」。"},{"level":"重点","text":"12 世纪晚期日本进入幕府统治时期，天皇成为象征，幕府将军实际掌握国家大权；武士集团的形成与武士道的盛行是这一时期的重要特征。","explain":"常考「大化改新与幕府统治的关系」：大化改新建立中央集权，庄园经济发展后武士集团崛起，最终架空天皇、形成幕府统治。"},{"level":"次重点","text":"大化改新使日本由奴隶社会向封建社会过渡，是日本历史上的重要转折点。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。","中日联动：从大化改新学习唐朝，到近代日本明治维新学习西方，日本历史上两次大规模学习外来文化的成败，常与中国近代的洋务运动合并考查。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把大化改新与明治维新混为一谈。","大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","两者都是日本历史上的关键改革，但时代、学习对象与性质完全不同，这是中日改革比较题的基本前提。"]]},{"type":"table","title":"日本大化改新与中国唐朝制度（中外对比：一次成功的「以唐为师」）","head":["比较项","日本大化改新（646 年起）","中国唐朝制度"],"rows":[["政治体制","建立以天皇为中心的中央集权制度","三省六部制下的中央集权，皇帝为最高统治者"],["地方行政","地方设国、郡、里，官吏由国家任免","州县制，官吏由中央任免"],["土地与赋税","土地与部民收归国有，定期分给公民耕种，收取赋税","均田制与租庸调制"],["文化","派遣遣唐使、留学生，学习唐朝文字、典章与建筑","开放包容，长安成为国际大都会"],["历史作用","日本发展为中央集权制的封建国家","唐朝成为当时世界上最强盛的国家之一"]]},{"type":"table","title":"日本与阿拉伯帝国：封建时代亚洲的两种国家（亚洲封建国家的横向比较）","head":["比较项","日本","阿拉伯帝国"],"rows":[["统一与立国","5 世纪大和政权基本统一日本","7 世纪初以伊斯兰教为纽带实现半岛统一"],["关键改革/事件","646 年大化改新，学习唐朝制度","622 年迁麦地那、632 年半岛基本统一，之后大规模扩张"],["政治特点","12 世纪晚期起幕府将军掌实权，天皇成为象征","政教合一的哈里发国家，8 世纪中期横跨欧亚非三洲"],["文化贡献","吸收唐文化，形成独特的日本文化","翻译保存古希腊典籍，传播阿拉伯数字，成为文化交流桥梁"],["共同点","都在吸收外来文化的基础上发展出自己的封建文明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革类材料题的中外比较","给出大化改新诏书与唐朝制度的材料，要求说明日本学习了中国的哪些制度、改革带来的结果。常与中国商鞅变法、北魏孝文帝改革合并成「改革专题」。"],["宗教与统一的关系","以伊斯兰教创立与阿拉伯半岛统一为材料，考查「宗教如何成为政治统一的力量」，答题要点是打破部落界限、提供共同信仰与法律规范。"],["文化交流的桥梁作用","给出阿拉伯数字、造纸术西传等材料，要求说明阿拉伯人在世界文化传播中的地位与作用，落脚在「东西方文化交流的桥梁」。"]]},{"type":"note","title":"跨学科视角","text":"地理：日本列岛与阿拉伯半岛的区位；语文：《一千零一夜》。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"源赖朝","v":"日本镰仓幕府建立者。 出处：吴于廑、齐世荣《世界史·中世纪史编》"}]},{"type":"list","title":"延伸阅读","items":["大化改新：646 年，孝德天皇颁布改新诏书，仿唐朝制度，实行班田收授法、租庸调制，建立中央集权国家。 出处：《日本书纪》；2024 部编版九上第 11 课","武士与幕府：武士是日本封建社会的军事贵族，以「忠君、节义、廉耻、勇武」为信条。1192 年源赖朝获「征夷大将军」称号，建立镰仓幕府。 出处：吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 11 课；《日本书纪》","吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】（大化改新诏书摘译）废除皇室和贵族的私有土地和部民，收归国家所有，成为公地、公民；国家定期把土地分给公民耕种，向他们收取赋税。中央和地方各级官吏由国家任免，废除世袭贵族统治制度。——据《日本书纪》相关记载摘译\n【材料二】7 世纪中期以后，日本先后派出十几批遣唐使，随行的还有留学生、学问僧。他们把唐朝的典章制度、天文历法、书法艺术、建筑技术等带回日本。\n【材料三】阿拉伯人把中国古代的造纸术、指南针、火药等重大发明和印度的棉花、食糖等传入欧洲；同时，他们翻译并保存了大量古希腊的哲学与科学著作，后来又将这些著作传回欧洲。","source":"材料研读 · 封建时代的亚洲国家：日本与阿拉伯帝国"}],"questions":[{"id":"h9a-u4-m1-q1","type":"short","stem":"（1）依据材料一，概括大化改新在经济和政治方面的措施，并说明这次改革使日本发生了怎样的变化。（6 分）","answer":"经济措施：废除皇室和贵族的私有土地与部民，收归国家所有，成为公地、公民；国家定期把土地分给公民耕种并收取赋税（类似唐朝的均田制与租庸调制）。政治措施：废除世袭贵族统治制度，建立以天皇为中心的中央集权制度，中央和地方官吏由国家任免。变化：大化改新使日本由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。","explain":"","tags":["大化改新","历史解释"],"rubric":["答出收土地与部民为公地、公民","答出定期分地收税","答出中央集权、官吏由国家任免","答出废除世袭贵族统治制度","答出成为中央集权制的封建国家"]},{"id":"h9a-u4-q1","type":"choice","stem":"646 年，日本效仿中国唐朝的典章制度进行改革，这次改革史称","answer":"B","explain":"646 年（大化年间），日本孝德天皇推行改革，史称大化改新，主要是效仿唐朝的典章制度，使日本发展成为一个中央集权制的封建国家。","options":["明治维新","大化改新","农奴制改革","幕府改革"],"tags":["大化改新","时空观念"]},{"id":"h9a-u4-q2","type":"choice","stem":"大化改新最重要的历史意义是","answer":"B","explain":"大化改新使日本建立了以天皇为中心的中央集权制度，由奴隶社会向封建社会过渡，发展成为一个中央集权制的封建国家。C 项是明治维新的作用。","options":["使日本实现了国家统一","使日本发展成为一个中央集权制的封建国家","使日本走上了资本主义发展道路","使日本摆脱了外族的侵略"],"tags":["大化改新","历史解释"]},{"id":"h9a-u4-q3","type":"choice","stem":"12 世纪晚期，日本进入幕府统治时期，国家的实际权力掌握在","answer":"B","explain":"12 世纪晚期，源赖朝获得「征夷大将军」称号，设幕府于镰仓，日本从此进入长达近 700 年的幕府统治时期，幕府将军实际掌握国家大权，天皇成为象征。","options":["天皇手中","幕府将军手中","武士手中","大名手中"],"tags":["幕府统治","历史解释"]},{"id":"cat-9a-4-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 大和政权基本统一日本\n② 日本孝德天皇推行大化改新，效仿唐朝典章制度进行改…\n③ 大化改新后日本继续派遣遣唐使，中日交流频繁\n④ 源赖朝获得「征夷大将军」称号，在镰仓设幕府","answer":"A","explain":"按时间顺序应为：①大和政权基本统一日本（5 世纪）→②日本孝德天皇推行大化改新，效仿唐朝典章制度进行改革（646 年）→③大化改新后日本继续派遣遣唐使，中日交流频繁（7 世纪末—8 世纪初）→④源赖朝获得「征夷大将军」称号，在镰仓设幕府（12 世纪晚期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g2","type":"choice","stem":"下列关于「古代日本」的表述，错误的是","answer":"A","explain":"把大化改新与明治维新混为一谈——两者都是日本历史上的关键改革，但时代、学习对象与性质完全不同，这是中日改革比较题的基本前提。正确表述：大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","options":["把大化改新与明治维新混为一谈。","大化改新发生在 646 年，学习的是中国唐朝的典章制度，使日本成为中央集权制的封建国家；明治维新发生在 1868 年，学习的是欧美，使日本走上资本主义道路。","大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。","中日联动：从大化改新学习唐朝，到近代日本明治维新学习西方，日本历史上两次大规模学习外来文化的成败，常与中国近代的洋务运动合并考查。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g3","type":"choice","stem":"下列结论中，属于「古代日本」的是","answer":"A","explain":"本课结论：大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。","阿拉伯人是东西方文化交流的桥梁：他们把中国的造纸术、指南针、火药和印度的数字、棉花、食糖传入欧洲，为欧洲的社会进步提供了重要条件。","中外联动：中国与阿拉伯（唐代称「大食」）通过陆上与海上丝绸之路往来密切，651 年阿拉伯遣使来华；中国的四大发明中有三项经阿拉伯人西传，这是理解「中国古代科技对世界的影响」的关键史实。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：646 年，孝德天皇颁布改新诏书，仿唐朝制度，实行班田收授法、租庸调制，建立中央集权国家。（《日本书纪》；2024 部编版九上第 11 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"古代日本；大化改新的内容：政治上建立以天皇为中心的中央集权制度，地方设国、郡、里，官吏由国家任免；经济上把土地和部民收归国有，成为公地、公民，国家定期把土地分给公民耕种并收取赋税。","explain":"材料出自《日本书纪》；2024 部编版九上第 11 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-4-2","title":"第12课 阿拉伯帝国","subtitle":"九年级上册 · 第四单元 封建时代的亚洲国家","grade":"9a","tags":["九年级上册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第四单元 封建时代的亚洲国家"},{"k":"课时","v":"第12课 阿拉伯帝国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"7 世纪初，穆罕默德在阿拉伯半岛创立伊斯兰教。8 世纪中期，阿拉伯帝国成为地跨欧亚非三洲的大帝国。阿拉伯人吸收融合东西方文化，在数学、医学、天文学等领域取得重要成就。"},{"type":"note","title":"本课主线 · 因果链","text":"日本在 646 年以大化改新全面学习唐朝制度，建立起中央集权制的封建国家，后因武士集团崛起于 12 世纪晚期进入幕府统治；阿拉伯半岛在伊斯兰教的旗帜下实现统一，8 世纪中期形成横跨欧亚非三洲的大帝国，阿拉伯人既是东西方文化交流的桥梁，也把中国的造纸术、火药等重大发明传入欧洲。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["622 年","穆罕默德迁往麦地那，建立穆斯林公社","这一年被定为伊斯兰教历元年；麦地那公社的建立为阿拉伯半岛的统一奠定基础 · 重点"],["630 年","穆罕默德率穆斯林占领麦加","此后阿拉伯半岛各部落纷纷承认穆罕默德的统治地位"],["632 年","穆罕默德病逝，阿拉伯半岛基本统一","穆罕默德创立伊斯兰教，宣传「真主」安拉是唯一的宇宙之神 · 重点"],["8 世纪中期","阿拉伯帝国成为横跨欧亚非三洲的大帝国","此时中国处于唐朝，阿拉伯人被称为「大食」，651 年起多次遣使来华 · 重点"],["1258 年","蒙古军队攻陷巴格达，阿拉伯帝国灭亡","此时中国处于元朝建立前后（1260 年忽必烈即位）"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"622 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"穆罕默德迁往麦地那，建立穆斯林公社","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"630 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"穆罕默德率穆斯林占领麦加","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"632 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"穆罕默德病逝，阿拉伯半岛基本统一","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"8 世纪中期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"阿拉伯帝国成为横跨欧亚非三洲的大帝国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1258 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"蒙古军队攻陷巴格达，阿拉伯帝国灭亡","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"穆罕默德于 7 世纪初在麦加创立伊斯兰教，622 年迁往麦地那建立穆斯林公社，632 年病逝时阿拉伯半岛基本统一。","explain":"要抓住「宗教与统一的关系」：伊斯兰教打破部落界限，为阿拉伯半岛的统一提供了精神纽带。"},{"level":"重点","text":"阿拉伯人改造并传播了古印度人从 0 到 9 的计数法，形成今天通用的「阿拉伯数字」；《医学集成》《医典》长期被欧洲医学界奉为经典；《天方夜谭》是阿拉伯文学的瑰宝。","explain":"要会写阿拉伯人的历史作用：他们是东西方文化交流的桥梁，把中国的造纸术、指南针、火药和印度的棉花、食糖等传入欧洲，也把古希腊典籍保存并传回欧洲。"},{"level":"次重点","text":"伊斯兰教的经典是《古兰经》，它宣传「真主」安拉是唯一的宇宙之神，要求穆斯林信仰安拉、服从先知。","explain":""},{"level":"选择题","text":"阿拉伯帝国的建立伴随着对外扩张，也给被征服地区带来了灾难，但它在客观上促进了东西方经济文化的交流。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。","阿拉伯人是东西方文化交流的桥梁：他们把中国的造纸术、指南针、火药和印度的数字、棉花、食糖传入欧洲，为欧洲的社会进步提供了重要条件。","中外联动：中国与阿拉伯（唐代称「大食」）通过陆上与海上丝绸之路往来密切，651 年阿拉伯遣使来华；中国的四大发明中有三项经阿拉伯人西传，这是理解「中国古代科技对世界的影响」的关键史实。","中日联动：从大化改新学习唐朝，到近代日本明治维新学习西方，日本历史上两次大规模学习外来文化的成败，常与中国近代的洋务运动合并考查。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为「阿拉伯数字」是阿拉伯人发明的。","阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」。","这是一道高频陷阱题，考查的是「发明」与「传播」的区别。"],["认为穆罕默德在麦加建立了穆斯林公社。","穆罕默德在麦加创立伊斯兰教，622 年迁往麦地那后才建立穆斯林公社，632 年病逝时阿拉伯半岛基本统一。","麦加是创立地，麦地那是公社建立地与教历元年所在地，两个地点不能调换。"]]},{"type":"table","title":"日本大化改新与中国唐朝制度（中外对比：一次成功的「以唐为师」）","head":["比较项","日本大化改新（646 年起）","中国唐朝制度"],"rows":[["政治体制","建立以天皇为中心的中央集权制度","三省六部制下的中央集权，皇帝为最高统治者"],["地方行政","地方设国、郡、里，官吏由国家任免","州县制，官吏由中央任免"],["土地与赋税","土地与部民收归国有，定期分给公民耕种，收取赋税","均田制与租庸调制"],["文化","派遣遣唐使、留学生，学习唐朝文字、典章与建筑","开放包容，长安成为国际大都会"],["历史作用","日本发展为中央集权制的封建国家","唐朝成为当时世界上最强盛的国家之一"]]},{"type":"table","title":"日本与阿拉伯帝国：封建时代亚洲的两种国家（亚洲封建国家的横向比较）","head":["比较项","日本","阿拉伯帝国"],"rows":[["统一与立国","5 世纪大和政权基本统一日本","7 世纪初以伊斯兰教为纽带实现半岛统一"],["关键改革/事件","646 年大化改新，学习唐朝制度","622 年迁麦地那、632 年半岛基本统一，之后大规模扩张"],["政治特点","12 世纪晚期起幕府将军掌实权，天皇成为象征","政教合一的哈里发国家，8 世纪中期横跨欧亚非三洲"],["文化贡献","吸收唐文化，形成独特的日本文化","翻译保存古希腊典籍，传播阿拉伯数字，成为文化交流桥梁"],["共同点","都在吸收外来文化的基础上发展出自己的封建文明","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革类材料题的中外比较","给出大化改新诏书与唐朝制度的材料，要求说明日本学习了中国的哪些制度、改革带来的结果。常与中国商鞅变法、北魏孝文帝改革合并成「改革专题」。"],["宗教与统一的关系","以伊斯兰教创立与阿拉伯半岛统一为材料，考查「宗教如何成为政治统一的力量」，答题要点是打破部落界限、提供共同信仰与法律规范。"],["文化交流的桥梁作用","给出阿拉伯数字、造纸术西传等材料，要求说明阿拉伯人在世界文化传播中的地位与作用，落脚在「东西方文化交流的桥梁」。"]]},{"type":"note","title":"跨学科视角","text":"地理：日本列岛与阿拉伯半岛的区位；语文：《一千零一夜》。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["一千零一夜","阿拉伯民间故事集，又名《天方夜谭》，汇集了古代波斯、印度、阿拉伯的故事。","《一千零一夜》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"穆罕默德","v":"伊斯兰教创始人，统一阿拉伯半岛。 出处：吴于廑、齐世荣《世界史·中世纪史编》"}]},{"type":"list","title":"延伸阅读","items":["阿拉伯数字：阿拉伯人改造古印度数字，形成今天通用的「阿拉伯数字」，并传播到欧洲。 出处：2024 部编版九上第 12 课","《医学集成》与《医典》：阿拉伯医学家拉齐斯著《医学集成》，伊本·西拿著《医典》，长期为欧洲医学教材。 出处：吴于廑、齐世荣《世界史·中世纪史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 12 课；吴于廑、齐世荣《世界史·中世纪史编》","《一千零一夜》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】（大化改新诏书摘译）废除皇室和贵族的私有土地和部民，收归国家所有，成为公地、公民；国家定期把土地分给公民耕种，向他们收取赋税。中央和地方各级官吏由国家任免，废除世袭贵族统治制度。——据《日本书纪》相关记载摘译\n【材料二】7 世纪中期以后，日本先后派出十几批遣唐使，随行的还有留学生、学问僧。他们把唐朝的典章制度、天文历法、书法艺术、建筑技术等带回日本。\n【材料三】阿拉伯人把中国古代的造纸术、指南针、火药等重大发明和印度的棉花、食糖等传入欧洲；同时，他们翻译并保存了大量古希腊的哲学与科学著作，后来又将这些著作传回欧洲。","source":"材料研读 · 封建时代的亚洲国家：日本与阿拉伯帝国"}],"questions":[{"id":"h9a-u4-m1-q2","type":"short","stem":"（2）材料二、三共同反映了什么历史现象？结合所学，说明阿拉伯人在世界文化发展中的作用。（6 分）","answer":"历史现象：不同文明之间通过使者往来、人员交流与商业贸易相互学习、彼此传播文化，文明交流是双向的。阿拉伯人的作用：阿拉伯人改造并传播了古印度人从 0 到 9 的计数法，形成今天通用的「阿拉伯数字」；把中国的造纸术、指南针、火药以及印度的棉花、食糖等传入欧洲；翻译并保存了大量古希腊的哲学与科学著作，后来又传回欧洲，为欧洲文化的发展提供了条件。因此阿拉伯人是东西方文化交流的桥梁。","explain":"","tags":["阿拉伯文化","中外交流"],"rubric":["答出文明之间相互交流、双向传播","答出派遣遣唐使或学习唐朝制度文化","答出阿拉伯数字的改造与传播","答出中国发明经阿拉伯人西传","答出保存传播古希腊典籍","答出「东西方文化交流的桥梁」"]},{"id":"h9a-u4-q4","type":"choice","stem":"622 年，穆罕默德迁往麦地那建立穆斯林公社，这一年被定为","answer":"A","explain":"622 年穆罕默德迁往麦地那建立穆斯林公社，这一年被定为伊斯兰教历元年。阿拉伯半岛基本统一是在 632 年穆罕默德病逝时。","options":["伊斯兰教历元年","阿拉伯帝国建立之年","阿拉伯半岛统一之年","《古兰经》成书之年"],"tags":["伊斯兰教","时空观念"]},{"id":"h9a-u4-q5","type":"choice","stem":"今天世界各国通用的「阿拉伯数字」最早由哪一地区的人发明","answer":"B","explain":"阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」，这体现了阿拉伯人在东西方文化交流中的桥梁作用。","options":["阿拉伯人","古印度人","古埃及人","古希腊人"],"tags":["阿拉伯文化","史料实证"]},{"id":"h9a-u4-q6","type":"choice","stem":"中国的造纸术、指南针、火药等重大发明由阿拉伯人传入欧洲，这说明阿拉伯人","answer":"B","explain":"阿拉伯人把中国的造纸术、指南针、火药和印度的棉花、食糖等传入欧洲，同时保存并传播古希腊典籍，起到了东西方文化交流桥梁的作用。","options":["是这些发明的发明者","是东西方文化交流的桥梁","建立了横跨欧亚非三洲的帝国","创立了伊斯兰教"],"tags":["阿拉伯文化","中外交流"]},{"id":"cat-9a-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 穆罕默德迁往麦地那，建立穆斯林公社\n② 穆罕默德率穆斯林占领麦加\n③ 穆罕默德病逝，阿拉伯半岛基本统一\n④ 阿拉伯帝国成为横跨欧亚非三洲的大帝国","answer":"A","explain":"按时间顺序应为：①穆罕默德迁往麦地那，建立穆斯林公社（622 年）→②穆罕默德率穆斯林占领麦加（630 年）→③穆罕默德病逝，阿拉伯半岛基本统一（632 年）→④阿拉伯帝国成为横跨欧亚非三洲的大帝国（8 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-2-g2","type":"choice","stem":"下列关于「阿拉伯帝国」的表述，错误的是","answer":"A","explain":"认为「阿拉伯数字」是阿拉伯人发明的——这是一道高频陷阱题，考查的是「发明」与「传播」的区别。正确表述：阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」。","options":["认为「阿拉伯数字」是阿拉伯人发明的。","阿拉伯数字最早由古印度人发明，阿拉伯人加以改造并传播到欧洲，因此被称为「阿拉伯数字」。","大化改新是一次自上而下的、以中国唐朝制度为蓝本的改革，说明隋唐制度在东亚具有强大的示范效应，也说明善于学习和吸收外来先进文化是一个国家走向强盛的重要原因。","宗教在特定历史条件下可以成为统一的政治力量：伊斯兰教打破了阿拉伯半岛的部落界限，为半岛统一和帝国建立提供了精神纽带。"],"difficulty":2,"tags":["九年级上册","第四单元","本课练习"]},{"id":"cat-9a-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：阿拉伯人改造古印度数字，形成今天通用的「阿拉伯数字」，并传播到欧洲。（2024 部编版九上第 12 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"阿拉伯帝国；穆罕默德于 7 世纪初在麦加创立伊斯兰教，622 年迁往麦地那建立穆斯林公社，632 年病逝时阿拉伯半岛基本统一。","explain":"材料出自2024 部编版九上第 12 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-5-1","title":"第13课 西欧经济和社会的发展","subtitle":"九年级上册 · 第五单元 走向近代","grade":"9a","tags":["九年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第五单元 走向近代"},{"k":"课时","v":"第13课 西欧经济和社会的发展"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"14 世纪起，西欧农村出现租地农场，城市出现手工工场，雇佣关系逐渐发展，资本主义萌芽产生。富裕农民和市民阶层力量壮大，为社会变革准备了条件。"},{"type":"note","title":"本课主线 · 因果链","text":"14 世纪以后，西欧农村出现租地农场、手工业中出现手工工场，生产组织逐渐资本主义化；同一时期，意大利兴起的文艺复兴以人文主义冲破教会神权的束缚，为新社会的到来做了思想准备；15 世纪末开始的探寻新航路使世界开始连为一个整体，随之而来的早期殖民掠夺为欧洲积累了资本，也把灾难带给亚非拉人民。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["13—14 世纪","西欧出现分散的手工工场，后来出现集中的手工工场","雇主与雇工之间形成雇佣关系，是资本主义生产关系的萌芽"],["14 世纪中叶以后","西欧农村出现租地农场","富裕农民租种领主的土地，雇用少地或无地的农民，农产品面向市场——土地关系的变化推动农业资本主义化 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"13—14 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"西欧出现分散的手工工场，后来出现集中…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"14 世纪中叶以后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"西欧农村出现租地农场","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"租地农场与手工工场的出现，使西欧农村与手工业生产组织逐渐资本主义化，富裕农民与市民阶层成为新的社会力量。","explain":"要紧扣「雇佣关系」与「面向市场」两个关键词：这两点说明资本主义生产方式已经在旧社会的内部萌芽。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。"],["认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混。","1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","「印第安人」这一称呼就源于哥伦布的误判，这是记忆这条史实的一个抓手。"]]},{"type":"table","title":"租地农场与手工工场（西欧两种资本主义化的生产组织）","head":["比较项","租地农场（农村）","手工工场（手工业）"],"rows":[["出现时间","14 世纪中叶以后","13—14 世纪出现分散的手工工场，后来出现集中的手工工场"],["经营者","富裕农民（租地农场主）","商人或富裕作坊主"],["劳动者","少地或无地的农民，受雇劳动","雇工，与雇主形成彻底的雇佣关系"],["生产特点","农产品面向市场，为市场而生产","产品面向市场，集中生产、分工协作"],["共同实质","都体现了资本主义生产关系的萌芽","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["思想解放与社会转型","以文艺复兴时期的作品或言论为材料，考查「人文主义」的内涵及其对欧洲社会的影响，常与启蒙运动、中国近代的思想解放运动合并成专题。"],["新航路开辟的多角度影响","给出地图与数据材料，要求从「世界联系、欧洲经济、殖民灾难」三个角度分析影响，是「一分为二」评析的经典题。"],["中外航海对比","把郑和下西洋与新航路开辟的材料并列，要求比较目的、性质与结果，并说明「为什么中国没有走上海外扩张的道路」，落脚在「中西发展道路的差异」。"]]},{"type":"note","title":"跨学科视角","text":"地理：新航路与世界市场；科学：航海技术与地理大发现。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["租地农场：富裕农民租种领主土地，雇佣少地或无地农民耕种，产品面向市场，具有资本主义生产特征。 出处：2024 部编版九上第 13 课","手工工场：分散或集中的手工工场中，工人与雇主形成雇佣关系，分工协作，生产效率提高。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 13 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u5-q1","type":"choice","stem":"文艺复兴的核心思想是","answer":"A","explain":"文艺复兴的核心思想是人文主义，即肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。理性主义是启蒙运动的核心。","options":["人文主义","理性主义","禁欲主义","重商主义"],"tags":["文艺复兴","历史解释"]},{"id":"h9a-u5-q2","type":"choice","stem":"文艺复兴的实质是","answer":"B","explain":"文艺复兴采取复兴古代希腊罗马文化的形式，实质是新兴资产阶级的思想文化解放运动，它反对的是教会的神权束缚而非宗教信仰本身。","options":["古希腊罗马文化的简单复兴","新兴资产阶级的思想文化解放运动","一场反宗教的社会运动","教会内部的一次改革"],"tags":["文艺复兴","唯物史观"]},{"id":"h9a-u5-q3","type":"choice","stem":"1492 年率船队横渡大西洋、到达美洲的航海家是","answer":"C","explain":"1492 年哥伦布率船队横渡大西洋，到达今天的巴哈马群岛一带，他误以为自己到达的是印度，因此称当地居民为「印第安人」。","options":["迪亚士","达·伽马","哥伦布","麦哲伦"],"tags":["新航路开辟","时空观念"]},{"id":"cat-9a-5-1-g2","type":"choice","stem":"下列关于「西欧经济和社会的发展」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-1-g3","type":"choice","stem":"下列结论中，属于「西欧经济和社会的发展」的是","answer":"A","explain":"本课结论：文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：富裕农民租种领主土地，雇佣少地或无地农民耕种，产品面向市场，具有资本主义生产特征。（2024 部编版九上第 13 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"西欧经济和社会的发展；租地农场与手工工场的出现，使西欧农村与手工业生产组织逐渐资本主义化，富裕农民与市民阶层成为新的社会力量。","explain":"材料出自2024 部编版九上第 13 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-5-2","title":"第14课 文艺复兴运动","subtitle":"九年级上册 · 第五单元 走向近代","grade":"9a","tags":["九年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第五单元 走向近代"},{"k":"课时","v":"第14课 文艺复兴运动"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"14 世纪，文艺复兴运动首先在意大利兴起，后扩展到欧洲其他国家。文艺复兴以人文主义为核心，肯定人的价值和尊严，反对神学束缚。但丁、达·芬奇、莎士比亚是代表。"},{"type":"note","title":"本课主线 · 因果链","text":"14 世纪以后，西欧农村出现租地农场、手工业中出现手工工场，生产组织逐渐资本主义化；同一时期，意大利兴起的文艺复兴以人文主义冲破教会神权的束缚，为新社会的到来做了思想准备；15 世纪末开始的探寻新航路使世界开始连为一个整体，随之而来的早期殖民掠夺为欧洲积累了资本，也把灾难带给亚非拉人民。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["14 世纪","文艺复兴运动在意大利兴起","核心思想是人文主义；此时中国处于元末明初，正是欧洲开始走出中世纪的时期 · 重点"],["15 世纪","文艺复兴从意大利扩展到西欧各国","但丁、达·芬奇、莎士比亚是其中的代表"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"14 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"文艺复兴运动在意大利兴起","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"15 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"文艺复兴从意大利扩展到西欧各国","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"文艺复兴以人文主义为核心思想，肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。","explain":"必答题：「文艺复兴的实质是一场新兴资产阶级的思想文化解放运动。」注意它不是反对宗教信仰本身，而是反对教会的神权束缚，并且借复兴古希腊罗马文化之名。"},{"level":"选择题","text":"文艺复兴的代表人物：但丁（《神曲》）、达·芬奇（《蒙娜丽莎》《最后的晚餐》）、莎士比亚（《哈姆雷特》《罗密欧与朱丽叶》）。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["思想解放与社会转型","以文艺复兴时期的作品或言论为材料，考查「人文主义」的内涵及其对欧洲社会的影响，常与启蒙运动、中国近代的思想解放运动合并成专题。"],["新航路开辟的多角度影响","给出地图与数据材料，要求从「世界联系、欧洲经济、殖民灾难」三个角度分析影响，是「一分为二」评析的经典题。"],["中外航海对比","把郑和下西洋与新航路开辟的材料并列，要求比较目的、性质与结果，并说明「为什么中国没有走上海外扩张的道路」，落脚在「中西发展道路的差异」。"]]},{"type":"note","title":"跨学科视角","text":"地理：新航路与世界市场；科学：航海技术与地理大发现。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["人文主义","文艺复兴的核心思想，主张以人为中心而不是以神为中心，肯定人的价值和尊严。","2024 部编版九上第 14 课"],["走自己的路，让别人说去吧","但丁《神曲》中的名句，体现追求个性解放的精神。","但丁《神曲》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"但丁","v":"意大利诗人，文艺复兴先驱，著《神曲》。 出处：《神曲》"},{"k":"达·芬奇","v":"意大利画家、科学家，代表作《蒙娜丽莎》《最后的晚餐》。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"莎士比亚","v":"英国剧作家，文艺复兴文学集大成者。 出处：《哈姆雷特》"}]},{"type":"list","title":"延伸阅读","items":["文艺复兴的实质：文艺复兴不是古典文化的简单复兴，而是新兴资产阶级在思想文化领域发动的反封建运动。 出处：吴于廑、齐世荣《世界史·近代史编》","莎士比亚：英国剧作家，创作《哈姆雷特》《罗密欧与朱丽叶》等，作品深刻反映人文主义思想。 出处：《哈姆雷特》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 14 课；《神曲》《哈姆雷特》","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u5-q1","type":"choice","stem":"文艺复兴的核心思想是","answer":"A","explain":"文艺复兴的核心思想是人文主义，即肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。理性主义是启蒙运动的核心。","options":["人文主义","理性主义","禁欲主义","重商主义"],"tags":["文艺复兴","历史解释"]},{"id":"h9a-u5-q2","type":"choice","stem":"文艺复兴的实质是","answer":"B","explain":"文艺复兴采取复兴古代希腊罗马文化的形式，实质是新兴资产阶级的思想文化解放运动，它反对的是教会的神权束缚而非宗教信仰本身。","options":["古希腊罗马文化的简单复兴","新兴资产阶级的思想文化解放运动","一场反宗教的社会运动","教会内部的一次改革"],"tags":["文艺复兴","唯物史观"]},{"id":"cat-9a-5-2-g2","type":"choice","stem":"下列关于「文艺复兴运动」的表述，错误的是","answer":"A","explain":"认为文艺复兴是反对宗教、否定基督教——材料题常问「文艺复兴为什么被称为『复兴』」，标准答法是：它以复兴古代希腊罗马文化为形式，实质是新兴资产阶级的思想解放运动。正确表述：文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","options":["认为文艺复兴是反对宗教、否定基督教。","文艺复兴反对的是教会的神权束缚与禁欲主义说教，而不是宗教信仰本身；它借复兴古希腊罗马文化之名，行资产阶级思想解放之实。","文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g3","type":"choice","stem":"下列结论中，属于「文艺复兴运动」的是","answer":"A","explain":"本课结论：文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：文艺复兴不是古典文化的简单复兴，而是新兴资产阶级在思想文化领域发动的反封建运动。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"文艺复兴运动；文艺复兴以人文主义为核心思想，肯定人的价值与尊严，提倡发扬人的个性、追求现世的幸福，反对教会神权对人的束缚。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-5-3","title":"第15课 探寻新航路","subtitle":"九年级上册 · 第五单元 走向近代","grade":"9a","tags":["九年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第五单元 走向近代"},{"k":"课时","v":"第15课 探寻新航路"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"15 世纪，欧洲商品经济发展，对黄金和香料的需求增加，奥斯曼帝国控制传统商路，促使欧洲人探寻通往东方的新航路。迪亚士、达·伽马、哥伦布、麦哲伦等航海家相继远航。"},{"type":"note","title":"本课主线 · 因果链","text":"14 世纪以后，西欧农村出现租地农场、手工业中出现手工工场，生产组织逐渐资本主义化；同一时期，意大利兴起的文艺复兴以人文主义冲破教会神权的束缚，为新社会的到来做了思想准备；15 世纪末开始的探寻新航路使世界开始连为一个整体，随之而来的早期殖民掠夺为欧洲积累了资本，也把灾难带给亚非拉人民。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1487 年","迪亚士到达非洲南端的好望角","葡萄牙人率先探寻通往东方的新航路"],["1492 年","哥伦布到达美洲（今巴哈马群岛一带）","他误以为自己到达的是印度，因此称当地居民为「印第安人」 · 重点"],["1497—1498 年","达·伽马率船队绕过好望角到达印度","打通了从欧洲绕非洲到印度的新航路 · 重点"],["1519—1522 年","麦哲伦船队完成环球航行","人类首次环球航行，证明地球是圆的，世界开始连为一个整体 · 重点"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 麦哲伦环球航行：三年绕地球一周","caption":"示意图：麦哲伦环球航行：三年绕地球一周，详见下方「历史现场」","view":"tall","alt":"示意图：麦哲伦环球航行：三年绕地球一周，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1519 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"麦哲伦率 5 艘船、约 270 人从…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1520 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"船队穿过南美洲南端海峡（后称麦哲伦海…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1521 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"到达菲律宾群岛，麦哲伦介入当地冲突被…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"1521 年 11 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"船队到达摩鹿加群岛","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1522 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"「维多利亚号」返回西班牙，仅 18 …","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"新航路的开辟：1487 年迪亚士到达好望角，1492 年哥伦布到达美洲，1497—1498 年达·伽马到达印度，1519—1522 年麦哲伦船队环球航行。","explain":"四条航线要能在地图上定位，时间不能混。哥伦布到达的是美洲（他始终以为是亚洲），麦哲伦本人在途中死于菲律宾，船队由他人带回西班牙。"},{"level":"重点","text":"新航路开辟使欧洲与亚非美之间的交通日益密切，世界开始连为一个整体，世界的观念逐步确立起来，同时促进了欧洲资本主义的发展。","explain":"这是本单元最重要的一条结论。答题时按「世界联系—欧洲经济—殖民扩张」三层展开，不能只说「发现了新大陆」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混。","1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","「印第安人」这一称呼就源于哥伦布的误判，这是记忆这条史实的一个抓手。"],["把新航路开辟的原因只归结为「马可·波罗的游记」或「地圆学说」。","根本原因是欧洲商品经济的发展与对财富（黄金、香料）的渴求，直接原因是奥斯曼帝国阻断了东西方传统的商路；此外还有地圆学说、罗盘与造船技术进步等条件。","「原因」要分根本原因与直接原因，「条件」与「原因」也不能混为一谈。"]]},{"type":"table","title":"郑和下西洋与新航路开辟（中外对比：15—16 世纪东西方两次大规模远航）","head":["比较项","郑和下西洋（1405—1433）","新航路开辟（1487—1522）"],"rows":[["时间","1405—1433 年，比新航路开辟早半个多世纪","1487 年迪亚士到达好望角起，至 1522 年完成环球航行"],["目的","宣扬国威，加强与海外各国的友好往来，发展朝贡贸易","寻求通往东方的新航路，获取黄金、香料，进行殖民扩张"],["规模与方式","船队规模庞大，以和平交往为主","船队规模小，伴随武力征服与殖民掠夺"],["经济性质","不计经济效益，由官府负担，难以持续","与商品经济和资本积累结合，获得巨额利润"],["结果与影响","加强了中国与亚非国家的友好往来，但后来远洋航行停止，中国逐渐闭关","世界开始连为一个整体，促进欧洲资本主义发展，中西差距逐渐拉大"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["思想解放与社会转型","以文艺复兴时期的作品或言论为材料，考查「人文主义」的内涵及其对欧洲社会的影响，常与启蒙运动、中国近代的思想解放运动合并成专题。"],["新航路开辟的多角度影响","给出地图与数据材料，要求从「世界联系、欧洲经济、殖民灾难」三个角度分析影响，是「一分为二」评析的经典题。"],["中外航海对比","把郑和下西洋与新航路开辟的材料并列，要求比较目的、性质与结果，并说明「为什么中国没有走上海外扩张的道路」，落脚在「中西发展道路的差异」。"]]},{"type":"note","title":"跨学科视角","text":"地理：新航路与世界市场；科学：航海技术与地理大发现。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 麦哲伦环球航行：三年绕地球一周","head":["时间","经过"],"rows":[["1519 年 9 月","麦哲伦率 5 艘船、约 270 人从西班牙出发，向西航行"],["1520 年","船队穿过南美洲南端海峡（后称麦哲伦海峡），进入太平洋"],["1521 年 3 月","到达菲律宾群岛，麦哲伦介入当地冲突被杀"],["1521 年 11 月","船队到达摩鹿加群岛"],["1522 年 9 月","「维多利亚号」返回西班牙，仅 18 人生还，完成首次环球航行"]]},{"type":"note","title":"现场解说","text":"环球航行证实了地圆学说，是世界航海史上的壮举。"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["哥伦布发现新大陆","1492 年哥伦布到达美洲，虽非最早到达，但开启了欧洲与美洲的持续联系。","吴于廑、齐世荣《世界史·近代史编》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"哥伦布","v":"意大利航海家，1492 年到达美洲。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"麦哲伦","v":"葡萄牙航海家，率船队完成首次环球航行。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"达·伽马","v":"葡萄牙航海家，1498 年到达印度。 出处：吴于廑、齐世荣《世界史·近代史编》"}]},{"type":"list","title":"延伸阅读","items":["四次关键航行：1487 年迪亚士到达好望角；1498 年达·伽马到达印度；1492 年哥伦布到达美洲；1519—1522 年麦哲伦船队完成环球航行。 出处：吴于廑、齐世荣《世界史·近代史编》","新航路的影响：世界开始连为一个整体，欧洲大西洋沿岸工商业繁荣，但也开启了殖民掠夺，给亚非拉人民带来灾难。 出处：2024 部编版九上第 15 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 15 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中世纪初期，人们在宗教神学的束缚下生活，认为人是渺小的、有罪的。14 世纪以后，意大利的一些诗人、画家开始歌颂人的价值。彼特拉克说：「我不想变成上帝……属于人的那种光荣对我就够了。我自己是凡人，我只要求凡人的幸福。」\n【材料二】15 世纪，随着工商业的发展，欧洲人对黄金和香料的渴求日益强烈。奥斯曼帝国控制了东西方之间的传统商路，欧洲人不得不用高昂的价格购买东方的商品，于是他们希望开辟一条通往东方的新航路。\n【材料三】新航路开辟后，欧洲与亚洲、非洲、美洲之间的联系日益密切，往来商品种类增多，世界市场逐渐形成。同时，欧洲殖民者开始了对亚非拉地区的掠夺，大批黑人被贩卖到美洲，非洲因此丧失了大量人口。","source":"材料研读 · 走向近代：租地农场、文艺复兴与新航路开辟"}],"questions":[{"id":"h9a-u5-m1-q2","type":"short","stem":"（2）依据材料二，概括新航路开辟的原因。结合材料三和所学知识，评价新航路开辟的历史影响。（7 分）","answer":"原因：欧洲工商业发展，商品经济发展需要更多黄金与市场；欧洲人对黄金、香料的渴求（《马可·波罗行纪》的传播刺激了这种欲望）；奥斯曼帝国控制东西方传统商路，使东方商品价格昂贵，欧洲人迫切希望开辟直达东方的新航路。影响：积极方面——欧洲与亚非美之间的交通日益密切，世界开始连为一个整体，世界的观念逐步确立起来；促进了欧洲大西洋沿岸工商业的繁荣和资本主义的发展；世界市场逐渐形成。消极方面——欧洲殖民者随之开始殖民掠夺，给亚非拉人民带来深重灾难，如三角贸易使非洲丧失大量人口。因此新航路开辟具有进步性与掠夺性两面。","explain":"","tags":["新航路开辟","历史解释"],"rubric":["答出商品经济发展或对黄金香料的渴求","答出奥斯曼帝国阻断传统商路","答出世界开始连为一个整体","答出促进欧洲资本主义发展或世界市场形成","答出殖民掠夺与亚非拉人民的灾难","答出「一分为二」的评价"]},{"id":"h9a-u5-q3","type":"choice","stem":"1492 年率船队横渡大西洋、到达美洲的航海家是","answer":"C","explain":"1492 年哥伦布率船队横渡大西洋，到达今天的巴哈马群岛一带，他误以为自己到达的是印度，因此称当地居民为「印第安人」。","options":["迪亚士","达·伽马","哥伦布","麦哲伦"],"tags":["新航路开辟","时空观念"]},{"id":"h9a-u5-q4","type":"choice","stem":"首次完成环球航行、证明地球是圆的的航海活动是","answer":"C","explain":"1519—1522 年，麦哲伦船队完成人类首次环球航行，证明了地球是圆的。麦哲伦本人在途中死于菲律宾，船队由其他人带领返回西班牙。","options":["迪亚士到达好望角","达·伽马到达印度","麦哲伦船队 1519—1522 年的环球航行","哥伦布到达美洲"],"tags":["新航路开辟","时空观念"]},{"id":"h9a-u5-q5","type":"choice","stem":"新航路开辟最重要的世界性影响是","answer":"B","explain":"新航路开辟以后，欧洲与亚洲、非洲、美洲之间的交通日益密切，世界开始连为一个整体，世界市场逐渐形成，这是它最重要的世界性影响。此后欧洲的贸易中心由地中海沿岸转移到大西洋沿岸。","options":["使欧洲人发现了美洲大陆","使世界开始连为一个整体，世界市场逐渐形成","使中国的丝绸传入欧洲","使意大利成为世界贸易的中心"],"tags":["新航路开辟","历史解释"]},{"id":"cat-9a-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 迪亚士到达非洲南端的好望角\n② 哥伦布到达美洲（今巴哈马群岛一带）\n③ 达·伽马率船队绕过好望角到达印度\n④ 麦哲伦船队完成环球航行","answer":"A","explain":"按时间顺序应为：①迪亚士到达非洲南端的好望角（1487 年）→②哥伦布到达美洲（今巴哈马群岛一带）（1492 年）→③达·伽马率船队绕过好望角到达印度（1497—1498 年）→④麦哲伦船队完成环球航行（1519—1522 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-3-g2","type":"choice","stem":"下列关于「探寻新航路」的表述，错误的是","answer":"A","explain":"认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混——「印第安人」这一称呼就源于哥伦布的误判，这是记忆这条史实的一个抓手。正确表述：1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","options":["认为哥伦布到达了亚洲（印度），或把哥伦布与麦哲伦的贡献弄混。","1492 年哥伦布到达美洲，他始终误以为是亚洲的印度；1519—1522 年麦哲伦船队完成环球航行，证明地球是圆的。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-3-g3","type":"choice","stem":"下列结论中，属于「探寻新航路」的是","answer":"A","explain":"本课结论：新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1487 年迪亚士到达好望角；1498 年达·伽马到达印度；1492 年哥伦布到达美洲；1519—1522 年麦哲伦船队完成环球航行。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"探寻新航路；新航路的开辟：1487 年迪亚士到达好望角，1492 年哥伦布到达美洲，1497—1498 年达·伽马到达印度，1519—1522 年麦哲伦船队环球航行。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-5-4","title":"第16课 早期殖民掠夺","subtitle":"九年级上册 · 第五单元 走向近代","grade":"9a","tags":["九年级上册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第五单元 走向近代"},{"k":"课时","v":"第16课 早期殖民掠夺"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"新航路开辟后，欧洲国家开始殖民扩张。葡萄牙、西班牙最早，英国后来居上。三角贸易把欧洲、非洲、美洲连接起来，持续数百年，给非洲带来深重灾难。"},{"type":"note","title":"本课主线 · 因果链","text":"14 世纪以后，西欧农村出现租地农场、手工业中出现手工工场，生产组织逐渐资本主义化；同一时期，意大利兴起的文艺复兴以人文主义冲破教会神权的束缚，为新社会的到来做了思想准备；15 世纪末开始的探寻新航路使世界开始连为一个整体，随之而来的早期殖民掠夺为欧洲积累了资本，也把灾难带给亚非拉人民。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1487 年","迪亚士到达非洲南端的好望角","葡萄牙人率先探寻通往东方的新航路"],["16 世纪","欧洲殖民者开始进行「三角贸易」，葡萄牙、西班牙最早走上殖民扩张道路","1588 年英国海军击败西班牙「无敌舰队」，开始走上殖民扩张的道路"],["17—18 世纪","荷兰被称为「海上马车夫」；18 世纪英国成为最大的殖民国家","英国通过三角贸易积累了大量资本，为工业革命准备了条件"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1487 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"迪亚士到达非洲南端的好望角","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"16 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"欧洲殖民者开始进行「三角贸易」，葡萄…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"17—18 世纪","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"荷兰被称为「海上马车夫」；18 世纪…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"新航路的开辟：1487 年迪亚士到达好望角，1492 年哥伦布到达美洲，1497—1498 年达·伽马到达印度，1519—1522 年麦哲伦船队环球航行。","explain":"四条航线要能在地图上定位，时间不能混。哥伦布到达的是美洲（他始终以为是亚洲），麦哲伦本人在途中死于菲律宾，船队由他人带回西班牙。"},{"level":"重点","text":"新航路开辟使欧洲与亚非美之间的交通日益密切，世界开始连为一个整体，世界的观念逐步确立起来，同时促进了欧洲资本主义的发展。","explain":"这是本单元最重要的一条结论。答题时按「世界联系—欧洲经济—殖民扩张」三层展开，不能只说「发现了新大陆」。"},{"level":"次重点","text":"早期殖民掠夺：葡萄牙、西班牙最早，17 世纪的荷兰被称为「海上马车夫」，英国后来居上，18 世纪成为最大的殖民国家。","explain":""},{"level":"次重点","text":"「三角贸易」的路线是欧洲 → 非洲 → 美洲：欧洲殖民者把廉价工业品运到非洲换取黑奴，再把黑奴运往美洲卖掉，最后把美洲的金银和工业原料运回欧洲。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。","早期殖民掠夺具有双重性：它给亚非拉人民带来了深重灾难（黑奴贸易使非洲丧失大量人口），客观上又为欧洲殖民国家积累了资本，有助于世界市场的形成。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为三角贸易中最先受害的是美洲，或把三角贸易的路线记成欧洲—美洲—非洲。","三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：非洲丧失大量青壮年人口，美洲得到的是被贩卖的黑人奴隶。","顺序错了整道题的答案就会错，记忆口诀是「出欧入非，贩奴至美，载货回欧」。"]]},{"type":"table","title":"郑和下西洋与新航路开辟（中外对比：15—16 世纪东西方两次大规模远航）","head":["比较项","郑和下西洋（1405—1433）","新航路开辟（1487—1522）"],"rows":[["时间","1405—1433 年，比新航路开辟早半个多世纪","1487 年迪亚士到达好望角起，至 1522 年完成环球航行"],["目的","宣扬国威，加强与海外各国的友好往来，发展朝贡贸易","寻求通往东方的新航路，获取黄金、香料，进行殖民扩张"],["规模与方式","船队规模庞大，以和平交往为主","船队规模小，伴随武力征服与殖民掠夺"],["经济性质","不计经济效益，由官府负担，难以持续","与商品经济和资本积累结合，获得巨额利润"],["结果与影响","加强了中国与亚非国家的友好往来，但后来远洋航行停止，中国逐渐闭关","世界开始连为一个整体，促进欧洲资本主义发展，中西差距逐渐拉大"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["思想解放与社会转型","以文艺复兴时期的作品或言论为材料，考查「人文主义」的内涵及其对欧洲社会的影响，常与启蒙运动、中国近代的思想解放运动合并成专题。"],["新航路开辟的多角度影响","给出地图与数据材料，要求从「世界联系、欧洲经济、殖民灾难」三个角度分析影响，是「一分为二」评析的经典题。"],["中外航海对比","把郑和下西洋与新航路开辟的材料并列，要求比较目的、性质与结果，并说明「为什么中国没有走上海外扩张的道路」，落脚在「中西发展道路的差异」。"]]},{"type":"note","title":"跨学科视角","text":"地理：新航路与世界市场；科学：航海技术与地理大发现。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["三角贸易：欧洲殖民者从欧洲运出廉价工业品到非洲换取黑奴，再把黑奴运到美洲出售，最后从美洲运回金银和原料，形成三角形航程。 出处：2024 部编版九上第 16 课","英国的崛起：英国通过 1588 年击败西班牙「无敌舰队」、17 世纪三次英荷战争、18 世纪英法战争，逐步取得海上霸权。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 16 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中世纪初期，人们在宗教神学的束缚下生活，认为人是渺小的、有罪的。14 世纪以后，意大利的一些诗人、画家开始歌颂人的价值。彼特拉克说：「我不想变成上帝……属于人的那种光荣对我就够了。我自己是凡人，我只要求凡人的幸福。」\n【材料二】15 世纪，随着工商业的发展，欧洲人对黄金和香料的渴求日益强烈。奥斯曼帝国控制了东西方之间的传统商路，欧洲人不得不用高昂的价格购买东方的商品，于是他们希望开辟一条通往东方的新航路。\n【材料三】新航路开辟后，欧洲与亚洲、非洲、美洲之间的联系日益密切，往来商品种类增多，世界市场逐渐形成。同时，欧洲殖民者开始了对亚非拉地区的掠夺，大批黑人被贩卖到美洲，非洲因此丧失了大量人口。","source":"材料研读 · 走向近代：租地农场、文艺复兴与新航路开辟"}],"questions":[{"id":"h9a-u5-q6","type":"choice","stem":"在「三角贸易」中，欧洲殖民者从非洲运往美洲的主要是","answer":"B","explain":"三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：殖民者把廉价工业品运到非洲换取黑奴，再把黑奴运往美洲出卖，最后把美洲的金银和工业原料运回欧洲。黑奴贸易使非洲丧失了大量人口。","options":["廉价工业品","黑人奴隶","金银和工业原料","香料和瓷器"],"tags":["三角贸易","历史解释"]},{"id":"cat-9a-5-4-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 迪亚士到达非洲南端的好望角\n② 欧洲殖民者开始进行「三角贸易」，葡萄牙、西班牙最…\n③ 荷兰被称为「海上马车夫」；18 世纪英国成为最大…","answer":"A","explain":"按时间顺序应为：①迪亚士到达非洲南端的好望角（1487 年）→②欧洲殖民者开始进行「三角贸易」，葡萄牙、西班牙最早走上殖民扩张道路（16 世纪）→③荷兰被称为「海上马车夫」；18 世纪英国成为最大的殖民国家（17—18 世纪）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-4-g2","type":"choice","stem":"下列关于「早期殖民掠夺」的表述，错误的是","answer":"A","explain":"认为三角贸易中最先受害的是美洲，或把三角贸易的路线记成欧洲—美洲—非洲——顺序错了整道题的答案就会错，记忆口诀是「出欧入非，贩奴至美，载货回欧」。正确表述：三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：非洲丧失大量青壮年人口，美洲得到的是被贩卖的黑人奴隶。","options":["认为三角贸易中最先受害的是美洲，或把三角贸易的路线记成欧洲—美洲—非洲。","三角贸易的路线是欧洲 → 非洲 → 美洲 → 欧洲：非洲丧失大量青壮年人口，美洲得到的是被贩卖的黑人奴隶。","新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-4-g3","type":"choice","stem":"下列结论中，属于「早期殖民掠夺」的是","answer":"A","explain":"本课结论：新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["新航路开辟的最大影响是世界开始连为一个整体，世界市场逐渐形成，也开始了西欧的殖民掠夺，具有进步性与掠夺性的两面。","文艺复兴的实质是新兴资产阶级的思想文化解放运动，它并不是要否定宗教，而是反对教会的神权束缚与禁欲说教，为欧洲资本主义社会的产生奠定了思想文化基础。","「人的发现」（文艺复兴）与「世界的发现」（新航路开辟）共同推动欧洲走向近代，说明思想解放与经济发展相互促进。","中外联动：郑和下西洋（1405—1433）在时间上早于新航路开辟，但目的以宣扬国威、发展朝贡贸易为主，不计经济效益，此后中国的远洋航行逐渐停止并走向闭关；西欧则把海外航行与殖民掠夺、资本积累结合起来，从此中西发展差距不断拉大。"],"difficulty":2,"tags":["九年级上册","第五单元","本课练习"]},{"id":"cat-9a-5-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：欧洲殖民者从欧洲运出廉价工业品到非洲换取黑奴，再把黑奴运到美洲出售，最后从美洲运回金银和原料，形成三角形航程。（2024 部编版九上第 16 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"早期殖民掠夺；新航路的开辟：1487 年迪亚士到达好望角，1492 年哥伦布到达美洲，1497—1498 年达·伽马到达印度，1519—1522 年麦哲伦船队环球航行。","explain":"材料出自2024 部编版九上第 16 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-6-1","title":"第17课 君主立宪制的英国","subtitle":"九年级上册 · 第六单元 资本主义制度的初步确立","grade":"9a","tags":["九年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第六单元 资本主义制度的初步确立"},{"k":"课时","v":"第17课 君主立宪制的英国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"英国斯图亚特王朝推行专制统治，征税未经议会同意，激化矛盾。1640 年英国资产阶级革命爆发，1649 年查理一世被处死，英国建立共和国。1688 年「光荣革命」后，1689 年议会通过《权利法案》，君主立宪制确立。"},{"type":"note","title":"本课主线 · 因果链","text":"英国议会与国王的冲突最终以 1688 年「光荣革命」收场，1689 年《权利法案》确立了君主立宪制；北美殖民地因不满英国的殖民压迫而独立，1776 年《独立宣言》宣告美国诞生，1787 年宪法确立了联邦制与三权分立；法国大革命以《人权宣言》高举自由平等的旗帜，把启蒙思想付诸实践，拿破仑用战争与法典把革命成果推向欧洲。三国革命共同确立了资本主义制度，也开启了近代政治文明的新形态。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1689 年","英国议会通过《权利法案》","以法律形式限制国王的权力，君主立宪制的资产阶级统治开始确立 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"1689 年《权利法案》以法律形式明…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"英国资产阶级革命经历了议会斗争、内战…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"英美法三国资产阶级革命都以法律文献的…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"英国确立的是君主立宪制（保留…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"关键表述是「以法律形式对国王的权力进行明确的制约」和「君主立宪制开始确立」。常考《权利法案》与《人权宣言》《独立宣言》的思想差异。"},{"level":"次重点","text":"英国资产阶级革命经历了议会斗争、内战、处死国王、共和国、复辟到「光荣革命」的曲折过程，说明新制度的确立不是一帆风顺的。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。","英国确立的是君主立宪制（保留国王、议会掌权），美国确立的是联邦共和制（没有国王、总统由选举产生），法国大革命则彻底摧毁了君主专制——三国选择了不同的政体，但都建立了资产阶级的统治。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为英国资产阶级革命后确立了共和制。","英国确立的是君主立宪制：国王仍然存在，但权力受议会和法律限制，议会成为国家权力的中心。","「君主立宪」与「共和」是两种政体。英国曾短暂建立共和国（1649—1660），但最终确立的是君主立宪制，这个曲折过程本身也是常考点。"],["把《权利法案》与《人权宣言》的作者、国家、内容混淆。","《权利法案》是 1689 年英国议会通过的，限制国王权力；《人权宣言》是 1789 年法国制宪议会颁布的，宣扬自由平等与私有财产神圣不可侵犯。","两者都把矛头指向专制王权，但一个是「限制王权」，一个是「宣告人权」，答题时不可互换。"]]},{"type":"table","title":"英国君主立宪制与美国联邦共和制（两种资本主义政体的比较）","head":["比较项","英国（1689 年《权利法案》后）","美国（1787 年宪法后）"],"rows":[["国家元首","国王，但权力受议会与法律限制","总统，由选举产生，有任期限制"],["权力中心","议会（下院逐渐成为权力中心）","总统与国会、最高法院相互制衡"],["权力结构","议会至上，内阁对议会负责","三权分立，立法、行政、司法相互制约"],["建立方式","1688 年「光荣革命」后以立法方式确立","独立战争胜利后由制宪会议制定宪法确立"],["共同点","都否定君主专制，实行资产阶级民主政治，都以法律形式确立制度","同左"]]},{"type":"table","title":"17—18 世纪的中国与英美法（中外对比：同一时期两种政治走向）","head":["比较项","中国（清朝前期）","英美法等国"],"rows":[["政治制度","君主专制空前强化（军机处设立于 1729 年前后）","通过革命确立君主立宪制、联邦共和制等资产阶级民主制度"],["法律地位","法律服务于皇权，皇帝不受法律约束","以宪法和法律限制王权、保障人权"],["经济政策","重农抑商，闭关锁国，只留广州一处通商","鼓励海外贸易与殖民扩张，发展资本主义经济"],["思想领域","八股取士、文字狱，思想受到严密控制","启蒙运动传播自由、平等、民主思想"],["历史结果","逐渐落后于世界潮流，为近代被动挨打埋下伏笔","走上资本主义道路，形成对东方的优势"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["法律文献的对比阅读","把《权利法案》《独立宣言》《人权宣言》的片段并列，要求比较三者的核心主张与国家，是稳定性很高的比较类材料题。"],["革命过程的曲折性","以英国革命「处死国王—建立共和国—复辟—光荣革命」的历程为材料，考查「新制度的确立为什么是曲折的」，落脚在「新旧势力的反复较量」。"],["历史人物的评价","以拿破仑的《法典》与对外战争为材料，要求一分为二地评价，答题结构是「功：法典与打击封建势力；过：侵略与损害他国利益」。"],["中外同时期对比","把清朝前期的君主专制、闭关锁国与英美法革命放在同一年代尺上，考查学生对「中西历史走向分岔」的理解。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：权利法案、独立宣言与人权宣言；语文：启蒙思想文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["君主立宪制","君主权力受宪法和法律限制，议会掌握国家最高权力的政治制度。","2024 部编版九上第 17 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"克伦威尔","v":"英国资产阶级革命领导人。 出处：吴于廑、齐世荣《世界史·近代史编》"}]},{"type":"list","title":"延伸阅读","items":["《权利法案》：规定国王不得随意废止法律、不得征税、不得在和平时期维持常备军，保障议会言论自由和定期集会，限制王权。 出处：《权利法案》原文","克伦威尔：英国革命领导人，处死查理一世后建立共和国，后任「护国公」，实行军事独裁。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 17 课；《权利法案》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】凡未经议会同意，以国王权威停止法律或停止法律实施之僭越权力，为非法权力。……凡未经议会准许，借口国王特权，为国王而征收，或供国王使用而征收金钱，超出议会准许之时限或方式者，皆为非法。——《权利法案》（1689 年）\n【材料二】人人生而平等，他们都从他们的「造物主」那里被赋予了某些不可转让的权利，其中包括生命权、自由权和追求幸福的权利。——《独立宣言》（1776 年）\n【材料三】在权利方面，人们生来是而且始终是自由平等的。……财产是神圣不可侵犯的权利。——《人权宣言》（1789 年）","source":"材料研读 · 资本主义制度的初步确立：英美法革命与制度创新"}],"questions":[{"id":"h9a-u6-q1","type":"choice","stem":"英国资产阶级革命结束的标志是","answer":"B","explain":"1688 年，英国议会邀请荷兰执政威廉和玛丽共同入主英国，推翻复辟的斯图亚特王朝，史称「光荣革命」，标志英国资产阶级革命结束。1689 年《权利法案》的颁布则标志着君主立宪制的确立。","options":["1649 年查理一世被处死","1688 年的「光荣革命」","1689 年《权利法案》的颁布","1660 年斯图亚特王朝复辟"],"tags":["英国革命","时空观念"]},{"id":"h9a-u6-q2","type":"choice","stem":"1689 年《权利法案》的颁布，使英国确立的政治制度是","answer":"B","explain":"《权利法案》以法律形式限制国王的权力，议会成为国家权力的中心，君主立宪制的资产阶级统治在英国开始确立起来。","options":["君主专制","君主立宪制","民主共和制","联邦制"],"tags":["《权利法案》","制度创新"]},{"id":"h9a-u6-q4","type":"choice","stem":"1787 年美国宪法确立的重要原则是","answer":"B","explain":"1787 年美国宪法确立了联邦制以及立法（国会）、行政（总统）、司法（最高法院）三权分立、相互制衡的原则，是世界上第一部资产阶级成文宪法。但它没有废除奴隶制，也没有给妇女、印第安人和黑人奴隶平等的权利。","options":["君主立宪","三权分立、相互制衡","中央集权与地方分权并重","议会至上"],"tags":["1787 年宪法","制度创新"]},{"id":"cat-9a-6-1-g2","type":"choice","stem":"下列关于「君主立宪制的英国」的表述，错误的是","answer":"A","explain":"认为英国资产阶级革命后确立了共和制——「君主立宪」与「共和」是两种政体。英国曾短暂建立共和国（1649—1660），但最终确立的是君主立宪制，这个曲折过程本身也是常考点。正确表述：英国确立的是君主立宪制：国王仍然存在，但权力受议会和法律限制，议会成为国家权力的中心。","options":["认为英国资产阶级革命后确立了共和制。","英国确立的是君主立宪制：国王仍然存在，但权力受议会和法律限制，议会成为国家权力的中心。","英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。","英国确立的是君主立宪制（保留国王、议会掌权），美国确立的是联邦共和制（没有国王、总统由选举产生），法国大革命则彻底摧毁了君主专制——三国选择了不同的政体，但都建立了资产阶级的统治。"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：规定国王不得随意废止法律、不得征税、不得在和平时期维持常备军，保障议会言论自由和定期集会，限制王权。（《权利法案》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"君主立宪制的英国；1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"材料出自《权利法案》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-6-2","title":"第18课 美国的独立","subtitle":"九年级上册 · 第六单元 资本主义制度的初步确立","grade":"9a","tags":["九年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第六单元 资本主义制度的初步确立"},{"k":"课时","v":"第18课 美国的独立"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"18 世纪，英国在北美殖民地推行高压政策，激起反抗。1775 年来克星顿枪声打响独立战争第一枪，1776 年 7 月 4 日《独立宣言》发表，宣告美国诞生。1783 年英国承认美国独立，1787 年美国宪法确立联邦制和三权分立。"},{"type":"note","title":"本课主线 · 因果链","text":"英国议会与国王的冲突最终以 1688 年「光荣革命」收场，1689 年《权利法案》确立了君主立宪制；北美殖民地因不满英国的殖民压迫而独立，1776 年《独立宣言》宣告美国诞生，1787 年宪法确立了联邦制与三权分立；法国大革命以《人权宣言》高举自由平等的旗帜，把启蒙思想付诸实践，拿破仑用战争与法典把革命成果推向欧洲。三国革命共同确立了资本主义制度，也开启了近代政治文明的新形态。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1775 年","来克星顿枪声，北美独立战争爆发","同年第二届大陆会议组建大陆军，华盛顿任总司令"],["1776 年 7 月 4 日","《独立宣言》发表，宣告北美 13 个殖民地独立","标志着美国的诞生；由杰斐逊起草，宣称人人生而平等 · 重点"],["1787 年","美国制定宪法，确立联邦制与三权分立","是世界上第一部资产阶级成文宪法；1789 年华盛顿当选为第一任总统 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1775 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"来克星顿枪声，北美独立战争爆发","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1776 年 7 月 4…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"《独立宣言》发表，宣告北美 13 个…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1787 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"美国制定宪法，确立联邦制与三权分立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"关键表述是「以法律形式对国王的权力进行明确的制约」和「君主立宪制开始确立」。常考《权利法案》与《人权宣言》《独立宣言》的思想差异。"},{"level":"重点","text":"《独立宣言》的发表标志着美国的诞生；1787 年宪法确立了联邦制与三权分立（立法权归国会、行政权归总统、司法权归最高法院）的原则。","explain":"1787 年宪法是世界上第一部资产阶级成文宪法，但要同时指出它的局限：它没有废除奴隶制，也没有给予妇女、印第安人和黑人奴隶平等的权利。"},{"level":"次重点","text":"美国独立战争既是民族解放战争，也是资产阶级革命：它使美国摆脱了英国的殖民统治，为资本主义的发展开辟了道路。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《独立宣言》与 1787 年宪法的意义弄混。","1776 年《独立宣言》宣告北美 13 个殖民地独立，标志美国的诞生；1787 年宪法确立了美国的联邦制与三权分立的政治体制。","前者解决「独立」，后者解决「建国后怎么治理」，是前后相承的两个环节。"]]},{"type":"table","title":"英国君主立宪制与美国联邦共和制（两种资本主义政体的比较）","head":["比较项","英国（1689 年《权利法案》后）","美国（1787 年宪法后）"],"rows":[["国家元首","国王，但权力受议会与法律限制","总统，由选举产生，有任期限制"],["权力中心","议会（下院逐渐成为权力中心）","总统与国会、最高法院相互制衡"],["权力结构","议会至上，内阁对议会负责","三权分立，立法、行政、司法相互制约"],["建立方式","1688 年「光荣革命」后以立法方式确立","独立战争胜利后由制宪会议制定宪法确立"],["共同点","都否定君主专制，实行资产阶级民主政治，都以法律形式确立制度","同左"]]},{"type":"table","title":"17—18 世纪的中国与英美法（中外对比：同一时期两种政治走向）","head":["比较项","中国（清朝前期）","英美法等国"],"rows":[["政治制度","君主专制空前强化（军机处设立于 1729 年前后）","通过革命确立君主立宪制、联邦共和制等资产阶级民主制度"],["法律地位","法律服务于皇权，皇帝不受法律约束","以宪法和法律限制王权、保障人权"],["经济政策","重农抑商，闭关锁国，只留广州一处通商","鼓励海外贸易与殖民扩张，发展资本主义经济"],["思想领域","八股取士、文字狱，思想受到严密控制","启蒙运动传播自由、平等、民主思想"],["历史结果","逐渐落后于世界潮流，为近代被动挨打埋下伏笔","走上资本主义道路，形成对东方的优势"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["法律文献的对比阅读","把《权利法案》《独立宣言》《人权宣言》的片段并列，要求比较三者的核心主张与国家，是稳定性很高的比较类材料题。"],["革命过程的曲折性","以英国革命「处死国王—建立共和国—复辟—光荣革命」的历程为材料，考查「新制度的确立为什么是曲折的」，落脚在「新旧势力的反复较量」。"],["历史人物的评价","以拿破仑的《法典》与对外战争为材料，要求一分为二地评价，答题结构是「功：法典与打击封建势力；过：侵略与损害他国利益」。"],["中外同时期对比","把清朝前期的君主专制、闭关锁国与英美法革命放在同一年代尺上，考查学生对「中西历史走向分岔」的理解。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：权利法案、独立宣言与人权宣言；语文：启蒙思想文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["人人生而平等","《独立宣言》的核心表述，成为后世权利宣言的重要思想来源。","《独立宣言》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"华盛顿","v":"美国独立战争大陆军总司令，首任总统。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"杰斐逊","v":"《独立宣言》起草者，美国第三任总统。 出处：《独立宣言》"}]},{"type":"list","title":"延伸阅读","items":["《独立宣言》：由杰斐逊起草，宣布人人生而平等，享有生命权、自由权和追求幸福的权利，宣告北美 13 个殖民地脱离英国独立。 出处：《独立宣言》原文","1787 年宪法：确立联邦制，联邦政府分为立法、行政、司法三部分，相互制衡；但允许奴隶制存在，妇女和黑人没有政治权利。 出处：《1787 年宪法》原文"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 18 课；《独立宣言》《1787 年宪法》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】凡未经议会同意，以国王权威停止法律或停止法律实施之僭越权力，为非法权力。……凡未经议会准许，借口国王特权，为国王而征收，或供国王使用而征收金钱，超出议会准许之时限或方式者，皆为非法。——《权利法案》（1689 年）\n【材料二】人人生而平等，他们都从他们的「造物主」那里被赋予了某些不可转让的权利，其中包括生命权、自由权和追求幸福的权利。——《独立宣言》（1776 年）\n【材料三】在权利方面，人们生来是而且始终是自由平等的。……财产是神圣不可侵犯的权利。——《人权宣言》（1789 年）","source":"材料研读 · 资本主义制度的初步确立：英美法革命与制度创新"}],"questions":[{"id":"h9a-u6-q3","type":"choice","stem":"标志着美国诞生的历史事件是","answer":"B","explain":"1776 年 7 月 4 日，《独立宣言》发表，宣告北美 13 个殖民地脱离英国独立，标志着美国的诞生。来克星顿枪声是独立战争爆发的标志，萨拉托加大捷是转折点。","options":["来克星顿枪声","1776 年 7 月 4 日《独立宣言》的发表","萨拉托加大捷","1787 年宪法的制定"],"tags":["《独立宣言》","时空观念"]},{"id":"h9a-u6-q4","type":"choice","stem":"1787 年美国宪法确立的重要原则是","answer":"B","explain":"1787 年美国宪法确立了联邦制以及立法（国会）、行政（总统）、司法（最高法院）三权分立、相互制衡的原则，是世界上第一部资产阶级成文宪法。但它没有废除奴隶制，也没有给妇女、印第安人和黑人奴隶平等的权利。","options":["君主立宪","三权分立、相互制衡","中央集权与地方分权并重","议会至上"],"tags":["1787 年宪法","制度创新"]},{"id":"h9a-u6-q6","type":"choice","stem":"《拿破仑法典》的历史地位主要在于","answer":"B","explain":"1804 年拿破仑颁布《拿破仑法典》，它体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本。A 项是 1787 年美国宪法，C 项是《权利法案》，D 项是《独立宣言》。","options":["是世界上第一部资产阶级成文宪法","体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本","以法律形式限制了国王的权力","宣告北美殖民地脱离英国独立"],"tags":["拿破仑法典","制度创新"]},{"id":"cat-9a-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 来克星顿枪声，北美独立战争爆发\n② 《独立宣言》发表，宣告北美 13 个殖民地独立\n③ 美国制定宪法，确立联邦制与三权分立","answer":"A","explain":"按时间顺序应为：①来克星顿枪声，北美独立战争爆发（1775 年）→②《独立宣言》发表，宣告北美 13 个殖民地独立（1776 年 7 月 4 日）→③美国制定宪法，确立联邦制与三权分立（1787 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-2-g2","type":"choice","stem":"下列关于「美国的独立」的表述，错误的是","answer":"A","explain":"把《独立宣言》与 1787 年宪法的意义弄混——前者解决「独立」，后者解决「建国后怎么治理」，是前后相承的两个环节。正确表述：1776 年《独立宣言》宣告北美 13 个殖民地独立，标志美国的诞生；1787 年宪法确立了美国的联邦制与三权分立的政治体制。","options":["把《独立宣言》与 1787 年宪法的意义弄混。","1776 年《独立宣言》宣告北美 13 个殖民地独立，标志美国的诞生；1787 年宪法确立了美国的联邦制与三权分立的政治体制。","英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。","1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：由杰斐逊起草，宣布人人生而平等，享有生命权、自由权和追求幸福的权利，宣告北美 13 个殖民地脱离英国独立。（《独立宣言》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"美国的独立；1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"材料出自《独立宣言》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-6-3","title":"第19课 法国大革命和拿破仑帝国","subtitle":"九年级上册 · 第六单元 资本主义制度的初步确立","grade":"9a","tags":["九年级上册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第六单元 资本主义制度的初步确立"},{"k":"课时","v":"第19课 法国大革命和拿破仑帝国"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"18 世纪末，法国封建专制和等级制度激化社会矛盾。1789 年 7 月 14 日巴黎人民攻占巴士底狱，法国大革命爆发。制宪议会通过《人权宣言》。1792 年法兰西第一共和国成立。1804 年拿破仑称帝，颁布《拿破仑法典》。"},{"type":"note","title":"本课主线 · 因果链","text":"英国议会与国王的冲突最终以 1688 年「光荣革命」收场，1689 年《权利法案》确立了君主立宪制；北美殖民地因不满英国的殖民压迫而独立，1776 年《独立宣言》宣告美国诞生，1787 年宪法确立了联邦制与三权分立；法国大革命以《人权宣言》高举自由平等的旗帜，把启蒙思想付诸实践，拿破仑用战争与法典把革命成果推向欧洲。三国革命共同确立了资本主义制度，也开启了近代政治文明的新形态。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1789 年","5 月三级会议召开，7 月 14 日巴黎人民攻占巴士底狱，法国大革命开始","同年 8 月颁布《人权宣言》；此时中国处于清朝乾隆年间 · 重点"],["1792—1794 年","法国建立共和国、处死路易十六，雅各宾派专政，1794 年热月政变革命结束","法国大革命摧毁了法国的君主专制统治，传播了自由民主思想"],["1804 年","拿破仑建立法兰西第一帝国，颁布《拿破仑法典》","法典体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本"],["1812—1815 年","拿破仑远征俄国失败，1815 年滑铁卢战役失败，帝国终结","拿破仑的对外战争前期打击了欧洲封建势力，后期损害了被侵略国家人民的利益"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1789 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"5 月三级会议召开，7 月 14 日…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1792—1794 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"法国建立共和国、处死路易十六，雅各宾…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1804 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"拿破仑建立法兰西第一帝国，颁布《拿破…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1812—1815 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"拿破仑远征俄国失败，1815 年滑铁…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"关键表述是「以法律形式对国王的权力进行明确的制约」和「君主立宪制开始确立」。常考《权利法案》与《人权宣言》《独立宣言》的思想差异。"},{"level":"重点","text":"法国大革命摧毁了法国的君主专制统治，传播了资产阶级自由民主思想，具有世界性的影响。","explain":"《人权宣言》要记住两个核心内容：「人生来自由，权利平等」与「私有财产神圣不可侵犯」——后者体现了资产阶级的本质要求。"},{"level":"重点","text":"《拿破仑法典》体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本；拿破仑的对外战争前期打击了欧洲封建势力，后期损害了被侵略国家人民的利益。","explain":"评价拿破仑必须一分为二：对内「法典」是功绩，对外战争具有双重性。材料题常给「拿破仑战争在欧洲引起反抗」的材料。"},{"level":"选择题","text":"启蒙运动批判封建专制和天主教会，宣传自由、平等和民主，为法国大革命作了思想准备；伏尔泰、孟德斯鸠、卢梭是其中的代表人物。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。","英国确立的是君主立宪制（保留国王、议会掌权），美国确立的是联邦共和制（没有国王、总统由选举产生），法国大革命则彻底摧毁了君主专制——三国选择了不同的政体，但都建立了资产阶级的统治。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把《权利法案》与《人权宣言》的作者、国家、内容混淆。","《权利法案》是 1689 年英国议会通过的，限制国王权力；《人权宣言》是 1789 年法国制宪议会颁布的，宣扬自由平等与私有财产神圣不可侵犯。","两者都把矛头指向专制王权，但一个是「限制王权」，一个是「宣告人权」，答题时不可互换。"],["完全否定拿破仑的对外战争。","拿破仑的对外战争前期打击了欧洲的封建势力、传播了革命成果，具有进步性；后期则损害了被侵略国家人民的利益，引起各国反抗。","这是「一分为二」评价历史人物的典型题，既要写功也要写过。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["法律文献的对比阅读","把《权利法案》《独立宣言》《人权宣言》的片段并列，要求比较三者的核心主张与国家，是稳定性很高的比较类材料题。"],["革命过程的曲折性","以英国革命「处死国王—建立共和国—复辟—光荣革命」的历程为材料，考查「新制度的确立为什么是曲折的」，落脚在「新旧势力的反复较量」。"],["历史人物的评价","以拿破仑的《法典》与对外战争为材料，要求一分为二地评价，答题结构是「功：法典与打击封建势力；过：侵略与损害他国利益」。"],["中外同时期对比","把清朝前期的君主专制、闭关锁国与英美法革命放在同一年代尺上，考查学生对「中西历史走向分岔」的理解。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：权利法案、独立宣言与人权宣言；语文：启蒙思想文本。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["自由、平等、博爱","法国大革命的口号，成为现代政治文明的重要价值。","2024 部编版九上第 19 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"罗伯斯庇尔","v":"法国大革命雅各宾派领导人。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"拿破仑","v":"法兰西第一帝国皇帝，颁布《拿破仑法典》。 出处：《拿破仑法典》"}]},{"type":"list","title":"延伸阅读","items":["《人权宣言》：宣布人生来自由、权利平等，私有财产神圣不可侵犯，主权在民，法律面前人人平等。 出处：《人权宣言》原文","《拿破仑法典》：1804 年颁布，确立民事权利平等、私有财产权、契约自由等原则，成为许多国家民法的范本。 出处：《拿破仑法典》原文"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 19 课；《人权宣言》《拿破仑法典》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】凡未经议会同意，以国王权威停止法律或停止法律实施之僭越权力，为非法权力。……凡未经议会准许，借口国王特权，为国王而征收，或供国王使用而征收金钱，超出议会准许之时限或方式者，皆为非法。——《权利法案》（1689 年）\n【材料二】人人生而平等，他们都从他们的「造物主」那里被赋予了某些不可转让的权利，其中包括生命权、自由权和追求幸福的权利。——《独立宣言》（1776 年）\n【材料三】在权利方面，人们生来是而且始终是自由平等的。……财产是神圣不可侵犯的权利。——《人权宣言》（1789 年）","source":"材料研读 · 资本主义制度的初步确立：英美法革命与制度创新"}],"questions":[{"id":"h9a-u6-m1-q2","type":"short","stem":"（2）比较材料二、三，指出两部文献共同宣扬的核心观念；结合所学说明这些观念来源于哪一思想解放运动，并指出《人权宣言》还强调了什么原则。（6 分）","answer":"共同宣扬的核心观念：人生来自由平等，享有不可剥夺（不可转让）的权利，即自由、平等的观念。来源：这些观念来源于启蒙运动，启蒙思想家宣传自由、平等和民主，反对封建专制与天主教会，为法国大革命作了思想准备。此外，《人权宣言》还强调私有财产神圣不可侵犯——这一原则反映了资产阶级保护自身经济利益的要求。","explain":"","tags":["《独立宣言》","《人权宣言》","历史解释"],"rubric":["答出自由、平等的观念","答出权利不可剥夺或以人为中心","答出启蒙运动","答出启蒙运动反对封建专制（或宣传自由平等民主）","答出私有财产神圣不可侵犯","答出这一原则反映资产阶级的要求"]},{"id":"h9a-u6-q5","type":"choice","stem":"法国大革命开始的标志是","answer":"B","explain":"1789 年 7 月 14 日，巴黎人民攻占巴士底狱，法国大革命由此开始。此后制宪议会颁布《人权宣言》，1792 年法国建立共和国。","options":["1789 年 5 月三级会议的召开","1789 年 7 月 14 日巴黎人民攻占巴士底狱","《人权宣言》的颁布","1793 年路易十六被处死"],"tags":["法国大革命","时空观念"]},{"id":"h9a-u6-q6","type":"choice","stem":"《拿破仑法典》的历史地位主要在于","answer":"B","explain":"1804 年拿破仑颁布《拿破仑法典》，它体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本。A 项是 1787 年美国宪法，C 项是《权利法案》，D 项是《独立宣言》。","options":["是世界上第一部资产阶级成文宪法","体现了自由平等和私有财产神圣不可侵犯的原则，成为许多国家民法的参照蓝本","以法律形式限制了国王的权力","宣告北美殖民地脱离英国独立"],"tags":["拿破仑法典","制度创新"]},{"id":"cat-9a-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 5 月三级会议召开，7 月 14 日巴黎人民攻占…\n② 法国建立共和国、处死路易十六，雅各宾派专政，17…\n③ 拿破仑建立法兰西第一帝国，颁布《拿破仑法典》\n④ 拿破仑远征俄国失败，1815 年滑铁卢战役失败，…","answer":"A","explain":"按时间顺序应为：①5 月三级会议召开，7 月 14 日巴黎人民攻占巴士底狱，法国大革命开始（1789 年）→②法国建立共和国、处死路易十六，雅各宾派专政，1794 年热月政变革命结束（1792—1794 年）→③拿破仑建立法兰西第一帝国，颁布《拿破仑法典》（1804 年）→④拿破仑远征俄国失败，1815 年滑铁卢战役失败，帝国终结（1812—1815 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-3-g2","type":"choice","stem":"下列关于「法国大革命和拿破仑帝国」的表述，错误的是","answer":"A","explain":"把《权利法案》与《人权宣言》的作者、国家、内容混淆——两者都把矛头指向专制王权，但一个是「限制王权」，一个是「宣告人权」，答题时不可互换。正确表述：《权利法案》是 1689 年英国议会通过的，限制国王权力；《人权宣言》是 1789 年法国制宪议会颁布的，宣扬自由平等与私有财产神圣不可侵犯。","options":["把《权利法案》与《人权宣言》的作者、国家、内容混淆。","《权利法案》是 1689 年英国议会通过的，限制国王权力；《人权宣言》是 1789 年法国制宪议会颁布的，宣扬自由平等与私有财产神圣不可侵犯。","英美法三国资产阶级革命都以法律文献的形式把革命成果固定下来（英国《权利法案》、美国 1787 年宪法、法国《人权宣言》与《拿破仑法典》），说明用法律确立制度是近代政治文明的重要特征。","英国确立的是君主立宪制（保留国王、议会掌权），美国确立的是联邦共和制（没有国王、总统由选举产生），法国大革命则彻底摧毁了君主专制——三国选择了不同的政体，但都建立了资产阶级的统治。"],"difficulty":2,"tags":["九年级上册","第六单元","本课练习"]},{"id":"cat-9a-6-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：宣布人生来自由、权利平等，私有财产神圣不可侵犯，主权在民，法律面前人人平等。（《人权宣言》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"法国大革命和拿破仑帝国；1689 年《权利法案》以法律形式明确限制国王的权力，君主立宪制的资产阶级统治在英国开始确立起来。","explain":"材料出自《人权宣言》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-7-1","title":"第20课 第一次工业革命","subtitle":"九年级上册 · 第七单元 工业革命和国际共产主义运动的兴起","grade":"9a","tags":["九年级上册","第七单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第七单元 工业革命和国际共产主义运动的兴起"},{"k":"课时","v":"第20课 第一次工业革命"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"18 世纪 60 年代，第一次工业革命首先在英国开始。哈格里夫斯发明珍妮机，瓦特改良蒸汽机，机器生产逐步取代手工劳动。1825 年斯蒂芬森设计的蒸汽机车试车成功，人类进入「铁路时代」。"},{"type":"note","title":"本课主线 · 因果链","text":"18 世纪 60 年代从英国棉纺织业开始的工业革命用机器生产取代了手工劳动，人类进入「蒸汽时代」，英国成为「世界工厂」，社会也日益分裂为工业资产阶级与工业无产阶级两大对立阶级；工人运动的兴起催生了 1848 年《共产党宣言》的发表和 1871 年巴黎公社的成立。与中国史的联动点是：英国完成工业革命后发动鸦片战争，中国被卷入资本主义世界市场。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["18 世纪 60 年代","哈格里夫斯发明珍妮纺纱机，工业革命开始","工业革命首先从英国的棉纺织业开始；此时中国处于清朝乾隆年间 · 重点"],["1785 年以后","瓦特改良的蒸汽机被用作纺织部门的动力机","蒸汽机的广泛应用是工业革命的重要标志，人类进入「蒸汽时代」 · 重点"],["1807 年、1825 年","富尔顿发明汽船；史蒂芬孙设计的蒸汽机车试车成功","交通运输工具的革命使世界联系更加紧密"],["19 世纪中期","英国率先完成工业革命，成为世界上第一个工业国家（「世界工厂」）","西方列强凭借工业文明加紧对外扩张；1840 年英国发动鸦片战争，中国开始沦为半殖民地半封建社会 · 重点"],["1840 年","英国发动鸦片战争（中国近代史的开端）","这是工业革命影响中国的直接体现，与中国史联动的关键时间点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"18 世纪 60 年代","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"哈格里夫斯发明珍妮纺纱机，工业革命开…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1785 年以后","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"瓦特改良的蒸汽机被用作纺织部门的动力…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1807 年、1825 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"富尔顿发明汽船；史蒂芬孙设计的蒸汽机…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"19 世纪中期","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"英国率先完成工业革命，成为世界上第一…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1840 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"英国发动鸦片战争（中国近代史的开端）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第一次工业革命首先从英国的棉纺织业开始，18 世纪 60 年代珍妮纺纱机的发明标志着工业革命的开始，瓦特改良的蒸汽机使人类进入「蒸汽时代」。","explain":"「为什么首先发生在英国」是本单元最爱考的一问，要综合答：政治制度（君主立宪制确立，政局稳定）、市场（海外殖民地广阔）、资本（殖民掠夺与三角贸易积累）、劳动力（圈地运动提供自由劳动力）、技术（手工工场积累的生产经验与科技知识）。"},{"level":"重点","text":"工业革命造成了巨大影响：极大地提高了社会生产力，人类进入「蒸汽时代」；机器生产取代手工劳动，工厂制度形成；社会日益分裂为工业资产阶级和工业无产阶级两大对立阶级；城市化进程加快，同时也带来环境污染等问题。","explain":"要从「生产力—生产关系—社会结构—世界格局」多个层面去答，并注意它对中国的影响：英国完成工业革命后发动鸦片战争，中国被卷入资本主义世界市场。"},{"level":"选择题","text":"工业革命中重要的交通发明：1807 年富尔顿发明汽船，1825 年史蒂芬孙设计的蒸汽机车试车成功。","explain":""},{"level":"选择题","text":"本单元不含殖民地人民的反抗：玻利瓦尔领导的拉丁美洲独立运动、章西女王领导的印度民族大起义属九下第一单元《殖民地人民的反抗与资本主义制度的扩展》，学到这里时注意不要与本单元的工业革命影响混为一谈。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。","马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","中外联动：英国完成工业革命的时期（19 世纪中期）正是中国被坚船利炮打开国门的时期。1840 年鸦片战争后，中国一步步沦为半殖民地半封建社会；此后洋务运动学习西方的器物技术，正是对工业文明冲击的被动回应——中国的近代化是在西方工业文明的冲击下被迫启动的。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把工业革命的开始标志说成「瓦特改良蒸汽机」。","工业革命开始的标志是 18 世纪 60 年代哈格里夫斯发明珍妮纺纱机；瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志，把人类带入「蒸汽时代」。","「开始标志」与「重要标志」是两个不同的表述，考卷上常以此设陷阱。"],["认为工业革命首先发生在英国只是因为「英国人聪明」或「某项发明领先」。","工业革命首先发生在英国是多种条件综合作用的结果：君主立宪制的确立（政治前提）、海外市场的扩大、殖民掠夺积累的资本、圈地运动提供的自由劳动力、手工工场积累的技术与经验。","答「原因」必须分点罗列多个方面，只写一条会被判为不完整。"],["把工业革命的影响与殖民地人民的反抗混为一谈。","工业革命使西方列强实力大增、加紧殖民扩张（如英国发动鸦片战争）；殖民地人民的反抗（拉丁美洲独立运动、印度民族大起义）属九下第一单元，与工业革命有因果联系但不是同一单元的内容。","跨单元的因果关系容易被压成「同一件事」，答材料题时要分清「原因」与「结果」。"]]},{"type":"table","title":"工业革命时期的英国与清朝中国（中外对比：同一时期两种文明的碰撞）","head":["比较项","英国（19 世纪中期）","中国清朝（19 世纪中期）"],"rows":[["政治制度","君主立宪制，议会掌握国家权力","君主专制空前强化，皇帝独揽大权"],["生产方式","机器大工业，工厂制度确立","以小农经济为主，手工业与农业相结合"],["对外政策","积极对外扩张，抢占商品市场与原料产地","闭关锁国，仅留广州一处对外通商"],["科技教育","近代自然科学与工程技术迅速发展","八股取士，轻视科技，思想受到控制"],["碰撞结果","发动鸦片战争，打开中国市场","战败签订《南京条约》，开始沦为半殖民地半封建社会"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["工业革命的条件与影响","给出英国海外贸易、圈地运动等材料，要求概括工业革命首先发生在英国的原因；或给出工厂与城市化的图片、数据，要求分析工业革命的社会影响。"],["思想理论与工人运动","以《共产党宣言》片段为材料，考查马克思主义诞生的背景与意义，常与「工业革命造成两大阶级对立」构成完整的因果链。"],["中外联动与近代化反思","把工业革命与鸦片战争、洋务运动联系起来，要求说明「西方工业文明对中国的冲击」以及中国近代化探索的特点，是跨册综合题的高频考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：蒸汽机与能源转换；道德与法治：劳动、资本与社会公平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["蒸汽时代","第一次工业革命以蒸汽机为标志，人类进入以蒸汽为动力的时代。","2024 部编版九上第 20 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"瓦特","v":"英国发明家，改良蒸汽机。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"史蒂芬森","v":"英国工程师，设计蒸汽机车「旅行者号」。 出处：吴于廑、齐世荣《世界史·近代史编》"}]},{"type":"list","title":"延伸阅读","items":["瓦特改良蒸汽机：1785 年，瓦特改良的蒸汽机投入使用，为工厂提供稳定动力，推动机器大工业发展。 出处：吴于廑、齐世荣《世界史·近代史编》","工业革命的影响：生产力极大提高，人类进入「蒸汽时代」；社会分裂为工业资产阶级和工业无产阶级；也带来环境污染、贫富分化等问题。 出处：2024 部编版九上第 20 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 20 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。……它使未开化和半开化的国家从属于文明的国家，使农民的民族从属于资产阶级的民族，使东方从属于西方。——《共产党宣言》\n【材料二】19 世纪 40 年代，英国的生铁产量占世界的一半以上，棉纺织品大量销往海外。为了打开中国市场，英国于 1840 年发动鸦片战争，强迫清政府签订《南京条约》。\n【材料三】让统治阶级在共产主义革命面前发抖吧。无产者在这个革命中失去的只是锁链。他们获得的将是整个世界。全世界无产者，联合起来！——《共产党宣言》","source":"材料研读 · 工业革命和国际共产主义运动的兴起"}],"questions":[{"id":"h9a-u7-m1-q2","type":"short","stem":"（2）依据材料二，说明工业革命与鸦片战争之间的关系，并据此谈谈你的认识。（6 分）","answer":"关系：19 世纪中期英国率先完成工业革命，急需广阔的商品市场和原料产地。为了打开中国市场、倾销工业品并掠夺原料，英国于 1840 年发动鸦片战争，强迫清政府签订《南京条约》。鸦片战争是中国近代史的开端，中国开始沦为半殖民地半封建社会。认识：工业革命使西方国家的实力远强于中国，落后就要挨打；闭关锁国只会导致落后；中国必须顺应世界潮流，学习先进的制度与技术（如后来的洋务运动），才能摆脱被动挨打的局面。","explain":"","tags":["工业革命","中外联动"],"rubric":["答出英国完成工业革命需要市场与原料","答出为打开中国市场而发动鸦片战争","答出中国开始沦为半殖民地半封建社会","答出「落后就要挨打」或闭关锁国导致落后","答出要顺应潮流、学习先进制度与技术"]},{"id":"h9a-u7-q1","type":"choice","stem":"第一次工业革命开始的标志是","answer":"B","explain":"18 世纪 60 年代，纺织工人哈格里夫斯发明珍妮纺纱机，标志着第一次工业革命的开始；瓦特改良蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志。","options":["瓦特改良蒸汽机","哈格里夫斯发明珍妮纺纱机","史蒂芬孙设计蒸汽机车","富尔顿发明汽船"],"tags":["工业革命","时空观念"]},{"id":"h9a-u7-q2","type":"choice","stem":"第一次工业革命中，把人类带入「蒸汽时代」的最重要发明是","answer":"B","explain":"瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，摆脱了工厂对河流水力条件的依赖，蒸汽机的广泛应用使人类进入「蒸汽时代」。","options":["珍妮纺纱机","瓦特改良的蒸汽机","水力织布机","汽船"],"tags":["工业革命","历史解释"]},{"id":"cat-9a-7-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 哈格里夫斯发明珍妮纺纱机，工业革命开始\n② 瓦特改良的蒸汽机被用作纺织部门的动力机\n③ 富尔顿发明汽船；史蒂芬孙设计的蒸汽机车试车成功\n④ 英国率先完成工业革命，成为世界上第一个工业国家（…","answer":"A","explain":"按时间顺序应为：①哈格里夫斯发明珍妮纺纱机，工业革命开始（18 世纪 60 年代）→②瓦特改良的蒸汽机被用作纺织部门的动力机（1785 年以后）→③富尔顿发明汽船；史蒂芬孙设计的蒸汽机车试车成功（1807 年、1825 年）→④英国率先完成工业革命，成为世界上第一个工业国家（「世界工厂」）（19 世纪中期）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-1-g2","type":"choice","stem":"下列关于「第一次工业革命」的表述，错误的是","answer":"A","explain":"把工业革命的开始标志说成「瓦特改良蒸汽机」——「开始标志」与「重要标志」是两个不同的表述，考卷上常以此设陷阱。正确表述：工业革命开始的标志是 18 世纪 60 年代哈格里夫斯发明珍妮纺纱机；瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志，把人类带入「蒸汽时代」。","options":["把工业革命的开始标志说成「瓦特改良蒸汽机」。","工业革命开始的标志是 18 世纪 60 年代哈格里夫斯发明珍妮纺纱机；瓦特改良的蒸汽机在 1785 年以后被用作纺织部门的动力机，是工业革命的重要标志，把人类带入「蒸汽时代」。","工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1785 年，瓦特改良的蒸汽机投入使用，为工厂提供稳定动力，推动机器大工业发展。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第一次工业革命；第一次工业革命首先从英国的棉纺织业开始，18 世纪 60 年代珍妮纺纱机的发明标志着工业革命的开始，瓦特改良的蒸汽机使人类进入「蒸汽时代」。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-7-2","title":"第21课 马克思主义的诞生和国际共产主义运动的兴起","subtitle":"九年级上册 · 第七单元 工业革命和国际共产主义运动的兴起","grade":"9a","tags":["九年级上册","第七单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第七单元 工业革命和国际共产主义运动的兴起"},{"k":"课时","v":"第21课 马克思主义的诞生和国际共产主义运动的兴起"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"工业革命后，工人运动兴起。1848 年，马克思、恩格斯为共产主义者同盟起草的《共产党宣言》发表，标志马克思主义诞生。1871 年巴黎公社成立，是无产阶级建立政权的第一次伟大尝试。"},{"type":"note","title":"本课主线 · 因果链","text":"18 世纪 60 年代从英国棉纺织业开始的工业革命用机器生产取代了手工劳动，人类进入「蒸汽时代」，英国成为「世界工厂」，社会也日益分裂为工业资产阶级与工业无产阶级两大对立阶级；工人运动的兴起催生了 1848 年《共产党宣言》的发表和 1871 年巴黎公社的成立。与中国史的联动点是：英国完成工业革命后发动鸦片战争，中国被卷入资本主义世界市场。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1848 年","《共产党宣言》发表，标志马克思主义的诞生","由马克思、恩格斯为共产主义者同盟起草，号召「全世界无产者，联合起来！」 · 重点"],["1871 年","巴黎公社成立，这是世界历史上第一个无产阶级政权","1871 年 3 月 18 日巴黎人民起义，3 月 28 日公社成立，5 月底失败，史称「五月流血周」 · 重点"],["1864 年","第一国际（国际工人协会）成立","马克思是创始人之一，推动了国际工人运动的发展"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1848 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"《共产党宣言》发表，标志马克思主义的…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1871 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"巴黎公社成立，这是世界历史上第一个无…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1864 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"第一国际（国际工人协会）成立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1848 年《共产党宣言》的发表标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。","explain":"马克思主义由马克思、恩格斯创立，包括马克思主义哲学、政治经济学和科学社会主义三部分。要能记住《宣言》中的名句并理解其历史意义。"},{"level":"重点","text":"1871 年巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试。","explain":"常考「巴黎公社失败的原因」与「为什么说它是无产阶级政权」：公社委员由选举产生、代表工人利益、废除旧军队与旧警察，但缺乏无产阶级政党的领导与经验，最终失败。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["工业革命的条件与影响","给出英国海外贸易、圈地运动等材料，要求概括工业革命首先发生在英国的原因；或给出工厂与城市化的图片、数据，要求分析工业革命的社会影响。"],["思想理论与工人运动","以《共产党宣言》片段为材料，考查马克思主义诞生的背景与意义，常与「工业革命造成两大阶级对立」构成完整的因果链。"],["中外联动与近代化反思","把工业革命与鸦片战争、洋务运动联系起来，要求说明「西方工业文明对中国的冲击」以及中国近代化探索的特点，是跨册综合题的高频考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：蒸汽机与能源转换；道德与法治：劳动、资本与社会公平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["全世界无产者，联合起来","《共产党宣言》结尾口号，成为国际工人运动的号召。","《共产党宣言》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"马克思","v":"科学社会主义创始人，著《资本论》《共产党宣言》。 出处：《共产党宣言》"},{"k":"恩格斯","v":"马克思主义创始人之一，与马克思共同起草《共产党宣言》。 出处：《共产党宣言》"}]},{"type":"list","title":"延伸阅读","items":["《共产党宣言》：系统阐述科学社会主义基本原理，指出阶级斗争推动历史发展，宣告「无产者在这个革命中失去的只是锁链，他们获得的将是整个世界」。 出处：《共产党宣言》原文","巴黎公社：1871 年 3 月 18 日巴黎工人起义，建立公社，存在 72 天，5 月 28 日在凡尔赛军镇压下失败。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 21 课；《共产党宣言》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】资产阶级在它的不到一百年的阶级统治中所创造的生产力，比过去一切世代创造的全部生产力还要多，还要大。……它使未开化和半开化的国家从属于文明的国家，使农民的民族从属于资产阶级的民族，使东方从属于西方。——《共产党宣言》\n【材料二】19 世纪 40 年代，英国的生铁产量占世界的一半以上，棉纺织品大量销往海外。为了打开中国市场，英国于 1840 年发动鸦片战争，强迫清政府签订《南京条约》。\n【材料三】让统治阶级在共产主义革命面前发抖吧。无产者在这个革命中失去的只是锁链。他们获得的将是整个世界。全世界无产者，联合起来！——《共产党宣言》","source":"材料研读 · 工业革命和国际共产主义运动的兴起"}],"questions":[{"id":"h9a-u7-q3","type":"choice","stem":"1848 年《共产党宣言》的发表，标志着","answer":"B","explain":"1848 年，马克思、恩格斯为共产主义者同盟起草的《共产党宣言》发表，标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。","options":["国际工人协会的成立","马克思主义的诞生","巴黎公社的建立","第一个无产阶级政权的建立"],"tags":["《共产党宣言》","时空观念"]},{"id":"h9a-u7-q4","type":"choice","stem":"巴黎公社在世界历史上的重要地位是","answer":"A","explain":"1871 年 3 月 28 日巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试，但只存在了两个多月就失败了，并未改变法国的社会性质。","options":["世界上第一个无产阶级政权","第一个社会主义国家","国际工人运动的第一个组织","第一次取得胜利的社会主义革命"],"tags":["巴黎公社","历史解释"]},{"id":"cat-9a-7-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 《共产党宣言》发表，标志马克思主义的诞生\n② 巴黎公社成立，这是世界历史上第一个无产阶级政权\n③ 第一国际（国际工人协会）成立","answer":"A","explain":"按时间顺序应为：①《共产党宣言》发表，标志马克思主义的诞生（1848 年）→②巴黎公社成立，这是世界历史上第一个无产阶级政权（1871 年）→③第一国际（国际工人协会）成立（1864 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-2-g2","type":"choice","stem":"下列关于「马克思主义的诞生和国际共产主义运…」的表述，错误的是","answer":"A","explain":"认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家——要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。正确表述：巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","options":["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","1848 年《共产党宣言》的发表标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-2-g3","type":"choice","stem":"下列结论中，属于「马克思主义的诞生和国际共产主义运…」的是","answer":"A","explain":"本课结论：马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。","中外联动：英国完成工业革命的时期（19 世纪中期）正是中国被坚船利炮打开国门的时期。1840 年鸦片战争后，中国一步步沦为半殖民地半封建社会；此后洋务运动学习西方的器物技术，正是对工业文明冲击的被动回应——中国的近代化是在西方工业文明的冲击下被迫启动的。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：系统阐述科学社会主义基本原理，指出阶级斗争推动历史发展，宣告「无产者在这个革命中失去的只是锁链，他们获得的将是整个世界」。（《共产党宣言》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"马克思主义的诞生和国际共产主义运动的兴起；1848 年《共产党宣言》的发表标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。","explain":"材料出自《共产党宣言》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9a-7-3","title":"第22课 活动课 唱响《国际歌》","subtitle":"九年级上册 · 第七单元 工业革命和国际共产主义运动的兴起","grade":"9a","tags":["九年级上册","第七单元","活动课"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级上册"},{"k":"单元","v":"第七单元 工业革命和国际共产主义运动的兴起"},{"k":"课时","v":"第22课 活动课 唱响《国际歌》"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"本课是活动课，学唱《国际歌》。1871 年巴黎公社失败后，欧仁·鲍狄埃创作歌词，1888 年皮埃尔·狄盖特谱曲，歌曲成为国际工人运动的战歌。"},{"type":"note","title":"本课主线 · 因果链","text":"18 世纪 60 年代从英国棉纺织业开始的工业革命用机器生产取代了手工劳动，人类进入「蒸汽时代」，英国成为「世界工厂」，社会也日益分裂为工业资产阶级与工业无产阶级两大对立阶级；工人运动的兴起催生了 1848 年《共产党宣言》的发表和 1871 年巴黎公社的成立。与中国史的联动点是：英国完成工业革命后发动鸦片战争，中国被卷入资本主义世界市场。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1871 年","巴黎公社成立，这是世界历史上第一个无产阶级政权","1871 年 3 月 18 日巴黎人民起义，3 月 28 日公社成立，5 月底失败，史称「五月流血周」 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"1871 年巴黎公社成立，这是世界历…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":27.17,"text":"工业革命是生产技术的革命，也是社…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"工业革命首先发生在英国不是偶然的，而…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"马克思主义的诞生是工业革命后资本主义…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1871 年巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试。","explain":"常考「巴黎公社失败的原因」与「为什么说它是无产阶级政权」：公社委员由选举产生、代表工人利益、废除旧军队与旧警察，但缺乏无产阶级政党的领导与经验，最终失败。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。","马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["工业革命的条件与影响","给出英国海外贸易、圈地运动等材料，要求概括工业革命首先发生在英国的原因；或给出工厂与城市化的图片、数据，要求分析工业革命的社会影响。"],["思想理论与工人运动","以《共产党宣言》片段为材料，考查马克思主义诞生的背景与意义，常与「工业革命造成两大阶级对立」构成完整的因果链。"],["中外联动与近代化反思","把工业革命与鸦片战争、洋务运动联系起来，要求说明「西方工业文明对中国的冲击」以及中国近代化探索的特点，是跨册综合题的高频考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：蒸汽机与能源转换；道德与法治：劳动、资本与社会公平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["英特纳雄耐尔","《国际歌》中「Internationale」的音译，意为国际主义、国际工人协会。","《国际歌》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"鲍狄埃","v":"法国诗人，巴黎公社社员，《国际歌》词作者。 出处：2024 部编版九上第 22 课"},{"k":"狄盖特","v":"比利时工人作曲家，《国际歌》曲作者。 出处：2024 部编版九上第 22 课"}]},{"type":"list","title":"延伸阅读","items":["《国际歌》的诞生：1871 年 6 月，巴黎公社诗人鲍狄埃在失败后写下歌词；1888 年，比利时工人作曲家狄盖特为其谱曲，同年 6 月在里尔纪念活动上首次演唱。 出处：2024 部编版九上第 22 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九上第 22 课；《国际歌》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9a-u7-q3","type":"choice","stem":"1848 年《共产党宣言》的发表，标志着","answer":"B","explain":"1848 年，马克思、恩格斯为共产主义者同盟起草的《共产党宣言》发表，标志着马克思主义的诞生，从此国际工人运动有了科学理论的指导。","options":["国际工人协会的成立","马克思主义的诞生","巴黎公社的建立","第一个无产阶级政权的建立"],"tags":["《共产党宣言》","时空观念"]},{"id":"h9a-u7-q4","type":"choice","stem":"巴黎公社在世界历史上的重要地位是","answer":"A","explain":"1871 年 3 月 28 日巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试，但只存在了两个多月就失败了，并未改变法国的社会性质。","options":["世界上第一个无产阶级政权","第一个社会主义国家","国际工人运动的第一个组织","第一次取得胜利的社会主义革命"],"tags":["巴黎公社","历史解释"]},{"id":"cat-9a-7-3-g2","type":"choice","stem":"下列关于「活动课 唱响《国际歌》」的表述，错误的是","answer":"A","explain":"认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家——要准确使用「第一次伟大尝试」这一表述，不能夸大为「建立起社会主义制度」。正确表述：巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","options":["认为巴黎公社推翻了法国的资本主义制度、建立了社会主义国家。","巴黎公社只存在了两个多月（1871 年 3 月 28 日—5 月底），是无产阶级建立政权的第一次伟大尝试，最终失败，并未改变法国的社会性质。","工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-3-g3","type":"choice","stem":"下列结论中，属于「活动课 唱响《国际歌》」的是","answer":"A","explain":"本课结论：工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["工业革命是生产技术的革命，也是社会关系的革命：机器生产取代手工劳动，工厂制度确立，工业资产阶级与工业无产阶级成为近代社会的两大阶级。","工业革命首先发生在英国不是偶然的，而是政治制度、市场、资本、劳动力、技术等多种因素共同作用的结果，其中君主立宪制的确立提供了政治前提，广阔的海外市场和殖民掠夺提供了资本与市场。","马克思主义的诞生是工业革命后资本主义矛盾发展的必然结果：工业无产阶级的壮大与工人运动的兴起，为科学社会主义理论提供了阶级基础。","中外联动：英国完成工业革命的时期（19 世纪中期）正是中国被坚船利炮打开国门的时期。1840 年鸦片战争后，中国一步步沦为半殖民地半封建社会；此后洋务运动学习西方的器物技术，正是对工业文明冲击的被动回应——中国的近代化是在西方工业文明的冲击下被迫启动的。"],"difficulty":2,"tags":["九年级上册","第七单元","本课练习"]},{"id":"cat-9a-7-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1871 年 6 月，巴黎公社诗人鲍狄埃在失败后写下歌词；1888 年，比利时工人作曲家狄盖特为其谱曲，同年 6 月在里尔纪念活动上首次演唱。（2024 部编版九上第 22 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"活动课 唱响《国际歌》；1871 年巴黎公社成立，这是世界历史上第一个无产阶级政权，是无产阶级建立政权的第一次伟大尝试。","explain":"材料出自2024 部编版九上第 22 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级上册","第七单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-1-1","title":"第1课 殖民地人民的反抗战争","subtitle":"九年级下册 · 第一单元 殖民地人民的反抗与资本主义制度的扩展","grade":"9b","tags":["九年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第一单元 殖民地人民的反抗与资本主义制度的扩展"},{"k":"课时","v":"第1课 殖民地人民的反抗战争"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"18 世纪末 19 世纪初，拉丁美洲人民在玻利瓦尔、圣马丁领导下争取独立；1857—1859 年印度爆发民族大起义，章西女王英勇抗英。这些斗争打击了殖民统治，为亚非拉民族独立运动奠定基础。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪，工业革命使资本主义制度需要更广阔的原料产地和市场：一方面殖民地半殖民地人民掀起反抗殖民统治的民族解放运动（拉美独立运动、印度民族大起义），另一方面俄国以自上而下的改革、美国以南北战争、日本以明治维新，使资本主义制度在世界范围内确立和扩展——世界市场与列强争霸的格局由此奠定。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["19 世纪初","拉丁美洲独立运动兴起","玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）"],["1857—1859 年","印度民族大起义","反抗英国殖民统治，章西女王是杰出代表；起义虽失败，但沉重打击了英国殖民统治 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"19 世纪初","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"拉丁美洲独立运动兴起","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1857—1859 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"印度民族大起义","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。","explain":"常考「人物—地区」配对（玻利瓦尔→南美北部，圣马丁→南美南部），落点是「殖民地人民反抗殖民压迫的民族解放运动」。"},{"level":"重点","text":"印度民族大起义（1857—1859）：反抗英国殖民统治，章西女王是杰出代表；起义失败，但沉重打击了英国殖民统治，表现了印度人民不屈的斗争精神。","explain":"要能答出「失败但不能说没有意义」：它打击了英国殖民统治，也支援了亚洲其他地区的民族解放运动。"},{"level":"选择题","text":"玻利瓦尔、圣马丁、章西女王、亚历山大二世、林肯、明治天皇等历史人物及其主要贡献。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——方式不同，方向一致。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","哪里有压迫，哪里就有反抗：拉丁美洲独立运动与印度民族大起义都是殖民地人民反抗殖民统治的民族解放运动，打击了殖民体系。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。"],["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革与革命的路径比较","以「俄国改革—美国内战—日本明治维新」为材料，要求归纳 19 世纪中期各国扫除资本主义发展障碍的方式，答案结构固定为「改革 / 内战 / 改革」，再分别说明其共同作用。"],["中国史联动的改革成败分析","把明治维新与戊戌变法（八上已学）并置，要求从领导力量、实权、群众基础等角度分析成败原因，是中外对比大题的高频考法。"],["国家统一与民族解放的主题","美国内战考「维护国家统一」，拉美独立运动与印度民族大起义考「反抗殖民统治」，常以人物图像、地图或名言材料切入，落点在家国情怀与正义立场。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：民族独立与改革；地理：俄国、美国、日本的资源与区位。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"玻利瓦尔","v":"拉美独立运动领袖，被誉为「解放者」。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"圣马丁","v":"拉美独立运动领袖，解放南美南部地区。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"章西女王","v":"印度民族大起义领袖之一。 出处：2024 部编版九下第 1 课"}]},{"type":"list","title":"延伸阅读","items":["南美的解放者：玻利瓦尔率军解放委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁等地，被誉为「解放者」；圣马丁解放阿根廷、智利、秘鲁。 出处：吴于廑、齐世荣《世界史·近代史编》","章西女王：印度民族大起义中，章西女王率军抗英，1858 年战死沙场，成为印度民族英雄。 出处：2024 部编版九下第 1 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 1 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u1-q1","type":"choice","stem":"19 世纪，印度爆发了反抗英国殖民统治的民族大起义，其杰出领导人是","answer":"B","explain":"1857—1859 年印度民族大起义反抗英国殖民统治，章西女王是杰出代表。玻利瓦尔是拉美独立运动领袖，甘地领导的是 20 世纪的印度非暴力不合作运动，凯末尔领导的是土耳其革命。","options":["玻利瓦尔","章西女王","甘地","凯末尔"],"tags":["印度民族大起义","时空观念"]},{"id":"cat-9b-1-1-g2","type":"choice","stem":"下列关于「殖民地人民的反抗战争」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——方式不同，方向一致。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：玻利瓦尔率军解放委内瑞拉、哥伦比亚、厄瓜多尔、秘鲁等地，被誉为「解放者」；圣马丁解放阿根廷、智利、秘鲁。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"殖民地人民的反抗战争；拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-1-g5","type":"choice","stem":"「拉丁美洲独立运动兴起」发生于","answer":"A","explain":"本课时间轴：拉丁美洲独立运动兴起（19 世纪初）。玻利瓦尔解放哥伦比亚、委内瑞拉、厄瓜多尔等地，圣马丁领导阿根廷、智利、秘鲁的独立运动；1804 年海地独立揭开序幕（拉美第一个独立国家）。其余三个时间是同一单元相邻课时的事件时间。","options":["19 世纪初","1861 年","1861—1865 年","1871 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-1-g6","type":"choice","stem":"下列考点中，属于「殖民地人民的反抗战争」的是","answer":"A","explain":"本课考点（重点）：拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，1804 年海地独立揭开序幕。其余三项是同一单元相邻课时的考点。","options":["拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买…","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废…","19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新…"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]}]},{"id":"cat-9b-1-2","title":"第2课 俄国的改革","subtitle":"九年级下册 · 第一单元 殖民地人民的反抗与资本主义制度的扩展","grade":"9b","tags":["九年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第一单元 殖民地人民的反抗与资本主义制度的扩展"},{"k":"课时","v":"第2课 俄国的改革"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪中期，俄国农奴制严重阻碍资本主义发展。1861 年，亚历山大二世颁布废除农奴制法令：农奴获得人身自由，可以赎买份地。改革使俄国走上发展资本主义的道路，但保留大量封建残余。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪，工业革命使资本主义制度需要更广阔的原料产地和市场：一方面殖民地半殖民地人民掀起反抗殖民统治的民族解放运动（拉美独立运动、印度民族大起义），另一方面俄国以自上而下的改革、美国以南北战争、日本以明治维新，使资本主义制度在世界范围内确立和扩展——世界市场与列强争霸的格局由此奠定。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1861 年","俄国农奴制改革","沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点 · 重点"],["1861—1865 年","美国南北战争","根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜 · 重点"],["1871 年","德意志帝国成立（普法战争后）","与 1861 年意大利王国建立同为「资本主义制度在世界范围内扩展」的时代背景；教材未展开，作背景了解即可"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1861 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"俄国农奴制改革","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1861—1865 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"美国南北战争","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1871 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"德意志帝国成立（普法战争后）","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。","explain":"评价必须「两点论」：进步性（解放劳动力、促进资本主义发展、是俄国历史上的重要转折点）+ 局限性（保留沙皇专制、地主仍占有大量土地，农奴制残余阻碍俄国经济发展）。"},{"level":"重点","text":"美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。","explain":"答题要点是「统一 + 奴隶制 + 资本主义发展」三件事，缺一不可。注意林肯的首要目标是维护国家统一，废奴是与维护统一相结合的。"},{"level":"次重点","text":"19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新）以不同方式扫除了资本主义发展的障碍。","explain":""},{"level":"选择题","text":"玻利瓦尔、圣马丁、章西女王、亚历山大二世、林肯、明治天皇等历史人物及其主要贡献。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。"]]},{"type":"table","title":"俄国 1861 年农奴制改革与日本明治维新（同一时期两种「自上而下」改革的比较）","head":["比较项","俄国农奴制改革（1861）","日本明治维新（1868 年起）"],"rows":[["面临的问题","农奴制阻碍资本主义发展，克里米亚战争失败暴露落后","幕府统治危机与民族危机（美国等国入侵）交织"],["推动者","沙皇亚历山大二世","明治天皇与倒幕派（中下级武士）"],["主要措施","废除农奴制，农奴获得人身自由，可赎买份地","废藩置县、殖产兴业、征兵制、文明开化"],["结果","走上发展资本主义的道路，成为欧洲强国，但保留大量封建残余","走上发展资本主义的道路，摆脱沦为半殖民地的危机，成为亚洲强国"],["共同局限","都保留大量封建残余，都走上对外扩张的道路","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革与革命的路径比较","以「俄国改革—美国内战—日本明治维新」为材料，要求归纳 19 世纪中期各国扫除资本主义发展障碍的方式，答案结构固定为「改革 / 内战 / 改革」，再分别说明其共同作用。"],["中国史联动的改革成败分析","把明治维新与戊戌变法（八上已学）并置，要求从领导力量、实权、群众基础等角度分析成败原因，是中外对比大题的高频考法。"],["国家统一与民族解放的主题","美国内战考「维护国家统一」，拉美独立运动与印度民族大起义考「反抗殖民统治」，常以人物图像、地图或名言材料切入，落点在家国情怀与正义立场。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：民族独立与改革；地理：俄国、美国、日本的资源与区位。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"亚历山大二世","v":"俄国沙皇，1861 年推行废除农奴制改革。 出处：《1861 年法令》原文"}]},{"type":"list","title":"延伸阅读","items":["改革的内容：农奴获得人身自由，有权拥有财产、从事工商活动；地主不得买卖农奴；农奴可赎买份地，但须支付高额赎金。 出处：《1861 年法令》原文","改革的局限：改革由沙皇自上而下推行，保留沙皇专制和地主土地所有制，农民负担沉重，社会矛盾并未根本解决。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 2 课；《1861 年法令》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】自 1863 年 1 月 1 日起，凡在当地人民尚在反抗合众国的任何一州之内，为人占有而做奴隶的人们，都应在那时及以后永远获得自由；合众国政府行政部门，包括陆海军当局，将承认并保障这些人的自由。——《解放黑人奴隶宣言》（1862 年颁布，1863 年 1 月 1 日起生效）\n【材料二】1861 年，沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，地主不得买卖农奴；农奴可以赎买的方式获得一块份地，但必须向地主缴纳大量赎金。\n【材料三】1868 年起，明治政府废除藩国、设置府县，加强中央集权；允许土地买卖，引进西方技术，鼓励发展近代工业；实行征兵制，建立新式军队；提倡「文明开化」，向欧美学习，努力发展教育。","source":"材料研读 · 殖民地人民的反抗与资本主义制度的扩展"}],"questions":[{"id":"h9b-u1-q2","type":"choice","stem":"1861 年，俄国沙皇亚历山大二世签署废除农奴制的法令。这项改革的性质是","answer":"B","explain":"改革由沙皇政府自上而下推行，使农奴获得人身自由、为资本主义发展提供了自由劳动力与市场，因此是自上而下的资产阶级性质的改革；但它保留了大量封建残余，不是「彻底」废除封建制度。","options":["自下而上的农民起义","自上而下的资产阶级性质的改革","无产阶级社会主义革命","彻底废除封建制度的民主革命"],"tags":["俄国农奴制改革","历史解释"]},{"id":"cat-9b-1-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 俄国农奴制改革\n② 美国南北战争\n③ 德意志帝国成立（普法战争后）","answer":"A","explain":"按时间顺序应为：①俄国农奴制改革（1861 年）→②美国南北战争（1861—1865 年）→③德意志帝国成立（普法战争后）（1871 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g2","type":"choice","stem":"下列关于「俄国的改革」的表述，错误的是","answer":"A","explain":"认为俄国 1861 年改革彻底废除了封建制度——「彻底」「完全」是选择题的常见错误表述；改革只是缓解矛盾、推动资本主义发展，没有改变社会性质。正确表述：改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","options":["认为俄国 1861 年改革彻底废除了封建制度。","改革使农奴获得人身自由，是自上而下的资产阶级性质的改革，但保留了大量封建残余（沙皇专制、地主土地占有制），农奴赎买的份地价格远高于实际价值。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。","俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：农奴获得人身自由，有权拥有财产、从事工商活动；地主不得买卖农奴；农奴可赎买份地，但须支付高额赎金。（《1861 年法令》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"俄国的改革；俄国农奴制改革（1861）：亚历山大二世颁布废除农奴制的法令，农奴获得人身自由、可以赎买份地；是自上而下的资产阶级性质的改革，推动俄国走上发展资本主义的道路，但保留大量封建残余。","explain":"材料出自《1861 年法令》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-2-g5","type":"choice","stem":"「俄国农奴制改革」发生于","answer":"A","explain":"本课时间轴：俄国农奴制改革（1861 年）。沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，可通过赎买获得份地——俄国历史上的重要转折点。其余三个时间是同一单元相邻课时的事件时间。","options":["1861 年","19 世纪初","1857—1859 年","1861—1865 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]}]},{"id":"cat-9b-1-3","title":"第3课 美国内战","subtitle":"九年级下册 · 第一单元 殖民地人民的反抗与资本主义制度的扩展","grade":"9b","tags":["九年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第一单元 殖民地人民的反抗与资本主义制度的扩展"},{"k":"课时","v":"第3课 美国内战"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪中期，美国北方资本主义工业与南方奴隶制种植园经济矛盾激化，焦点是奴隶制存废。1861 年南北战争爆发，林肯政府颁布《宅地法》和《解放黑人奴隶宣言》，扭转战局。1865 年北方获胜，维护了国家统一。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪，工业革命使资本主义制度需要更广阔的原料产地和市场：一方面殖民地半殖民地人民掀起反抗殖民统治的民族解放运动（拉美独立运动、印度民族大起义），另一方面俄国以自上而下的改革、美国以南北战争、日本以明治维新，使资本主义制度在世界范围内确立和扩展——世界市场与列强争霸的格局由此奠定。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1861—1865 年","美国南北战争","根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜 · 重点"],["1862 年","林肯颁布《宅地法》和《解放黑人奴隶宣言》","宣言自 1863 年 1 月 1 日起生效，黑人踊跃参军，扭转了战局——北方取胜的关键 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1861—1865 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"美国南北战争","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1862 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"林肯颁布《宅地法》和《解放黑人奴隶宣…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。","explain":"答题要点是「统一 + 奴隶制 + 资本主义发展」三件事，缺一不可。注意林肯的首要目标是维护国家统一，废奴是与维护统一相结合的。"},{"level":"选择题","text":"玻利瓦尔、圣马丁、章西女王、亚历山大二世、林肯、明治天皇等历史人物及其主要贡献。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["林肯的贡献在于维护了国家统一、废除了奴隶制，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革与革命的路径比较","以「俄国改革—美国内战—日本明治维新」为材料，要求归纳 19 世纪中期各国扫除资本主义发展障碍的方式，答案结构固定为「改革 / 内战 / 改革」，再分别说明其共同作用。"],["中国史联动的改革成败分析","把明治维新与戊戌变法（八上已学）并置，要求从领导力量、实权、群众基础等角度分析成败原因，是中外对比大题的高频考法。"],["国家统一与民族解放的主题","美国内战考「维护国家统一」，拉美独立运动与印度民族大起义考「反抗殖民统治」，常以人物图像、地图或名言材料切入，落点在家国情怀与正义立场。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：民族独立与改革；地理：俄国、美国、日本的资源与区位。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["民有、民治、民享","林肯葛底斯堡演说中的名句，形容政府属于人民、由人民治理、为人民服务。","林肯《葛底斯堡演说》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"林肯","v":"美国第 16 任总统，领导南北战争，废除奴隶制。 出处：吴于廑、齐世荣《世界史·近代史编》"}]},{"type":"list","title":"延伸阅读","items":["《解放黑人奴隶宣言》：1862 年 9 月林肯颁布，宣布自 1863 年 1 月 1 日起，叛乱各州的奴隶一律获得自由，可参加联邦军队。 出处：《解放黑人奴隶宣言》原文","林肯遇刺：1865 年 4 月 14 日，林肯在华盛顿福特剧院被刺杀，次日去世。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 3 课；《解放黑人奴隶宣言》原文","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】自 1863 年 1 月 1 日起，凡在当地人民尚在反抗合众国的任何一州之内，为人占有而做奴隶的人们，都应在那时及以后永远获得自由；合众国政府行政部门，包括陆海军当局，将承认并保障这些人的自由。——《解放黑人奴隶宣言》（1862 年颁布，1863 年 1 月 1 日起生效）\n【材料二】1861 年，沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，地主不得买卖农奴；农奴可以赎买的方式获得一块份地，但必须向地主缴纳大量赎金。\n【材料三】1868 年起，明治政府废除藩国、设置府县，加强中央集权；允许土地买卖，引进西方技术，鼓励发展近代工业；实行征兵制，建立新式军队；提倡「文明开化」，向欧美学习，努力发展教育。","source":"材料研读 · 殖民地人民的反抗与资本主义制度的扩展"}],"questions":[{"id":"h9b-u1-q3","type":"choice","stem":"美国南北战争爆发前，南北方矛盾斗争的焦点是","answer":"B","explain":"南北两种经济制度（北方资本主义工商业与南方种植园奴隶制经济）的矛盾日益尖锐，焦点是奴隶制的存废问题；林肯当选总统成为战争爆发的导火线。","options":["关税税率的高低","奴隶制的存废问题","西部领土的扩张方向","总统选举的方式"],"tags":["美国内战","历史解释"]},{"id":"h9b-u1-q4","type":"choice","stem":"使美国南北战争的战局发生扭转、为北方军队提供雄厚兵源的文件是","answer":"B","explain":"1862 年林肯颁布《宅地法》和《解放黑人奴隶宣言》，宣言宣布叛乱各州奴隶永远获得自由，黑人踊跃参军，扭转了战局。《独立宣言》《1787 年宪法》均为美国独立战争时期的文件。","options":["《独立宣言》","《解放黑人奴隶宣言》","《人权宣言》","1787 年美国宪法"],"tags":["美国内战","史料实证"]},{"id":"cat-9b-1-3-g2","type":"choice","stem":"下列关于「美国内战」的表述，错误的是","answer":"A","explain":"认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制——「根本原因」与「导火线」的区分是必考得分点，答题时要先答经济制度矛盾，再答导火线。正确表述：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","options":["认为美国南北战争爆发的原因是林肯当选总统后立即宣布废除奴隶制。","根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废问题；林肯当选总统是导火线。林肯执政初期的首要目标是维护国家统一。","林肯的贡献在于维护了国家统一、废除了奴隶制，为美国经济的迅速发展创造了条件；评价历史人物要看其是否推动社会进步、是否符合人民利益。","美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1862 年 9 月林肯颁布，宣布自 1863 年 1 月 1 日起，叛乱各州的奴隶一律获得自由，可参加联邦军队。（《解放黑人奴隶宣言》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"美国内战；美国南北战争（1861—1865）：根本原因是南北两种经济制度的矛盾，焦点是奴隶制的存废；林肯颁布《宅地法》和《解放黑人奴隶宣言》，1865 年北方取胜。意义：维护了国家统一，废除了奴隶制，为经济迅速发展创造了条件。","explain":"材料出自《解放黑人奴隶宣言》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-3-g5","type":"choice","stem":"「美国南北战争」发生于","answer":"A","explain":"本课时间轴：美国南北战争（1861—1865 年）。根本原因是南北两种经济制度的矛盾（焦点是奴隶制的存废）；1861 年南方军队挑起内战，1865 年北方获胜。其余三个时间是同一单元相邻课时的事件时间。","options":["1861—1865 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]}]},{"id":"cat-9b-1-4","title":"第4课 日本明治维新","subtitle":"九年级下册 · 第一单元 殖民地人民的反抗与资本主义制度的扩展","grade":"9b","tags":["九年级下册","第一单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第一单元 殖民地人民的反抗与资本主义制度的扩展"},{"k":"课时","v":"第4课 日本明治维新"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪中期，日本面临民族危机，幕府统治腐朽。1868 年明治政府推行改革：废藩置县、殖产兴业、文明开化、实行征兵制。明治维新使日本走上资本主义道路，但保留大量封建残余，逐步走上对外侵略扩张道路。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪，工业革命使资本主义制度需要更广阔的原料产地和市场：一方面殖民地半殖民地人民掀起反抗殖民统治的民族解放运动（拉美独立运动、印度民族大起义），另一方面俄国以自上而下的改革、美国以南北战争、日本以明治维新，使资本主义制度在世界范围内确立和扩展——世界市场与列强争霸的格局由此奠定。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1868 年","日本明治维新开始","推翻幕府统治后，明治政府推行废藩置县、殖产兴业、征兵制、文明开化等改革，日本走上发展资本主义的道路 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"日本明治维新（1868 年起）：废藩…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"19 世纪中期资本主义制度的扩展：俄…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":41.33,"text":"19 世纪中期，资本主义制度在世界范…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"改革是社会进步的重要方式：俄国 18…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近代工业）、实行征兵制（建立新式军队）、提倡「文明开化」（发展教育）。使日本走上发展资本主义的道路，成为亚洲强国，但保留大量封建残余并走向对外扩张。","explain":"最常考「明治维新为什么能成功」：改革派掌握实权、有武装力量、措施全面；与中国的戊戌变法形成必考对比。"},{"level":"次重点","text":"19 世纪中期资本主义制度的扩展：俄国（1861 年改革）、美国（内战）、日本（明治维新）以不同方式扫除了资本主义发展的障碍。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——方式不同，方向一致。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把明治维新的「废藩置县」与「殖产兴业」混为一谈。","废藩置县是政治措施（废除藩国、设置府县，加强中央集权）；殖产兴业是经济措施（引进西方技术、发展近代工业）。","材料题要求「按政治、经济、军事、文化分类概括措施」，混在一起就丢分。"]]},{"type":"table","title":"俄国 1861 年农奴制改革与日本明治维新（同一时期两种「自上而下」改革的比较）","head":["比较项","俄国农奴制改革（1861）","日本明治维新（1868 年起）"],"rows":[["面临的问题","农奴制阻碍资本主义发展，克里米亚战争失败暴露落后","幕府统治危机与民族危机（美国等国入侵）交织"],["推动者","沙皇亚历山大二世","明治天皇与倒幕派（中下级武士）"],["主要措施","废除农奴制，农奴获得人身自由，可赎买份地","废藩置县、殖产兴业、征兵制、文明开化"],["结果","走上发展资本主义的道路，成为欧洲强国，但保留大量封建残余","走上发展资本主义的道路，摆脱沦为半殖民地的危机，成为亚洲强国"],["共同局限","都保留大量封建残余，都走上对外扩张的道路","同左"]]},{"type":"table","title":"日本明治维新与中国戊戌变法（中国史联动）（中外对比：同为 19 世纪后期学习西方的改革，为何一成一败）","head":["比较项","日本明治维新（1868）","中国戊戌变法（1898）"],"rows":[["背景","幕府统治腐朽，面临西方入侵的民族危机","甲午战败，民族危机空前严重"],["领导力量","明治天皇与倒幕派掌握实权、拥有武装","光绪帝与康有为、梁启超，依靠没有实权的皇帝"],["主要措施","废藩置县、殖产兴业、征兵制、文明开化","裁撤冗官、鼓励私人兴办工矿企业、开办新式学堂、训练新式军队"],["结果","成功，走上发展资本主义的道路，成为亚洲强国","失败，变法仅百余天即被镇压，戊戌六君子遇害"],["成败关键","改革派掌握实权，有武装力量，措施全面且得到推行","依靠无实权的皇帝，顽固派力量强大，缺乏群众基础"],["共同启示","改革要成功，必须有强有力的领导核心与相应实力，要顺应历史潮流","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["改革与革命的路径比较","以「俄国改革—美国内战—日本明治维新」为材料，要求归纳 19 世纪中期各国扫除资本主义发展障碍的方式，答案结构固定为「改革 / 内战 / 改革」，再分别说明其共同作用。"],["中国史联动的改革成败分析","把明治维新与戊戌变法（八上已学）并置，要求从领导力量、实权、群众基础等角度分析成败原因，是中外对比大题的高频考法。"],["国家统一与民族解放的主题","美国内战考「维护国家统一」，拉美独立运动与印度民族大起义考「反抗殖民统治」，常以人物图像、地图或名言材料切入，落点在家国情怀与正义立场。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：民族独立与改革；地理：俄国、美国、日本的资源与区位。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["文明开化","明治维新时期提倡学习西方文明、改变社会风俗的口号。","2024 部编版九下第 4 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"明治天皇","v":"日本天皇，1868 年推行明治维新。 出处：吴于廑、齐世荣《世界史·近代史编》"}]},{"type":"list","title":"延伸阅读","items":["明治维新的措施：政治上废藩置县，加强中央集权；经济上殖产兴业，发展近代工业；军事上实行征兵制，建立新式军队；社会生活上提倡文明开化。 出处：2024 部编版九下第 4 课","改革的局限：改革保留天皇制和大量封建残余，武士道精神被利用，日本很快走上军国主义对外扩张道路。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 4 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 中外改革与制度创新对照","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-04"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】自 1863 年 1 月 1 日起，凡在当地人民尚在反抗合众国的任何一州之内，为人占有而做奴隶的人们，都应在那时及以后永远获得自由；合众国政府行政部门，包括陆海军当局，将承认并保障这些人的自由。——《解放黑人奴隶宣言》（1862 年颁布，1863 年 1 月 1 日起生效）\n【材料二】1861 年，沙皇亚历山大二世签署废除农奴制的法令：农奴获得人身自由，地主不得买卖农奴；农奴可以赎买的方式获得一块份地，但必须向地主缴纳大量赎金。\n【材料三】1868 年起，明治政府废除藩国、设置府县，加强中央集权；允许土地买卖，引进西方技术，鼓励发展近代工业；实行征兵制，建立新式军队；提倡「文明开化」，向欧美学习，努力发展教育。","source":"材料研读 · 殖民地人民的反抗与资本主义制度的扩展"}],"questions":[{"id":"h9b-u1-q5","type":"choice","stem":"日本明治维新措施中，属于政治方面、旨在加强中央集权的是","answer":"A","explain":"废藩置县废除了藩国、设置府县，由中央任命官员，加强了中央集权。殖产兴业属经济措施，征兵制属军事措施，文明开化属文化教育措施。","options":["废藩置县","殖产兴业，发展近代工业","实行征兵制，建立新式军队","提倡「文明开化」，发展教育"],"tags":["明治维新","制度创新"]},{"id":"cat-9b-1-4-g2","type":"choice","stem":"下列关于「日本明治维新」的表述，错误的是","answer":"A","explain":"把明治维新的「废藩置县」与「殖产兴业」混为一谈——材料题要求「按政治、经济、军事、文化分类概括措施」，混在一起就丢分。正确表述：废藩置县是政治措施（废除藩国、设置府县，加强中央集权）；殖产兴业是经济措施（引进西方技术、发展近代工业）。","options":["把明治维新的「废藩置县」与「殖产兴业」混为一谈。","废藩置县是政治措施（废除藩国、设置府县，加强中央集权）；殖产兴业是经济措施（引进西方技术、发展近代工业）。","19 世纪中期，资本主义制度在世界范围内确立和扩展：俄国靠自上而下的改革，美国靠内战，日本靠明治维新——方式不同，方向一致。","改革是社会进步的重要方式：俄国 1861 年改革与日本明治维新都使国家走上发展资本主义的道路，但都保留了大量封建残余，日本还由此走上对外扩张的道路。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：政治上废藩置县，加强中央集权；经济上殖产兴业，发展近代工业；军事上实行征兵制，建立新式军队；社会生活上提倡文明开化。（2024 部编版九下第 4 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"日本明治维新；日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近代工业）、实行征兵制（建立新式军队）、提倡「文明开化」（发展教育）。使日本走上发展资本主义的道路，成为亚洲强国，但保留大量封建残余并走向对外扩张。","explain":"材料出自2024 部编版九下第 4 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第一单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-1-4-g5","type":"choice","stem":"「日本明治维新开始」发生于","answer":"A","explain":"本课时间轴：日本明治维新开始（1868 年）。推翻幕府统治后，明治政府推行废藩置县、殖产兴业、征兵制、文明开化等改革，日本走上发展资本主义的道路。其余三个时间是同一单元相邻课时的事件时间。","options":["1868 年","19 世纪初","1857—1859 年","1861 年"],"difficulty":1,"tags":["九年级下册","第一单元","本课练习"]},{"id":"cat-9b-1-4-g6","type":"choice","stem":"下列考点中，属于「日本明治维新」的是","answer":"A","explain":"本课考点（重点）：日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近代工业）、实行征兵制（建立新式军队）、提倡「文明开化」（发展教育）。使日本走上发展资本主义的道路，成为亚洲强国，但保留大量封建残余并走向对外扩张。其余三项是同一单元相邻课时的考点。","options":["日本明治维新（1868 年起）：废藩置县（加强中央集权）、殖产兴业（引进西方技术、发展近…","拉丁美洲独立运动（19 世纪初）：玻利瓦尔、圣马丁领导，反抗西班牙、葡萄牙殖民统治，18…","印度民族大起义（1857—1859）：反抗英国殖民统治，章西女王是杰出代表；起义失败，但…","玻利瓦尔、圣马丁、章西女王、亚历山大二世、林肯、明治天皇等历史人物及其主要贡献。"],"difficulty":2,"tags":["九年级下册","第一单元","本课练习"]}]},{"id":"cat-9b-2-1","title":"第5课 第二次工业革命","subtitle":"九年级下册 · 第二单元 第二次工业革命和近代科学文化","grade":"9b","tags":["九年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第二单元 第二次工业革命和近代科学文化"},{"k":"课时","v":"第5课 第二次工业革命"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪六七十年代，第二次工业革命兴起，电力成为新能源，内燃机、化学工业、钢铁工业迅速发展。爱迪生发明耐用白炽灯泡，卡尔·本茨制造内燃机汽车，莱特兄弟试飞飞机。人类进入「电气时代」。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪 70 年代起，第二次工业革命以电力的广泛应用为标志，科学与技术紧密结合，使人类进入「电气时代」，生产力飞速发展；生产与资本的高度集中产生垄断组织，主要资本主义国家进入帝国主义阶段，世界市场最终形成，列强争夺霸权最终引发第一次世界大战——同期牛顿、达尔文与巴尔扎克、贝多芬、托尔斯泰等人则在科学与文化上完成了近代思想的奠基。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["19 世纪 70 年代","第二次工业革命开始","以电力的广泛应用为标志，电动机、发电机相继问世，人类进入「电气时代」 · 重点"],["1879 年","爱迪生发明耐用碳丝白炽灯泡","此后电灯、电话、电车等相继问世，电力进入生产与生活领域；爱迪生被誉为「发明大王」 · 重点"],["1885 年","本茨制造出内燃机驱动的汽车","内燃机的创制推动了石油开采与化学工业的发展，交通运输发生革命性变化"],["1903 年","莱特兄弟制成的飞机试飞成功","人类交通运输工具的又一次重大突破"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"19 世纪 70 年代","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"第二次工业革命开始","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1879 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"爱迪生发明耐用碳丝白炽灯泡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1885 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"本茨制造出内燃机驱动的汽车","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1903 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"莱特兄弟制成的飞机试飞成功","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第二次工业革命的成就与标志：19 世纪 70 年代开始，以电力的广泛应用为标志，还包括内燃机与新交通工具（汽车、飞机）、化学工业和新材料、新通讯手段的发明，人类进入「电气时代」。","explain":"要能把成就按「能源（电力、石油）— 交通（汽车、飞机）— 通讯 — 化工」分类，并答出对生产力的巨大推动。"},{"level":"重点","text":"第二次工业革命的影响：生产力飞速发展，资本主义世界市场最终形成；生产与资本的高度集中产生垄断组织，主要资本主义国家进入帝国主义阶段；帝国主义国家政治经济发展不平衡加剧，列强争夺殖民地和世界霸权，最终导致第一次世界大战。","explain":"这是「第二次工业革命 → 一战」的因果链，中考常把两个单元连起来考，答题时要把这条因果链写完整。"},{"level":"次重点","text":"第二次工业革命的特点：科学研究与工业生产紧密结合（科学与技术紧密结合）；几个主要资本主义国家几乎同时进行；日本、德国等国两次工业革命交叉进行。","explain":""},{"level":"次重点","text":"爱迪生（发明大王）、本茨（内燃机汽车）、莱特兄弟（飞机）、诺贝尔（现代炸药）等发明家的贡献。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","帝国主义国家政治经济发展不平衡是第一次世界大战的根本原因——这是「第二次工业革命」与「一战」之间最重要的一条因果链。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。"],["认为垄断组织的出现只有消极影响。","垄断组织是第二次工业革命推动下生产与资本高度集中的结果，在一定程度上促进了生产的发展；同时也使主要资本主义国家进入帝国主义阶段，加剧了对外扩张与争夺。","「只有消极影响」「完全没有积极作用」这类绝对化表述通常是错的。"]]},{"type":"table","title":"第一次工业革命与第二次工业革命（跨册对比（九上第二单元与九下第二单元））","head":["比较项","第一次工业革命（18 世纪 60 年代起）","第二次工业革命（19 世纪 70 年代起）"],"rows":[["标志性技术","蒸汽机的改良和广泛使用","电力的广泛应用"],["主要能源","煤炭","电力、石油"],["时代特征","「蒸汽时代」","「电气时代」"],["科学与技术的关系","主要靠工匠的实践经验与发明","科学研究与工业生产紧密结合"],["生产组织","工厂制度确立","出现垄断组织，进入帝国主义阶段"],["对世界的影响","世界市场初步形成，列强加紧殖民扩张","世界市场最终形成，列强掀起瓜分世界的狂潮"]]},{"type":"table","title":"第二次工业革命时期的西方与中国（中国史联动）（中外对比：同一时期中国为什么「落伍」了）","head":["比较项","西方主要资本主义国家","中国（洋务运动，19 世纪 60—90 年代）"],"rows":[["核心技术","电力、内燃机、化学工业，科学与技术紧密结合","引进西方机器设备，创办军事工业与民用工业，未掌握核心技术"],["制度基础","资产阶级统治确立或扩展，为经济发展提供制度保障","仍是封建专制统治，未改变社会制度"],["教育与人才","重视科技研究与教育普及，人才辈出","创办新式学堂、派遣留学生，但科举制度仍束缚人才"],["结果","生产力飞跃，进入帝国主义阶段，加紧瓜分世界","甲午战败，洋务运动破产，民族危机空前严重"],["启示","科技创新与制度变革必须并举，单纯引进技术不能救国","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次工业革命的比较","给出标志性发明或能源材料，要求判断属于哪次工业革命并说明理由，进而比较两次革命在能源、时代名称、科学与技术关系上的不同，答案可直接对照本单元对比表。"],["科技与思想解放的关联","以牛顿、达尔文为切口，要求说明科学成就如何冲击神学观念、推动思想解放，常与文艺复兴、启蒙运动组合成大题。"],["从科技革命看近代中国的落后","以「第二次工业革命时期的中国」设问，要求结合洋务运动说明中国落后的原因与启示，落点是「科技创新与制度变革并举」，属高频中外对比考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：电力、内燃机与第二次工业革命；地理：工业化与城市化。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["电气时代","第二次工业革命以电力广泛应用为标志，人类进入电气时代。","2024 部编版九下第 5 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"爱迪生","v":"美国发明家，发明耐用白炽灯泡等。 出处：吴于廑、齐世荣《世界史·近代史编》"},{"k":"卡尔·本茨","v":"德国工程师，制造第一辆内燃机汽车。 出处：2024 部编版九下第 5 课"}]},{"type":"list","title":"延伸阅读","items":["电力的应用：1866 年西门子发明发电机，1879 年爱迪生发明耐用白炽灯泡，电力广泛用于照明、动力和通讯。 出处：吴于廑、齐世荣《世界史·近代史编》","汽车与飞机：1885 年卡尔·本茨制造出第一辆内燃机汽车；1903 年莱特兄弟试飞飞机成功。 出处：2024 部编版九下第 5 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 5 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】19 世纪 70 年代起，发电机、电动机、电灯、电话、电车等相继问世，电力作为新能源进入生产领域，人类进入「电气时代」。到 19 世纪末，美国的工业产量跃居世界第一位。\n【材料二】（19 世纪末）少数大企业通过兼并、联合，控制了某一个或几个部门的生产和销售，形成垄断组织。它们不仅控制国家的经济命脉，还干预国家的政治生活。\n【材料三】1870 年以后，科学技术的发展突飞猛进，各种新技术、新发明层出不穷，它们被迅速应用于生产，大大促进了经济的发展。","source":"材料研读 · 第二次工业革命和近代科学文化"}],"questions":[{"id":"h9b-u2-m1-q1","type":"short","stem":"（1）依据材料一，指出第二次工业革命中出现的两种新能源，并说明电力广泛应用使人类进入了什么时代？（4 分）","answer":"新能源：电力；石油（随内燃机的创制而得到广泛开采和使用）。电力广泛应用于生产与生活领域，人类由此进入「电气时代」。","explain":"","tags":["第二次工业革命","史料实证"],"rubric":["答出电力","答出石油（或内燃机）","答出「电气时代」","表述完整、指向第二次工业革命"]},{"id":"h9b-u2-q1","type":"choice","stem":"第二次工业革命中，作为新能源被广泛应用、使人类进入「电气时代」的是","answer":"B","explain":"第二次工业革命以电力的广泛应用为标志，电动机、发电机等的发明使电力进入生产与生活领域，人类进入「电气时代」。煤炭是第一次工业革命的主要能源。","options":["煤炭","电力","水力","风能"],"tags":["第二次工业革命","时空观念"]},{"id":"h9b-u2-q2","type":"choice","stem":"1879 年研制出耐用碳丝白炽灯泡、一生取得千余项发明专利，被誉为「发明大王」的是","answer":"B","explain":"爱迪生 1879 年发明耐用的白炽灯泡，被誉为「发明大王」。本茨制造出内燃机汽车，莱特兄弟制成飞机，诺贝尔发明现代炸药。","options":["本茨","爱迪生","莱特兄弟","诺贝尔"],"tags":["第二次工业革命","历史人物"]},{"id":"h9b-u2-q4","type":"choice","stem":"19 世纪末 20 世纪初，主要资本主义国家出现垄断组织。其根本原因是","answer":"B","explain":"垄断组织是第二次工业革命中生产力迅速发展、生产和资本高度集中的结果。国家全面干预经济是二战后（罗斯福新政开创）的新变化，不是垄断组织产生的原因。","options":["第一次工业革命的完成","第二次工业革命推动生产力发展、生产和资本日益高度集中","列强加紧对外殖民扩张","国家全面干预经济生活"],"tags":["垄断组织","唯物史观"]},{"id":"h9b-u2-q6","type":"choice","stem":"与第一次工业革命相比，第二次工业革命最突出的特点是","answer":"B","explain":"第二次工业革命中科学与技术紧密结合，各种新发明迅速应用于生产，这是它最突出的特点。A、C、D 都是第一次工业革命的特点，其中 D 是第一次工业革命的标志。","options":["主要靠工匠的实践经验与发明创造","科学研究与工业生产紧密结合，科学技术迅速应用于生产","首先发生在英国，然后扩展到其他国家","以蒸汽机的广泛使用为标志"],"tags":["第二次工业革命","横向比较"]},{"id":"cat-9b-2-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 第二次工业革命开始\n② 爱迪生发明耐用碳丝白炽灯泡\n③ 本茨制造出内燃机驱动的汽车\n④ 莱特兄弟制成的飞机试飞成功","answer":"A","explain":"按时间顺序应为：①第二次工业革命开始（19 世纪 70 年代）→②爱迪生发明耐用碳丝白炽灯泡（1879 年）→③本茨制造出内燃机驱动的汽车（1885 年）→④莱特兄弟制成的飞机试飞成功（1903 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-1-g2","type":"choice","stem":"下列关于「第二次工业革命」的表述，错误的是","answer":"A","explain":"把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志——两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。正确表述：第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","options":["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","帝国主义国家政治经济发展不平衡是第一次世界大战的根本原因——这是「第二次工业革命」与「一战」之间最重要的一条因果链。"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1866 年西门子发明发电机，1879 年爱迪生发明耐用白炽灯泡，电力广泛用于照明、动力和通讯。（吴于廑、齐世荣《世界史·近代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第二次工业革命；第二次工业革命的成就与标志：19 世纪 70 年代开始，以电力的广泛应用为标志，还包括内燃机与新交通工具（汽车、飞机）、化学工业和新材料、新通讯手段的发明，人类进入「电气时代」。","explain":"材料出自吴于廑、齐世荣《世界史·近代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-2-2","title":"第6课 工业化国家的社会变化","subtitle":"九年级下册 · 第二单元 第二次工业革命和近代科学文化","grade":"9b","tags":["九年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第二单元 第二次工业革命和近代科学文化"},{"k":"课时","v":"第6课 工业化国家的社会变化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"第二次工业革命推动工业化国家社会结构变化：人口增长、城市化加速、教育普及。同时也带来环境污染、贫富分化、社会问题等，各国开始通过立法和社会改革应对。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪 70 年代起，第二次工业革命以电力的广泛应用为标志，科学与技术紧密结合，使人类进入「电气时代」，生产力飞速发展；生产与资本的高度集中产生垄断组织，主要资本主义国家进入帝国主义阶段，世界市场最终形成，列强争夺霸权最终引发第一次世界大战——同期牛顿、达尔文与巴尔扎克、贝多芬、托尔斯泰等人则在科学与文化上完成了近代思想的奠基。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1687 年","牛顿发表《自然哲学的数学原理》","提出万有引力定律等，建立起经典力学体系，为近代自然科学奠定基础"],["1859 年","达尔文出版《物种起源》","提出生物进化论（「物竞天择，适者生存」），打破了神学创世说，在生物学领域完成一次伟大革命 · 重点"],["1869 年","俄国化学家门捷列夫发现元素周期律","编制出元素周期表，使化学研究变得有规律可循"],["19 世纪 70 年代","第二次工业革命开始","以电力的广泛应用为标志，电动机、发电机相继问世，人类进入「电气时代」 · 重点"],["1879 年","爱迪生发明耐用碳丝白炽灯泡","此后电灯、电话、电车等相继问世，电力进入生产与生活领域；爱迪生被誉为「发明大王」 · 重点"],["1885 年","本茨制造出内燃机驱动的汽车","内燃机的创制推动了石油开采与化学工业的发展，交通运输发生革命性变化"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1687 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"牛顿发表《自然哲学的数学原理》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1859 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"达尔文出版《物种起源》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1869 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"俄国化学家门捷列夫发现元素周期律","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"19 世纪 70 年代","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"第二次工业革命开始","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"1879 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"爱迪生发明耐用碳丝白炽灯泡","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1885 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"本茨制造出内燃机驱动的汽车","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题（本课单独考点较少，以下取本单元整体内容）","items":[{"level":"重点","text":"第二次工业革命的成就与标志：19 世纪 70 年代开始，以电力的广泛应用为标志，还包括内燃机与新交通工具（汽车、飞机）、化学工业和新材料、新通讯手段的发明，人类进入「电气时代」。","explain":"要能把成就按「能源（电力、石油）— 交通（汽车、飞机）— 通讯 — 化工」分类，并答出对生产力的巨大推动。"},{"level":"重点","text":"第二次工业革命的影响：生产力飞速发展，资本主义世界市场最终形成；生产与资本的高度集中产生垄断组织，主要资本主义国家进入帝国主义阶段；帝国主义国家政治经济发展不平衡加剧，列强争夺殖民地和世界霸权，最终导致第一次世界大战。","explain":"这是「第二次工业革命 → 一战」的因果链，中考常把两个单元连起来考，答题时要把这条因果链写完整。"},{"level":"重点","text":"牛顿与达尔文：牛顿建立经典力学体系（万有引力定律等），达尔文提出生物进化论（1859 年《物种起源》），二者都冲击了神学观念，推动了近代科学和思想解放。","explain":"常考「科学成就与思想解放的关系」：科学进步使人们摆脱神学束缚，为启蒙思想、社会进步提供基础。"},{"level":"重点","text":"近代文学艺术：巴尔扎克《人间喜剧》（法国社会的「百科全书」）、贝多芬《英雄交响曲》、列夫·托尔斯泰《战争与和平》《安娜·卡列尼娜》《复活》（被列宁称为「俄国革命的镜子」）、梵高《向日葵》。","explain":"人物—国别—代表作是必考配对；材料常引作品片段，要求判断作者与作品所反映的时代。"},{"level":"次重点","text":"第二次工业革命的特点：科学研究与工业生产紧密结合（科学与技术紧密结合）；几个主要资本主义国家几乎同时进行；日本、德国等国两次工业革命交叉进行。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","垄断是生产力发展的结果：生产与资本高度集中 → 垄断组织 → 主要资本主义国家进入帝国主义阶段，列强加紧瓜分世界。","科学进步与思想解放相互促进：牛顿力学与达尔文进化论冲击了神学观念，推动了近代思想解放和社会进步。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。"],["把牛顿与达尔文的成就对调。","牛顿建立经典力学体系、提出万有引力定律；达尔文提出生物进化论、出版《物种起源》。","人物与成就的配对题几乎必考，还要注意二者都是「冲击神学」的近代科学家。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次工业革命的比较","给出标志性发明或能源材料，要求判断属于哪次工业革命并说明理由，进而比较两次革命在能源、时代名称、科学与技术关系上的不同，答案可直接对照本单元对比表。"],["科技与思想解放的关联","以牛顿、达尔文为切口，要求说明科学成就如何冲击神学观念、推动思想解放，常与文艺复兴、启蒙运动组合成大题。"],["从科技革命看近代中国的落后","以「第二次工业革命时期的中国」设问，要求结合洋务运动说明中国落后的原因与启示，落点是「科技创新与制度变革并举」，属高频中外对比考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：电力、内燃机与第二次工业革命；地理：工业化与城市化。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["城市化：大量农村人口涌入城市，城市规模迅速扩大，但住房拥挤、卫生条件差等问题突出。 出处：2024 部编版九下第 6 课","社会立法：19 世纪末 20 世纪初，一些国家颁布工厂法、限制工时、改善劳动条件，社会保障制度逐步建立。 出处：吴于廑、齐世荣《世界史·近代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 6 课；吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u2-q1","type":"choice","stem":"第二次工业革命中，作为新能源被广泛应用、使人类进入「电气时代」的是","answer":"B","explain":"第二次工业革命以电力的广泛应用为标志，电动机、发电机等的发明使电力进入生产与生活领域，人类进入「电气时代」。煤炭是第一次工业革命的主要能源。","options":["煤炭","电力","水力","风能"],"tags":["第二次工业革命","时空观念"]},{"id":"h9b-u2-q2","type":"choice","stem":"1879 年研制出耐用碳丝白炽灯泡、一生取得千余项发明专利，被誉为「发明大王」的是","answer":"B","explain":"爱迪生 1879 年发明耐用的白炽灯泡，被誉为「发明大王」。本茨制造出内燃机汽车，莱特兄弟制成飞机，诺贝尔发明现代炸药。","options":["本茨","爱迪生","莱特兄弟","诺贝尔"],"tags":["第二次工业革命","历史人物"]},{"id":"h9b-u2-q3","type":"choice","stem":"1859 年出版《物种起源》、提出生物进化论、打破神学创世说的科学家是","answer":"B","explain":"1859 年英国科学家达尔文出版《物种起源》，提出生物进化论，打破了神学创世说。牛顿建立经典力学体系，门捷列夫发现元素周期律。","options":["牛顿","达尔文","门捷列夫","爱因斯坦"],"tags":["近代科学","历史解释"]},{"id":"cat-9b-2-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 牛顿发表《自然哲学的数学原理》\n② 达尔文出版《物种起源》\n③ 俄国化学家门捷列夫发现元素周期律\n④ 第二次工业革命开始","answer":"A","explain":"按时间顺序应为：①牛顿发表《自然哲学的数学原理》（1687 年）→②达尔文出版《物种起源》（1859 年）→③俄国化学家门捷列夫发现元素周期律（1869 年）→④第二次工业革命开始（19 世纪 70 年代）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-2-g2","type":"choice","stem":"下列关于「工业化国家的社会变化」的表述，错误的是","answer":"A","explain":"把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志——两次革命的标志、能源、时代名称是最常设的对应类陷阱，要成对记：「一蒸二电」。正确表述：第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","options":["把两次工业革命的标志性成果弄反：认为第二次工业革命以蒸汽机的广泛使用为标志。","第一次工业革命以蒸汽机的广泛使用为标志，人类进入「蒸汽时代」；第二次工业革命以电力的广泛应用为标志，人类进入「电气时代」。","科学技术是第一生产力：第二次工业革命中科学与技术紧密结合，电力等新能源的应用使生产力获得飞跃式发展。","垄断是生产力发展的结果：生产与资本高度集中 → 垄断组织 → 主要资本主义国家进入帝国主义阶段，列强加紧瓜分世界。"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：大量农村人口涌入城市，城市规模迅速扩大，但住房拥挤、卫生条件差等问题突出。（2024 部编版九下第 6 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"工业化国家的社会变化；第二次工业革命的成就与标志：19 世纪 70 年代开始，以电力的广泛应用为标志，还包括内燃机与新交通工具（汽车、飞机）、化学工业和新材料、新通讯手段的发明，人类进入「电气时代」。","explain":"材料出自2024 部编版九下第 6 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-2-3","title":"第7课 近代科学与文化","subtitle":"九年级下册 · 第二单元 第二次工业革命和近代科学文化","grade":"9b","tags":["九年级下册","第二单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第二单元 第二次工业革命和近代科学文化"},{"k":"课时","v":"第7课 近代科学与文化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"近代科学与文化取得重大突破。1687 年牛顿发表《自然哲学的数学原理》，建立经典力学体系；1859 年达尔文发表《物种起源》，提出进化论；贝多芬、托尔斯泰、梵高等创作出不朽作品。"},{"type":"note","title":"本课主线 · 因果链","text":"19 世纪 70 年代起，第二次工业革命以电力的广泛应用为标志，科学与技术紧密结合，使人类进入「电气时代」，生产力飞速发展；生产与资本的高度集中产生垄断组织，主要资本主义国家进入帝国主义阶段，世界市场最终形成，列强争夺霸权最终引发第一次世界大战——同期牛顿、达尔文与巴尔扎克、贝多芬、托尔斯泰等人则在科学与文化上完成了近代思想的奠基。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1687 年","牛顿发表《自然哲学的数学原理》","提出万有引力定律等，建立起经典力学体系，为近代自然科学奠定基础"],["1859 年","达尔文出版《物种起源》","提出生物进化论（「物竞天择，适者生存」），打破了神学创世说，在生物学领域完成一次伟大革命 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1687 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"牛顿发表《自然哲学的数学原理》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1859 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"达尔文出版《物种起源》","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"牛顿与达尔文：牛顿建立经典力学体系（万有引力定律等），达尔文提出生物进化论（1859 年《物种起源》），二者都冲击了神学观念，推动了近代科学和思想解放。","explain":"常考「科学成就与思想解放的关系」：科学进步使人们摆脱神学束缚，为启蒙思想、社会进步提供基础。"},{"level":"重点","text":"近代文学艺术：巴尔扎克《人间喜剧》（法国社会的「百科全书」）、贝多芬《英雄交响曲》、列夫·托尔斯泰《战争与和平》《安娜·卡列尼娜》《复活》（被列宁称为「俄国革命的镜子」）、梵高《向日葵》。","explain":"人物—国别—代表作是必考配对；材料常引作品片段，要求判断作者与作品所反映的时代。"},{"level":"选择题","text":"牛顿、达尔文、巴尔扎克、贝多芬、列夫·托尔斯泰、梵高的国别、身份与代表作。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["科学进步与思想解放相互促进：牛顿力学与达尔文进化论冲击了神学观念，推动了近代思想解放和社会进步。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把牛顿与达尔文的成就对调。","牛顿建立经典力学体系、提出万有引力定律；达尔文提出生物进化论、出版《物种起源》。","人物与成就的配对题几乎必考，还要注意二者都是「冲击神学」的近代科学家。"],["把列夫·托尔斯泰、巴尔扎克、梵高的国别混淆。","托尔斯泰是俄国作家，巴尔扎克是法国作家，梵高是荷兰画家，贝多芬是德国音乐家。","文学艺术的国别与代表作属于「了解」层级，但选择题常用它送分或设陷阱。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次工业革命的比较","给出标志性发明或能源材料，要求判断属于哪次工业革命并说明理由，进而比较两次革命在能源、时代名称、科学与技术关系上的不同，答案可直接对照本单元对比表。"],["科技与思想解放的关联","以牛顿、达尔文为切口，要求说明科学成就如何冲击神学观念、推动思想解放，常与文艺复兴、启蒙运动组合成大题。"],["从科技革命看近代中国的落后","以「第二次工业革命时期的中国」设问，要求结合洋务运动说明中国落后的原因与启示，落点是「科技创新与制度变革并举」，属高频中外对比考法。"]]},{"type":"note","title":"跨学科视角","text":"科学：电力、内燃机与第二次工业革命；地理：工业化与城市化。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["物竞天择，适者生存","达尔文进化论核心思想的概括，后被严复引入中国。","《物种起源》；严复《天演论》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"牛顿","v":"英国物理学家，建立经典力学体系。 出处：《自然哲学的数学原理》"},{"k":"达尔文","v":"英国生物学家，提出进化论。 出处：《物种起源》"},{"k":"贝多芬","v":"德国作曲家，代表作《英雄交响曲》《命运交响曲》。 出处：2024 部编版九下第 7 课"},{"k":"托尔斯泰","v":"俄国作家，代表作《战争与和平》《安娜·卡列尼娜》。 出处：2024 部编版九下第 7 课"}]},{"type":"list","title":"延伸阅读","items":["牛顿的贡献：牛顿提出万有引力定律和三大运动定律，建立经典力学体系，还独立发明微积分、发现光的色散。 出处：《自然哲学的数学原理》","达尔文进化论：达尔文通过环球考察，提出以自然选择为核心的生物进化论，冲击了神创论。 出处：《物种起源》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 7 课；《自然哲学的数学原理》《物种起源》","吴于廑、齐世荣《世界史·近代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u2-q3","type":"choice","stem":"1859 年出版《物种起源》、提出生物进化论、打破神学创世说的科学家是","answer":"B","explain":"1859 年英国科学家达尔文出版《物种起源》，提出生物进化论，打破了神学创世说。牛顿建立经典力学体系，门捷列夫发现元素周期律。","options":["牛顿","达尔文","门捷列夫","爱因斯坦"],"tags":["近代科学","历史解释"]},{"id":"h9b-u2-q5","type":"choice","stem":"被列宁称为「俄国革命的镜子」的作家及其代表作是","answer":"B","explain":"俄国作家列夫·托尔斯泰著有《战争与和平》《安娜·卡列尼娜》《复活》，列宁称他为「俄国革命的镜子」；巴尔扎克是法国作家，其《人间喜剧》被称为法国社会的「百科全书」。","options":["巴尔扎克《人间喜剧》","列夫·托尔斯泰《战争与和平》","莎士比亚《哈姆雷特》","但丁《神曲》"],"tags":["近代文学","历史人物"]},{"id":"cat-9b-2-3-g2","type":"choice","stem":"下列关于「近代科学与文化」的表述，错误的是","answer":"A","explain":"把牛顿与达尔文的成就对调——人物与成就的配对题几乎必考，还要注意二者都是「冲击神学」的近代科学家。正确表述：牛顿建立经典力学体系、提出万有引力定律；达尔文提出生物进化论、出版《物种起源》。","options":["把牛顿与达尔文的成就对调。","牛顿建立经典力学体系、提出万有引力定律；达尔文提出生物进化论、出版《物种起源》。","科学进步与思想解放相互促进：牛顿力学与达尔文进化论冲击了神学观念，推动了近代思想解放和社会进步。","牛顿与达尔文：牛顿建立经典力学体系（万有引力定律等），达尔文提出生物进化论（1859 年《物种起源》），二者都冲击了神学观念，推动了近代科学和思想解放。"],"difficulty":2,"tags":["九年级下册","第二单元","本课练习"]},{"id":"cat-9b-2-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：牛顿提出万有引力定律和三大运动定律，建立经典力学体系，还独立发明微积分、发现光的色散。（《自然哲学的数学原理》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"近代科学与文化；牛顿与达尔文：牛顿建立经典力学体系（万有引力定律等），达尔文提出生物进化论（1859 年《物种起源》），二者都冲击了神学观念，推动了近代科学和思想解放。","explain":"材料出自《自然哲学的数学原理》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第二单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-2-3-g5","type":"choice","stem":"「牛顿发表《自然哲学的数学原理》」发生于","answer":"A","explain":"本课时间轴：牛顿发表《自然哲学的数学原理》（1687 年）。提出万有引力定律等，建立起经典力学体系，为近代自然科学奠定基础。其余三个时间是同一单元相邻课时的事件时间。","options":["1687 年","19 世纪 70 年代","1879 年","1885 年"],"difficulty":1,"tags":["九年级下册","第二单元","本课练习"]}]},{"id":"cat-9b-3-1","title":"第8课 第一次世界大战","subtitle":"九年级下册 · 第三单元 第一次世界大战和战后初期的世界","grade":"9b","tags":["九年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第三单元 第一次世界大战和战后初期的世界"},{"k":"课时","v":"第8课 第一次世界大战"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"19 世纪末，帝国主义国家矛盾激化，形成三国同盟和三国协约两大军事集团。1914 年 6 月 28 日萨拉热窝事件成为导火索，第一次世界大战爆发。1916 年凡尔登战役异常惨烈，被称为「凡尔登绞肉机」。1918 年 11 月德国投降，一战结束。"},{"type":"note","title":"本课主线 · 因果链","text":"帝国主义国家政治经济发展不平衡，两大军事集团对抗，1914 年一战爆发；四年大战削弱了帝国主义力量、促成俄国十月革命，战后列强通过巴黎和会与华盛顿会议建立起「凡尔赛—华盛顿体系」，暂时调整了世界秩序；苏俄以新经济政策恢复经济并成立苏联，亚非拉的民族民主运动（印度非暴力不合作、土耳其凯末尔革命）也在战后高涨。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1882 年","三国同盟形成","德国、奥匈帝国、意大利结盟，以德国为核心"],["1907 年","三国协约形成","英国、法国、俄国结盟，与三国同盟对峙，两大军事集团的形成使战争一触即发"],["1914 年 6 月","萨拉热窝事件","奥匈帝国皇储夫妇被塞尔维亚青年刺杀，成为第一次世界大战的导火线（直接原因） · 重点"],["1916 年","凡尔登战役","德法双方伤亡七十多万人，被称为「凡尔登绞肉机」，是一战中残酷性的典型例证"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1882 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"三国同盟形成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1907 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"三国协约形成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1914 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"萨拉热窝事件","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1916 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"凡尔登战役","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第一次世界大战爆发的原因、导火线与性质：根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权；两大军事集团（三国同盟与三国协约）的形成使战争一触即发；导火线是 1914 年萨拉热窝事件。性质是一场非正义的帝国主义掠夺战争（塞尔维亚为民族独立而战具有正义性）。","explain":"答题顺序固定：根本原因 → 具体条件（两大军事集团）→ 导火线 → 性质。切忌把萨拉热窝事件答成根本原因。"},{"level":"重点","text":"第一次世界大战的影响：给人类带来空前灾难（30 多个国家、15 亿人口卷入，伤亡 3000 多万人）；削弱了帝国主义和殖民主义力量；促进了殖民地半殖民地民族解放运动的发展；促成俄国十月革命；欧洲衰落、美日崛起，世界格局发生变化。","explain":"「大战 → 十月革命 → 民族解放运动高涨」是这一单元的三条支线，材料题常要求「从一战的影响看十月革命的条件」。"},{"level":"选择题","text":"一战中的重要战役（凡尔登战役、索姆河战役）与萨拉热窝事件的经过。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","弱国无外交：巴黎和会上中国外交失败说明国家实力决定国际地位，中国要争取国际地位必须实现民族独立、国家富强。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。"],["认为十月革命结束了一战。","十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","两个 1918 年的事件时间接近，容易混为一谈。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局的起点","以「凡尔赛—华盛顿体系」为切口考查战后格局如何形成、为何不能持久，常与第四单元「雅尔塔体系与两极格局」组合成「20 世纪世界格局的三次变动」大题。"],["大国关系与军事集团","给出三国同盟与三国协约的示意图或结盟材料，要求指出两大集团的核心国家、说明欧洲两大军事集团对峙与一战爆发的关系。"],["中国史联动：外交失败与民族觉醒","把巴黎和会、《九国公约》与五四运动、中国共产党的成立串成一线，落点在「弱国无外交」与「中国国际地位的今昔对比」。"],["社会主义运动的探索","十月革命（建立政权）与新经济政策（恢复经济）常作为一组材料，要求说明「社会主义道路需要不断探索、政策要符合国情」。"]]},{"type":"note","title":"跨学科视角","text":"地理：巴尔干与欧洲战场；道德与法治：战争与和平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["萨拉热窝事件","一战导火索，暴露了帝国主义矛盾的尖锐性。","吴于廑、齐世荣《世界史·现代史编》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"普林西普","v":"塞尔维亚青年，刺杀斐迪南大公，引发一战。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["萨拉热窝事件：1914 年 6 月 28 日，奥匈帝国皇储斐迪南大公夫妇在萨拉热窝被塞尔维亚青年普林西普刺杀，成为一战导火索。 出处：吴于廑、齐世荣《世界史·现代史编》","凡尔登战役：1916 年 2—12 月，德法两军在凡尔登要塞激战，双方伤亡约 70 万人，被称为「凡尔登绞肉机」。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 8 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u3-q1","type":"choice","stem":"第一次世界大战爆发的根本原因是","answer":"B","explain":"根本原因是帝国主义国家政治经济发展不平衡，后起的帝国主义国家要求重新瓜分世界，与老牌殖民国家矛盾激化。萨拉热窝事件是导火线，两大军事集团的形成是具体条件。","options":["萨拉热窝事件的发生","帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权","三国同盟与三国协约的形成","塞尔维亚与奥匈帝国的领土争端"],"tags":["第一次世界大战","唯物史观"]},{"id":"cat-9b-3-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 三国同盟形成\n② 三国协约形成\n③ 萨拉热窝事件\n④ 凡尔登战役","answer":"A","explain":"按时间顺序应为：①三国同盟形成（1882 年）→②三国协约形成（1907 年）→③萨拉热窝事件（1914 年 6 月）→④凡尔登战役（1916 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g2","type":"choice","stem":"下列关于「第一次世界大战」的表述，错误的是","answer":"A","explain":"把萨拉热窝事件说成第一次世界大战爆发的根本原因——「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。正确表述：萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","options":["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g3","type":"choice","stem":"下列结论中，属于「第一次世界大战」的是","answer":"A","explain":"本课结论：第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["第一次世界大战是一场非正义的帝国主义掠夺战争，给人类带来空前灾难；战争没有解决列强之间的矛盾，反而为新的战争埋下祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1914 年 6 月 28 日，奥匈帝国皇储斐迪南大公夫妇在萨拉热窝被塞尔维亚青年普林西普刺杀，成为一战导火索。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第一次世界大战；第一次世界大战爆发的原因、导火线与性质：根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权；两大军事集团（三国同盟与三国协约）的形成使战争一触即发；导火线是 1914 年萨拉热窝事件。性质是一场非正义的帝国主义掠夺战争（塞尔维亚为民族独立而战具有正义性）。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-3-2","title":"第9课 一战后的国际关系","subtitle":"九年级下册 · 第三单元 第一次世界大战和战后初期的世界","grade":"9b","tags":["九年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第三单元 第一次世界大战和战后初期的世界"},{"k":"课时","v":"第9课 一战后的国际关系"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1919 年巴黎和会签订《凡尔赛条约》，1921—1922 年华盛顿会议签订《九国公约》，形成「凡尔赛—华盛顿体系」。1920 年国际联盟成立，但被英法操纵，未能维护世界和平。"},{"type":"note","title":"本课主线 · 因果链","text":"帝国主义国家政治经济发展不平衡，两大军事集团对抗，1914 年一战爆发；四年大战削弱了帝国主义力量、促成俄国十月革命，战后列强通过巴黎和会与华盛顿会议建立起「凡尔赛—华盛顿体系」，暂时调整了世界秩序；苏俄以新经济政策恢复经济并成立苏联，亚非拉的民族民主运动（印度非暴力不合作、土耳其凯末尔革命）也在战后高涨。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1919 年 1—6 月","巴黎和会与《凡尔赛条约》","战胜国重新瓜分世界；把德国在中国山东的特权转让给日本，中国外交失败，引发五四运动 · 重点"],["1921—1922 年","华盛顿会议与《九国公约》","调整列强在亚太地区的关系；《九国公约》使中国回到被几个帝国主义国家共同支配的局面"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1919 年 1—6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"巴黎和会与《凡尔赛条约》","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1921—1922 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"华盛顿会议与《九国公约》","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"凡尔赛—华盛顿体系：巴黎和会签订《凡尔赛条约》，华盛顿会议签订《九国公约》，确立了战后帝国主义在欧洲、西亚、非洲和亚太地区的统治秩序；但它不可能消除帝国主义国家之间的矛盾，反而埋下新的战争祸根。","explain":"对中国的处理是必考细节：巴黎和会把德国在山东的特权转让给日本，引发五四运动；《九国公约》使中国回到几个帝国主义国家共同支配的局面。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约。","它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","评价条约要抓住「分赃」二字，并联系中国外交失败与五四运动。"]]},{"type":"table","title":"巴黎和会、华盛顿会议与中国（中国史联动）（两次国际会议对中国问题的处理及其影响）","head":["比较项","列强（英、法、美、日等）","中国"],"rows":[["巴黎和会（1919）","重新瓜分世界，把德国在中国山东的特权全部转让给日本","代表提出收回山东主权、取消「二十一条」等正当要求被拒绝，外交失败"],["华盛顿会议（1921—1922）","签订《九国公约》，以「门户开放」「机会均等」原则协调在亚太的关系","名义上尊重中国主权、独立与领土完整，实际上使中国回到被几个帝国主义国家共同支配的局面"],["中国的反应","力图以牺牲中国利益来协调列强关系","五四运动爆发，中国人民反帝爱国斗争高涨"],["共同点","都无视中国的正当要求，损害中国主权与利益","同左"],["启示","弱国无外交，国家实力决定国际地位","必须争取民族独立、实现国家富强"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局的起点","以「凡尔赛—华盛顿体系」为切口考查战后格局如何形成、为何不能持久，常与第四单元「雅尔塔体系与两极格局」组合成「20 世纪世界格局的三次变动」大题。"],["大国关系与军事集团","给出三国同盟与三国协约的示意图或结盟材料，要求指出两大集团的核心国家、说明欧洲两大军事集团对峙与一战爆发的关系。"],["中国史联动：外交失败与民族觉醒","把巴黎和会、《九国公约》与五四运动、中国共产党的成立串成一线，落点在「弱国无外交」与「中国国际地位的今昔对比」。"],["社会主义运动的探索","十月革命（建立政权）与新经济政策（恢复经济）常作为一组材料，要求说明「社会主义道路需要不断探索、政策要符合国情」。"]]},{"type":"note","title":"跨学科视角","text":"地理：巴尔干与欧洲战场；道德与法治：战争与和平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["《凡尔赛条约》：重划德国疆界，德国失去全部海外殖民地，限制军备，承担巨额赔款，德国国内普遍不满。 出处：《凡尔赛条约》原文","《九国公约》：1922 年签订，宣称尊重中国主权、独立和领土完整，实际确认了帝国主义在华「门户开放」「机会均等」原则。 出处：《九国公约》原文"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 9 课；《凡尔赛条约》《九国公约》原文","吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中国代表在巴黎和会上提出收回山东主权、取消「二十一条」等正当要求，但会议决定把德国在中国山东的特权全部转让给日本。消息传回国内，激起了中国人民的强烈愤慨。\n【材料二】1922 年，九国代表在华盛顿签署《九国公约》。公约宣称尊重中国的主权、独立与领土完整，遵守各国在中国的「门户开放」「机会均等」的原则。\n【材料三】十月革命一声炮响，给我们送来了马克思列宁主义。——毛泽东《论人民民主专政》","source":"材料研读 · 第一次世界大战和战后初期的世界"}],"questions":[{"id":"h9b-u3-q4","type":"choice","stem":"1922 年华盛顿会议上签署的《九国公约》，其实际作用是","answer":"B","explain":"《九国公约》名义上尊重中国的主权、独立与领土完整，实际上使中国回到被几个帝国主义国家共同支配的局面。确立欧洲统治秩序的是《凡尔赛条约》，列强矛盾也不可能因此消除。","options":["使中国收回了全部主权","使中国回到被几个帝国主义国家共同支配的局面","确立了欧洲的统治秩序","彻底消除了列强之间的矛盾"],"tags":["华盛顿会议","历史解释"]},{"id":"cat-9b-3-2-g2","type":"choice","stem":"下列关于「一战后的国际关系」的表述，错误的是","answer":"A","explain":"认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约——评价条约要抓住「分赃」二字，并联系中国外交失败与五四运动。正确表述：它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","options":["认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约。","它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","凡尔赛—华盛顿体系：巴黎和会签订《凡尔赛条约》，华盛顿会议签订《九国公约》，确立了战后帝国主义在欧洲、西亚、非洲和亚太地区的统治秩序；但它不可能消除帝国主义国家之间的矛盾，反而埋下新的战争祸根。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-2-g3","type":"choice","stem":"下列结论中，属于「一战后的国际关系」的是","answer":"A","explain":"本课结论：「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：重划德国疆界，德国失去全部海外殖民地，限制军备，承担巨额赔款，德国国内普遍不满。（《凡尔赛条约》原文）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"一战后的国际关系；凡尔赛—华盛顿体系：巴黎和会签订《凡尔赛条约》，华盛顿会议签订《九国公约》，确立了战后帝国主义在欧洲、西亚、非洲和亚太地区的统治秩序；但它不可能消除帝国主义国家之间的矛盾，反而埋下新的战争祸根。","explain":"材料出自《凡尔赛条约》原文。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-3-2-g5","type":"choice","stem":"「巴黎和会与《凡尔赛条约》」发生于","answer":"A","explain":"本课时间轴：巴黎和会与《凡尔赛条约》（1919 年 1—6 月）。战胜国重新瓜分世界；把德国在中国山东的特权转让给日本，中国外交失败，引发五四运动。其余三个时间是同一单元相邻课时的事件时间。","options":["1919 年 1—6 月","1882 年","1907 年","1914 年 6 月"],"difficulty":1,"tags":["九年级下册","第三单元","本课练习"]}]},{"id":"cat-9b-3-3","title":"第10课 列宁与十月革命","subtitle":"九年级下册 · 第三单元 第一次世界大战和战后初期的世界","grade":"9b","tags":["九年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第三单元 第一次世界大战和战后初期的世界"},{"k":"课时","v":"第10课 列宁与十月革命"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1917 年，俄国深陷一战，社会矛盾激化。3 月革命推翻沙皇专制，但资产阶级临时政府继续战争。11 月 7 日（俄历 10 月 25 日），列宁领导彼得格勒武装起义，推翻临时政府，建立世界上第一个无产阶级专政国家。"},{"type":"note","title":"本课主线 · 因果链","text":"帝国主义国家政治经济发展不平衡，两大军事集团对抗，1914 年一战爆发；四年大战削弱了帝国主义力量、促成俄国十月革命，战后列强通过巴黎和会与华盛顿会议建立起「凡尔赛—华盛顿体系」，暂时调整了世界秩序；苏俄以新经济政策恢复经济并成立苏联，亚非拉的民族民主运动（印度非暴力不合作、土耳其凯末尔革命）也在战后高涨。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1917 年 11 月","俄国十月革命","彼得格勒武装起义胜利，建立世界上第一个无产阶级专政的国家，人类历史上第一次胜利的社会主义革命 · 重点"],["1922 年 12 月","苏联成立","苏维埃社会主义共和国联盟成立，最初有 4 个加盟共和国"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1917 年 11 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"俄国十月革命","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1922 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"苏联成立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第一次世界大战的影响：给人类带来空前灾难（30 多个国家、15 亿人口卷入，伤亡 3000 多万人）；削弱了帝国主义和殖民主义力量；促进了殖民地半殖民地民族解放运动的发展；促成俄国十月革命；欧洲衰落、美日崛起，世界格局发生变化。","explain":"「大战 → 十月革命 → 民族解放运动高涨」是这一单元的三条支线，材料题常要求「从一战的影响看十月革命的条件」。"},{"level":"重点","text":"十月革命的历史意义：人类历史上第一次胜利的社会主义革命，建立了世界上第一个无产阶级专政的国家；沉重打击了帝国主义的统治，推动了国际社会主义运动的发展；鼓舞了殖民地半殖民地人民的解放斗争；给中国送来了马克思列宁主义，推动五四运动发展与中国共产党的成立。","explain":"答题要写全「一国、两推动（社会主义运动、民族解放运动）、对中国的影响」三层。"},{"level":"次重点","text":"苏联的建立：1922 年 12 月，苏维埃社会主义共和国联盟成立。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为十月革命结束了一战。","十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","两个 1918 年的事件时间接近，容易混为一谈。"]]},{"type":"table","title":"俄国十月革命道路与中国革命道路（中国史联动）（中外对比：两国革命道路的选择与国情）","head":["比较项","俄国十月革命（1917）","中国革命道路（1927 年后）"],"rows":[["基本国情","资本主义有一定发展，工人阶级相对集中","半殖民地半封建社会，农民占人口绝大多数，城市中敌人力量强大"],["革命道路","在中心城市发动武装起义，然后向全国扩展","农村包围城市、武装夺取政权"],["主要依靠力量","城市工人阶级与士兵","农民阶级，建立农村革命根据地"],["结果","建立世界上第一个无产阶级专政的国家","找到适合中国国情的革命道路，最终取得新民主主义革命胜利"],["共同启示","革命和建设道路必须从本国国情出发，不能照搬别国经验","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局的起点","以「凡尔赛—华盛顿体系」为切口考查战后格局如何形成、为何不能持久，常与第四单元「雅尔塔体系与两极格局」组合成「20 世纪世界格局的三次变动」大题。"],["大国关系与军事集团","给出三国同盟与三国协约的示意图或结盟材料，要求指出两大集团的核心国家、说明欧洲两大军事集团对峙与一战爆发的关系。"],["中国史联动：外交失败与民族觉醒","把巴黎和会、《九国公约》与五四运动、中国共产党的成立串成一线，落点在「弱国无外交」与「中国国际地位的今昔对比」。"],["社会主义运动的探索","十月革命（建立政权）与新经济政策（恢复经济）常作为一组材料，要求说明「社会主义道路需要不断探索、政策要符合国情」。"]]},{"type":"note","title":"跨学科视角","text":"地理：巴尔干与欧洲战场；道德与法治：战争与和平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["阿芙乐尔号","十月革命中发出进攻冬宫信号巡洋舰，成为革命象征。","吴于廑、齐世荣《世界史·现代史编》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"列宁","v":"俄国无产阶级革命领袖，领导十月革命。 出处：列宁《四月提纲》"}]},{"type":"list","title":"延伸阅读","items":["十月革命的过程：1917 年 11 月 6 日夜，起义者占领彼得格勒主要据点；7 日攻占冬宫，逮捕临时政府成员，当晚召开全俄苏维埃第二次代表大会。 出处：吴于廑、齐世荣《世界史·现代史编》","历史意义：十月革命建立了世界上第一个社会主义国家，开辟了人类历史新纪元，推动了国际社会主义运动的发展。 出处：2024 部编版九下第 10 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 10 课；列宁《四月提纲》","吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】中国代表在巴黎和会上提出收回山东主权、取消「二十一条」等正当要求，但会议决定把德国在中国山东的特权全部转让给日本。消息传回国内，激起了中国人民的强烈愤慨。\n【材料二】1922 年，九国代表在华盛顿签署《九国公约》。公约宣称尊重中国的主权、独立与领土完整，遵守各国在中国的「门户开放」「机会均等」的原则。\n【材料三】十月革命一声炮响，给我们送来了马克思列宁主义。——毛泽东《论人民民主专政》","source":"材料研读 · 第一次世界大战和战后初期的世界"}],"questions":[{"id":"h9b-u3-m1-q2","type":"short","stem":"（2）依据材料二、三并结合所学，说明《九国公约》签订后中国依然面临的处境，以及十月革命对中国产生的影响。（6 分）","answer":"处境：《九国公约》虽宣称尊重中国的主权、独立与领土完整，实际上使中国回到被几个帝国主义国家共同支配的局面，中国依然处于半殖民地半封建社会的深渊，遭受列强侵略与压迫。影响：十月革命是人类历史上第一次胜利的社会主义革命，它沉重打击了帝国主义的统治，鼓舞了殖民地半殖民地人民的解放斗争；它给中国送来了马克思列宁主义，促进了中国人民的觉醒，推动了五四运动的发展和中国共产党的成立，为中国革命指明了新的方向。","explain":"","tags":["华盛顿会议","十月革命","中外关联"],"rubric":["指出《九国公约》使中国回到几个帝国主义国家共同支配的局面","指出中国仍处于半殖民地半封建社会","答出十月革命传播马克思列宁主义（给中国送来马列主义）","答出推动五四运动或中国共产党的成立","答出鼓舞殖民地半殖民地人民的解放斗争"]},{"id":"h9b-u3-q6","type":"choice","stem":"人类历史上第一次胜利的社会主义革命是","answer":"C","explain":"1917 年俄国十月革命建立了世界上第一个无产阶级专政的国家，是人类历史上第一次胜利的社会主义革命，开辟了人类历史的新纪元。","options":["英国资产阶级革命","法国大革命","俄国十月革命","美国独立战争"],"tags":["十月革命","历史解释"]},{"id":"cat-9b-3-3-g2","type":"choice","stem":"下列关于「列宁与十月革命」的表述，错误的是","answer":"A","explain":"认为十月革命结束了一战——两个 1918 年的事件时间接近，容易混为一谈。正确表述：十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","options":["认为十月革命结束了一战。","十月革命后苏俄退出一战（1918 年 3 月签订和约），但一战直到 1918 年 11 月德国投降才结束。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","第一次世界大战的影响：给人类带来空前灾难（30 多个国家、15 亿人口卷入，伤亡 3000 多万人）；削弱了帝国主义和殖民主义力量；促进了殖民地半殖民地民族解放运动的发展；促成俄国十月革命；欧洲衰落、美日崛起，世界格局发生变化。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-3-g3","type":"choice","stem":"下列结论中，属于「列宁与十月革命」的是","answer":"A","explain":"本课结论：十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1917 年 11 月 6 日夜，起义者占领彼得格勒主要据点；7 日攻占冬宫，逮捕临时政府成员，当晚召开全俄苏维埃第二次代表大会。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"列宁与十月革命；第一次世界大战的影响：给人类带来空前灾难（30 多个国家、15 亿人口卷入，伤亡 3000 多万人）；削弱了帝国主义和殖民主义力量；促进了殖民地半殖民地民族解放运动的发展；促成俄国十月革命；欧洲衰落、美日崛起，世界格局发生变化。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-3-4","title":"第11课 苏联的社会主义建设","subtitle":"九年级下册 · 第三单元 第一次世界大战和战后初期的世界","grade":"9b","tags":["九年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第三单元 第一次世界大战和战后初期的世界"},{"k":"课时","v":"第11课 苏联的社会主义建设"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1921 年，苏俄实行新经济政策，允许多种经济成分并存，恢复商品货币关系。1928 年起，苏联实施五年计划，优先发展重工业，1936 年新宪法宣布建成社会主义。苏联模式高度集中，短期内实现工业化，但弊端严重。"},{"type":"note","title":"本课主线 · 因果链","text":"帝国主义国家政治经济发展不平衡，两大军事集团对抗，1914 年一战爆发；四年大战削弱了帝国主义力量、促成俄国十月革命，战后列强通过巴黎和会与华盛顿会议建立起「凡尔赛—华盛顿体系」，暂时调整了世界秩序；苏俄以新经济政策恢复经济并成立苏联，亚非拉的民族民主运动（印度非暴力不合作、土耳其凯末尔革命）也在战后高涨。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1921 年","苏俄开始实行新经济政策","以征收粮食税代替余粮收集制，允许多种经济并存、大力发展商品经济，国民经济迅速恢复 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"新经济政策（1921 年起）：以征收…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"政策必须立足国情、实事求是：新经济政…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"新经济政策（1921 年起）：以征收粮食税代替余粮收集制；允许使用雇佣劳动力和出租土地，农民可以自由买卖纳税后的剩余产品；允许私人经营中小企业；实行自由贸易；废除生活必需品配给制。特点是允许多种经济并存、大力发展商品经济；作用是调动了生产者的积极性，迅速缓解危机，促使国民经济稳步发展。","explain":"「新」在哪里是必答点：利用市场和商品货币关系来发展经济，而不是单纯依靠行政命令。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为苏俄新经济政策是放弃社会主义、恢复资本主义。","新经济政策是在国家掌握经济命脉的前提下，利用市场和商品货币关系发展经济，是向社会主义过渡的正确途径。","判断政策性质要看「谁掌握经济命脉、目的是什么」，不能只看是否有市场因素。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局的起点","以「凡尔赛—华盛顿体系」为切口考查战后格局如何形成、为何不能持久，常与第四单元「雅尔塔体系与两极格局」组合成「20 世纪世界格局的三次变动」大题。"],["大国关系与军事集团","给出三国同盟与三国协约的示意图或结盟材料，要求指出两大集团的核心国家、说明欧洲两大军事集团对峙与一战爆发的关系。"],["中国史联动：外交失败与民族觉醒","把巴黎和会、《九国公约》与五四运动、中国共产党的成立串成一线，落点在「弱国无外交」与「中国国际地位的今昔对比」。"],["社会主义运动的探索","十月革命（建立政权）与新经济政策（恢复经济）常作为一组材料，要求说明「社会主义道路需要不断探索、政策要符合国情」。"]]},{"type":"note","title":"跨学科视角","text":"地理：巴尔干与欧洲战场；道德与法治：战争与和平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"斯大林","v":"苏联领导人，推行五年计划和农业集体化，形成苏联模式。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["新经济政策：以粮食税代替余粮收集制，允许私人经营中小企业，恢复自由贸易，利用市场和商品货币关系发展经济。 出处：2024 部编版九下第 11 课","苏联模式：高度集中的计划经济体制和高度集权的政治体制，优先发展重工业，牺牲农业和轻工业，长期看不利于经济持续发展。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 11 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u3-q5","type":"choice","stem":"1921 年苏俄开始实行新经济政策，其「新」主要体现在","answer":"B","explain":"新经济政策以征收粮食税代替余粮收集制，允许私人经营中小企业、实行自由贸易，即利用市场和商品货币关系发展经济；国家仍掌握经济命脉，不是放弃社会主义。","options":["全面实行余粮收集制","允许多种经济并存，大力发展商品经济，利用市场和商品货币关系发展经济","取消商品交换，实行生活必需品配给制","放弃国家对经济命脉的控制"],"tags":["新经济政策","历史解释"]},{"id":"cat-9b-3-4-g2","type":"choice","stem":"下列关于「苏联的社会主义建设」的表述，错误的是","answer":"A","explain":"认为苏俄新经济政策是放弃社会主义、恢复资本主义——判断政策性质要看「谁掌握经济命脉、目的是什么」，不能只看是否有市场因素。正确表述：新经济政策是在国家掌握经济命脉的前提下，利用市场和商品货币关系发展经济，是向社会主义过渡的正确途径。","options":["认为苏俄新经济政策是放弃社会主义、恢复资本主义。","新经济政策是在国家掌握经济命脉的前提下，利用市场和商品货币关系发展经济，是向社会主义过渡的正确途径。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。","新经济政策（1921 年起）：以征收粮食税代替余粮收集制；允许使用雇佣劳动力和出租土地，农民可以自由买卖纳税后的剩余产品；允许私人经营中小企业；实行自由贸易；废除生活必需品配给制。特点是允许多种经济并存、大力发展商品经济；作用是调动了生产者的积极性，迅速缓解危机，促使国民经济稳步发展。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-4-g3","type":"choice","stem":"下列结论中，属于「苏联的社会主义建设」的是","answer":"A","explain":"本课结论：政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：以粮食税代替余粮收集制，允许私人经营中小企业，恢复自由贸易，利用市场和商品货币关系发展经济。（2024 部编版九下第 11 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"苏联的社会主义建设；新经济政策（1921 年起）：以征收粮食税代替余粮收集制；允许使用雇佣劳动力和出租土地，农民可以自由买卖纳税后的剩余产品；允许私人经营中小企业；实行自由贸易；废除生活必需品配给制。特点是允许多种经济并存、大力发展商品经济；作用是调动了生产者的积极性，迅速缓解危机，促使国民经济稳步发展。","explain":"材料出自2024 部编版九下第 11 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]},{"id":"cat-9b-3-4-g5","type":"choice","stem":"「苏俄开始实行新经济政策」发生于","answer":"A","explain":"本课时间轴：苏俄开始实行新经济政策（1921 年）。以征收粮食税代替余粮收集制，允许多种经济并存、大力发展商品经济，国民经济迅速恢复。其余三个时间是同一单元相邻课时的事件时间。","options":["1921 年","1882 年","1907 年","1914 年 6 月"],"difficulty":1,"tags":["九年级下册","第三单元","本课练习"]}]},{"id":"cat-9b-3-5","title":"第12课 亚非拉民族民主运动的高涨","subtitle":"九年级下册 · 第三单元 第一次世界大战和战后初期的世界","grade":"9b","tags":["九年级下册","第三单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第三单元 第一次世界大战和战后初期的世界"},{"k":"课时","v":"第12课 亚非拉民族民主运动的高涨"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"一战后，亚非拉民族民主运动高涨。甘地在印度领导非暴力不合作运动，凯末尔领导土耳其革命，1923 年建立土耳其共和国。这些运动打击了殖民统治，推动了民族独立。"},{"type":"note","title":"本课主线 · 因果链","text":"帝国主义国家政治经济发展不平衡，两大军事集团对抗，1914 年一战爆发；四年大战削弱了帝国主义力量、促成俄国十月革命，战后列强通过巴黎和会与华盛顿会议建立起「凡尔赛—华盛顿体系」，暂时调整了世界秩序；苏俄以新经济政策恢复经济并成立苏联，亚非拉的民族民主运动（印度非暴力不合作、土耳其凯末尔革命）也在战后高涨。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1920 年起","印度非暴力不合作运动","甘地号召印度人民用非暴力的方式抵制英国殖民统治，打击了英国的殖民统治，增强了印度人民的民族自尊心"],["1919—1923 年","土耳其凯末尔革命","凯末尔领导土耳其人民赢得民族独立，1923 年建立土耳其共和国并推行世俗化改革"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1920 年起","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"印度非暴力不合作运动","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1919—1923 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"土耳其凯末尔革命","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"次重点","text":"亚非拉的民族民主运动：印度甘地领导的非暴力不合作运动（1920 年起）打击了英国殖民统治；土耳其凯末尔革命（1919—1923）赢得民族独立并建立共和国；埃及华夫脱运动迫使英国有条件地承认埃及独立。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。"],["认为《凡尔赛条约》是战胜国与被战胜国之间的公平条约。","它是战胜国重新瓜分世界的条约：对德国索取巨额赔款、分割领土，对中国极不公平（把德国在山东的特权转让给日本），激化了矛盾，埋下新的战争祸根。","评价条约要抓住「分赃」二字，并联系中国外交失败与五四运动。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局的起点","以「凡尔赛—华盛顿体系」为切口考查战后格局如何形成、为何不能持久，常与第四单元「雅尔塔体系与两极格局」组合成「20 世纪世界格局的三次变动」大题。"],["大国关系与军事集团","给出三国同盟与三国协约的示意图或结盟材料，要求指出两大集团的核心国家、说明欧洲两大军事集团对峙与一战爆发的关系。"],["中国史联动：外交失败与民族觉醒","把巴黎和会、《九国公约》与五四运动、中国共产党的成立串成一线，落点在「弱国无外交」与「中国国际地位的今昔对比」。"],["社会主义运动的探索","十月革命（建立政权）与新经济政策（恢复经济）常作为一组材料，要求说明「社会主义道路需要不断探索、政策要符合国情」。"]]},{"type":"note","title":"跨学科视角","text":"地理：巴尔干与欧洲战场；道德与法治：战争与和平。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["非暴力不合作","甘地领导的印度民族解放运动方式，以和平手段抵制英国殖民统治。","2024 部编版九下第 12 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"甘地","v":"印度民族解放运动领袖，倡导非暴力不合作。 出处：2024 部编版九下第 12 课"},{"k":"凯末尔","v":"土耳其共和国缔造者，推行世俗化改革。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["非暴力不合作：甘地主张以和平方式抵制英国殖民统治，包括放弃英国授予的爵位、抵制英货、拒绝在政府任职、不送子女入英国学校等。 出处：2024 部编版九下第 12 课","凯末尔革命：1919 年凯末尔领导土耳其民族解放战争，1923 年建立土耳其共和国，推行世俗化改革。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 12 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u3-q1","type":"choice","stem":"第一次世界大战爆发的根本原因是","answer":"B","explain":"根本原因是帝国主义国家政治经济发展不平衡，后起的帝国主义国家要求重新瓜分世界，与老牌殖民国家矛盾激化。萨拉热窝事件是导火线，两大军事集团的形成是具体条件。","options":["萨拉热窝事件的发生","帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权","三国同盟与三国协约的形成","塞尔维亚与奥匈帝国的领土争端"],"tags":["第一次世界大战","唯物史观"]},{"id":"h9b-u3-q2","type":"choice","stem":"1914 年，奥匈帝国皇储夫妇被刺杀，这一事件成为第一次世界大战的","answer":"B","explain":"1914 年 6 月的萨拉热窝事件是第一次世界大战的导火线；大战的根本原因是帝国主义国家政治经济发展不平衡。","options":["根本原因","导火线（直接原因）","结束标志","转折点"],"tags":["萨拉热窝事件","时空观念"]},{"id":"h9b-u3-q3","type":"choice","stem":"1919 年，中国在巴黎和会上外交失败，德国在中国山东的特权被转让给日本。这一消息直接引发了","answer":"C","explain":"巴黎和会上中国外交失败的消息传回国内，直接引发 1919 年五四运动的爆发，五四运动标志着中国新民主主义革命的开端。","options":["洋务运动","戊戌变法","五四运动","新文化运动"],"tags":["巴黎和会","中外关联"]},{"id":"cat-9b-3-5-g2","type":"choice","stem":"下列关于「亚非拉民族民主运动的高涨」的表述，错误的是","answer":"A","explain":"把萨拉热窝事件说成第一次世界大战爆发的根本原因——「根本原因—导火线」的区分是最高频的失分点，凡遇「根本」二字都要往经济与制度矛盾上想。正确表述：萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","options":["把萨拉热窝事件说成第一次世界大战爆发的根本原因。","萨拉热窝事件是导火线（直接原因）；根本原因是帝国主义国家政治经济发展不平衡，争夺殖民地和世界霸权。","民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。","亚非拉的民族民主运动：印度甘地领导的非暴力不合作运动（1920 年起）打击了英国殖民统治；土耳其凯末尔革命（1919—1923）赢得民族独立并建立共和国；埃及华夫脱运动迫使英国有条件地承认埃及独立。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-5-g3","type":"choice","stem":"下列结论中，属于「亚非拉民族民主运动的高涨」的是","answer":"A","explain":"本课结论：民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["民族解放运动必须与本国国情相适应：甘地走非暴力不合作道路，凯末尔走武装斗争与世俗化改革道路，都推动了民族民主运动的发展。","「凡尔赛—华盛顿体系」是帝国主义重新瓜分世界的体系：它暂时调整了列强关系，但不可能消除矛盾，因此不能带来持久和平。","十月革命开辟了人类历史的新纪元：社会主义由理论变为现实，从此世界出现了社会主义与资本主义两种制度并存的局面。","政策必须立足国情、实事求是：新经济政策利用市场和商品货币关系恢复经济，是在坚持社会主义方向前提下的成功探索。"],"difficulty":2,"tags":["九年级下册","第三单元","本课练习"]},{"id":"cat-9b-3-5-g4","type":"short","stem":"阅读材料，回答问题。\n材料：甘地主张以和平方式抵制英国殖民统治，包括放弃英国授予的爵位、抵制英货、拒绝在政府任职、不送子女入英国学校等。（2024 部编版九下第 12 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"亚非拉民族民主运动的高涨；亚非拉的民族民主运动：印度甘地领导的非暴力不合作运动（1920 年起）打击了英国殖民统治；土耳其凯末尔革命（1919—1923）赢得民族独立并建立共和国；埃及华夫脱运动迫使英国有条件地承认埃及独立。","explain":"材料出自2024 部编版九下第 12 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第三单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-4-1","title":"第13课 资本主义经济大危机","subtitle":"九年级下册 · 第四单元 资本主义经济大危机和第二次世界大战","grade":"9b","tags":["九年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第四单元 资本主义经济大危机和第二次世界大战"},{"k":"课时","v":"第13课 资本主义经济大危机"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1929 年，美国股市崩盘，经济大危机爆发，波及整个资本主义世界。1933 年罗斯福就任美国总统，推行新政：整顿金融、调整农业、复兴工业、以工代赈、建立社会保障。新政开创了国家干预经济的新模式。"},{"type":"note","title":"本课主线 · 因果链","text":"1929—1933 年的经济大危机使资本主义世界陷入混乱：美国以罗斯福新政加强国家对经济的干预、逐步走出危机，德日则走上法西斯道路并对外侵略扩张；英法等国的绥靖政策助长了侵略，1939 年德国突袭波兰使二战全面爆发；1942 年《联合国家宣言》的签署使世界反法西斯同盟正式形成，1945 年法西斯彻底失败，二战深刻改变了世界格局。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1929—1933 年","资本主义世界经济大危机","1929 年 10 月美国股市崩溃，危机迅速波及整个资本主义世界：范围广、时间长、破坏性大 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"wide","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":13,"text":"1929—1933 年经济大危机的特…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":34.25,"text":"罗斯福新政：中心措施是对工业的调整（…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":55.5,"text":"罗斯福新政是在不改变资本主义制度前提…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。","explain":"要能分清「根源（制度基本矛盾）」与「直接原因（生产与销售的矛盾、生产过剩）」；罗斯福新政只能缓解危机，不能消除危机，原因就在这里。"},{"level":"重点","text":"罗斯福新政：中心措施是对工业的调整（《全国工业复兴法》）；还包括整顿金融体系、调整农业政策、推行「以工代赈」（兴办公共工程）。特点是加强国家对经济的干预和指导。作用是使美国度过了经济危机，经济缓慢恢复，人民生活得到改善，联邦政府的调控能力增强；但它是在不改变资本主义制度前提下的调整，不能从根本上消除经济危机。","explain":"两个必答判断：新政的实质是资本主义制度的自我调整（不是社会主义），新政开创了国家干预经济的新模式。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为罗斯福新政是社会主义性质的改革。","新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","判断改革性质看「是否改变社会制度」：新政不改变私有制与资产阶级统治，因此不是社会主义改革。"],["认为罗斯福新政使美国彻底消除了经济危机。","新政只能缓解危机，不能从根本上消除经济危机，因为经济危机的根源——资本主义制度的基本矛盾依然存在。","凡出现「彻底」「根本消除」等绝对化表述，基本可判为错误。"]]},{"type":"table","title":"苏俄新经济政策与罗斯福新政（两种社会制度下的政策调整与创新）","head":["比较项","苏俄新经济政策（1921 年起）","罗斯福新政（1933 年起）"],"rows":[["背景","国内战争结束后经济困难、政治危机严重","1929—1933 年经济大危机冲击美国"],["主要手段","以征收粮食税代替余粮收集制，允许多种经济并存、大力发展商品经济，利用市场和商品货币关系","加强国家对经济的干预和指导，中心措施是对工业的调整（《全国工业复兴法》）"],["实质","在坚持社会主义制度前提下利用市场发展经济","在不改变资本主义制度前提下加强国家干预"],["结果","调动了生产者的积极性，国民经济迅速恢复和发展","使美国度过危机、经济缓慢恢复，开创国家干预经济的新模式"],["共同点","都是在原有制度框架内的政策调整，都取得成效，都体现了实事求是、勇于创新的精神","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局","把「凡尔赛—华盛顿体系 → 二战 → 雅尔塔体系与两极格局」串成一条线，考查格局的形成者、特征与结局，是材料大题最稳定的考法之一。"],["大国关系与绥靖政策的教训","以慕尼黑会议的材料考查「绥靖政策为什么加速了二战爆发」，进而要求谈对「面对侵略不能退让妥协」的认识。"],["中国抗战与世界反法西斯战争","给出中国战场牵制日军兵力或中国抗战贡献的材料，要求说明中国战场的地位，落点在家国情怀与世界意识。"],["应对危机的两种选择","对比美国罗斯福新政与德日走上法西斯道路，考查「同一场危机为什么走出两条不同道路」，是考查历史解释能力的高频题。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：法西斯与集体安全；地理：二战主要战场。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["炉边谈话","罗斯福通过广播向民众发表谈话，解释新政，稳定人心。","吴于廑、齐世荣《世界史·现代史编》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"罗斯福","v":"美国第 32 任总统，推行新政应对经济大危机。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["罗斯福新政：通过《紧急银行法》《农业调整法》《全国工业复兴法》等，加强国家对经济的干预和指导，缓解危机。 出处：2024 部编版九下第 13 课","以工代赈：政府兴办公共工程，如田纳西河流域治理、修建公路桥梁，吸纳失业人口，刺激消费。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 13 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u4-q1","type":"choice","stem":"1929—1933 年资本主义世界经济大危机的特点不包括","answer":"D","explain":"这次经济大危机的特点是涉及范围特别广、持续时间比较长、破坏性特别大。它从美国开始，迅速波及整个资本主义世界，并非只在英国发生。","options":["涉及范围特别广","持续时间比较长","破坏性特别大","只在英国一国发生"],"tags":["经济大危机","历史解释"]},{"id":"h9b-u4-q2","type":"choice","stem":"罗斯福新政的中心措施是","answer":"B","explain":"新政的中心措施是对工业的调整，通过《全国工业复兴法》加强国家对工业的计划指导。整顿金融、调整农业、以工代赈都是新政的重要措施，但不是中心措施。","options":["整顿金融体系","对工业的调整（《全国工业复兴法》）","调整农业政策","推行「以工代赈」，兴办公共工程"],"tags":["罗斯福新政","历史解释"]},{"id":"cat-9b-4-1-g2","type":"choice","stem":"下列关于「资本主义经济大危机」的表述，错误的是","answer":"A","explain":"认为罗斯福新政是社会主义性质的改革——判断改革性质看「是否改变社会制度」：新政不改变私有制与资产阶级统治，因此不是社会主义改革。正确表述：新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","options":["认为罗斯福新政是社会主义性质的改革。","新政是在不改变资本主义制度前提下的自我调整：运用国家力量干预经济，目的是维护资本主义统治、缓解危机。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-1-g3","type":"choice","stem":"下列结论中，属于「资本主义经济大危机」的是","answer":"A","explain":"本课结论：罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：通过《紧急银行法》《农业调整法》《全国工业复兴法》等，加强国家对经济的干预和指导，缓解危机。（2024 部编版九下第 13 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"资本主义经济大危机；1929—1933 年经济大危机的特点与根源：特点是涉及范围特别广、持续时间比较长、破坏性特别大（整个资本主义世界的工业产量下降 1/3 以上，失业工人超过 3000 万）。根源是资本主义制度的基本矛盾，即生产社会化与生产资料私人占有之间的矛盾。","explain":"材料出自2024 部编版九下第 13 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-4-2","title":"第14课 法西斯国家的侵略扩张","subtitle":"九年级下册 · 第四单元 资本主义经济大危机和第二次世界大战","grade":"9b","tags":["九年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第四单元 资本主义经济大危机和第二次世界大战"},{"k":"课时","v":"第14课 法西斯国家的侵略扩张"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1929 年经济危机后，德国、日本走上法西斯道路。1933 年希特勒出任德国总理，建立法西斯专政；日本军部法西斯势力膨胀。1938 年慕尼黑协定，英法出卖捷克斯洛伐克，绥靖政策达到顶峰。"},{"type":"note","title":"本课主线 · 因果链","text":"1929—1933 年的经济大危机使资本主义世界陷入混乱：美国以罗斯福新政加强国家对经济的干预、逐步走出危机，德日则走上法西斯道路并对外侵略扩张；英法等国的绥靖政策助长了侵略，1939 年德国突袭波兰使二战全面爆发；1942 年《联合国家宣言》的签署使世界反法西斯同盟正式形成，1945 年法西斯彻底失败，二战深刻改变了世界格局。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1933 年","希特勒出任德国总理，德国建立法西斯专政","世界大战的欧洲战争策源地形成"],["1936 年","日本军部法西斯专政建立","受军部控制的广田弘毅内阁上台，世界大战的亚洲战争策源地形成；此前 1931 年日本已发动九一八事变侵略中国"],["1938 年 9 月","慕尼黑会议","英、法、德、意四国首脑把捷克斯洛伐克的苏台德区割让给德国，绥靖政策达到顶峰，加速了二战的爆发"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1933 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"希特勒出任德国总理，德国建立法西斯专…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1936 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"日本军部法西斯专政建立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1938 年 9 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"慕尼黑会议","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"二战的性质与影响：二战是世界范围内反法西斯的正义战争；它彻底粉碎了法西斯主义和军国主义通过战争称霸世界的野心，给人类带来空前灾难（先后有 60 多个国家和地区、20 亿以上人口卷入，死亡 5000 多万人）；战后欧洲衰落、美苏崛起，形成美苏对峙的两极格局；促进了民族解放运动的发展和科学技术的进步。","explain":"「性质（反法西斯的正义战争）— 影响（格局、民族解放、科技、灾难）」是固定答题结构。"},{"level":"次重点","text":"法西斯国家的侵略扩张与绥靖政策：德国（1933 年希特勒上台）、意大利（墨索里尼）、日本（1936 年军部法西斯专政）先后建立法西斯政权并对外侵略；英法推行绥靖政策，其顶峰是 1938 年慕尼黑会议。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为绥靖政策从慕尼黑会议开始。","绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","「开始」与「顶峰」是两问，慕尼黑会议是顶峰而非起点。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局","把「凡尔赛—华盛顿体系 → 二战 → 雅尔塔体系与两极格局」串成一条线，考查格局的形成者、特征与结局，是材料大题最稳定的考法之一。"],["大国关系与绥靖政策的教训","以慕尼黑会议的材料考查「绥靖政策为什么加速了二战爆发」，进而要求谈对「面对侵略不能退让妥协」的认识。"],["中国抗战与世界反法西斯战争","给出中国战场牵制日军兵力或中国抗战贡献的材料，要求说明中国战场的地位，落点在家国情怀与世界意识。"],["应对危机的两种选择","对比美国罗斯福新政与德日走上法西斯道路，考查「同一场危机为什么走出两条不同道路」，是考查历史解释能力的高频题。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：法西斯与集体安全；地理：二战主要战场。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["绥靖政策","对法西斯侵略者妥协退让、牺牲弱小国家利益以保全自身的政策，助长了侵略气焰。","2024 部编版九下第 14 课"]]},{"type":"kv","title":"人物卡片","items":[{"k":"希特勒","v":"德国纳粹党首领，1933 年出任总理，建立法西斯专政。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["慕尼黑协定：1938 年 9 月，英、法、德、意四国首脑在慕尼黑签订协定，把捷克斯洛伐克的苏台德地区割让给德国，捷方未参会。 出处：吴于廑、齐世荣《世界史·现代史编》","轴心国：1936 年德意签订协定，1937 年意大利加入《反共产国际协定》，形成「柏林—罗马—东京」轴心。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 14 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u4-q6","type":"choice","stem":"1938 年，英、法、德、意四国首脑在没有捷克斯洛伐克代表参加的情况下，把苏台德区割让给德国。这一事件说明","answer":"A","explain":"慕尼黑会议把捷克斯洛伐克的苏台德区割让给德国，是绥靖政策达到顶峰的标志，助长了法西斯的侵略野心，加速了第二次世界大战的爆发。","options":["绥靖政策达到顶峰，加速了二战的爆发","法西斯国家的侵略被彻底制止","世界反法西斯同盟已经形成","德国的侵略野心得到有效遏制"],"tags":["慕尼黑会议","历史解释"]},{"id":"cat-9b-4-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 希特勒出任德国总理，德国建立法西斯专政\n② 日本军部法西斯专政建立\n③ 慕尼黑会议","answer":"A","explain":"按时间顺序应为：①希特勒出任德国总理，德国建立法西斯专政（1933 年）→②日本军部法西斯专政建立（1936 年）→③慕尼黑会议（1938 年 9 月）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g2","type":"choice","stem":"下列关于「法西斯国家的侵略扩张」的表述，错误的是","answer":"A","explain":"认为绥靖政策从慕尼黑会议开始——「开始」与「顶峰」是两问，慕尼黑会议是顶峰而非起点。正确表述：绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","options":["认为绥靖政策从慕尼黑会议开始。","绥靖政策在 20 世纪 30 年代逐步推行（如纵容日本侵占中国东北、纵容意大利侵略埃塞俄比亚、纵容德国吞并奥地利），其顶峰是 1938 年 9 月的慕尼黑会议。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g3","type":"choice","stem":"下列结论中，属于「法西斯国家的侵略扩张」的是","answer":"A","explain":"本课结论：世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","罗斯福新政是在不改变资本主义制度前提下的自我调整，实质是维护资本主义统治；它开创了国家干预经济的新模式，但不能消除资本主义的基本矛盾。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1938 年 9 月，英、法、德、意四国首脑在慕尼黑签订协定，把捷克斯洛伐克的苏台德地区割让给德国，捷方未参会。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"法西斯国家的侵略扩张；二战的性质与影响：二战是世界范围内反法西斯的正义战争；它彻底粉碎了法西斯主义和军国主义通过战争称霸世界的野心，给人类带来空前灾难（先后有 60 多个国家和地区、20 亿以上人口卷入，死亡 5000 多万人）；战后欧洲衰落、美苏崛起，形成美苏对峙的两极格局；促进了民族解放运动的发展和科学技术的进步。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-4-3","title":"第15课 第二次世界大战","subtitle":"九年级下册 · 第四单元 资本主义经济大危机和第二次世界大战","grade":"9b","tags":["九年级下册","第四单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第四单元 资本主义经济大危机和第二次世界大战"},{"k":"课时","v":"第15课 第二次世界大战"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"1939 年 9 月 1 日，德国突袭波兰，二战全面爆发。1941 年德国进攻苏联，日本偷袭珍珠港，战争扩大到全球。1942 年《联合国家宣言》签署，世界反法西斯同盟形成。1945 年 5 月德国投降，9 月日本投降，二战结束。"},{"type":"note","title":"本课主线 · 因果链","text":"1929—1933 年的经济大危机使资本主义世界陷入混乱：美国以罗斯福新政加强国家对经济的干预、逐步走出危机，德日则走上法西斯道路并对外侵略扩张；英法等国的绥靖政策助长了侵略，1939 年德国突袭波兰使二战全面爆发；1942 年《联合国家宣言》的签署使世界反法西斯同盟正式形成，1945 年法西斯彻底失败，二战深刻改变了世界格局。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1938 年 9 月","慕尼黑会议","英、法、德、意四国首脑把捷克斯洛伐克的苏台德区割让给德国，绥靖政策达到顶峰，加速了二战的爆发"],["1939 年 9 月 1 日","德国突袭波兰，英法对德宣战，第二次世界大战全面爆发","绥靖政策破产；注意：七七事变是中国全民族抗战的开始，不是二战全面爆发的标志 · 重点"],["1941 年 6 月 22 日","德国进攻苏联，苏德战争爆发","二战规模扩大；莫斯科保卫战打破了德军不可战胜的神话"],["1941 年 12 月 7 日","日本偷袭珍珠港，太平洋战争爆发","二战达到最大规模，美国对日宣战"],["1942 年 1 月 1 日","《联合国家宣言》签署","美、英、苏、中等 26 国在华盛顿签署，标志世界反法西斯同盟正式形成——战胜法西斯的根本保证 · 重点"],["1942 年 7 月—1943 年 2 月","斯大林格勒战役","苏军击败德军，是苏德战场的转折点，也是第二次世界大战的转折点"],["1944 年 6 月 6 日","诺曼底登陆","美英盟军在法国诺曼底登陆，开辟了欧洲第二战场，德国陷入东西两面夹击"],["1945 年 2 月","雅尔塔会议","美、英、苏三国首脑会议，决定彻底打败德国、战后成立联合国、苏联对日作战"]]},{"type":"figure","figure":{"id":"","title":"历史现场 · 二战进程：从波兰到日本投降","caption":"示意图：二战进程：从波兰到日本投降，详见下方「历史现场」","view":"tall","alt":"示意图：二战进程：从波兰到日本投降，详见下方「历史现场」","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1939 年 9 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"德国突袭波兰，二战全面爆发","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":29.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":32.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":29.67,"text":"1941 年 6 月 2…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":35.67,"text":"德国进攻苏联，苏德战争爆发","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":36.07,"x2":14,"y2":47.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":51.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":48.33,"text":"1941 年 12 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":54.33,"text":"日本偷袭珍珠港，太平洋战争爆发","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":54.73,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1942 年 1 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"26 国签署《联合国家宣言》，世界反…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":85.27,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":88.67,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":85.67,"text":"1942—1943 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":91.67,"text":"斯大林格勒战役，苏军转入反攻","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":92.07,"x2":14,"y2":103.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":107.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":104.33,"text":"1944 年 6 月 6…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":110.33,"text":"诺曼底登陆，开辟欧洲第二战场","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":110.73,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1945 年 5 月 8…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"德国无条件投降","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"第二次世界大战的爆发与扩大：1939 年 9 月 1 日德国突袭波兰，英法对德宣战，二战全面爆发；1941 年 6 月苏德战争爆发、12 月太平洋战争爆发，二战规模空前扩大，达到最大规模。","explain":"「全面爆发」「规模扩大」「达到最大规模」三个节点必须分清，这是选择题最爱设的年份陷阱。"},{"level":"重点","text":"世界反法西斯同盟的形成与作用：1942 年 1 月 1 日，美、英、苏、中等 26 国签署《联合国家宣言》，标志世界反法西斯同盟正式形成；它壮大了反法西斯力量，是最终战胜法西斯的根本保证。","explain":"材料题常问「二战胜利的根本原因」，标准答法即「世界反法西斯同盟的建立与反法西斯国家的协同作战」。"},{"level":"重点","text":"二战的重要转折与胜利：斯大林格勒战役是苏德战场的转折点，也是第二次世界大战的转折点；1944 年诺曼底登陆开辟欧洲第二战场；1945 年 2 月雅尔塔会议决定彻底打败德国、成立联合国、苏联对日作战；1945 年 5 月 8 日德国投降，9 月 2 日日本签署投降书，二战结束。","explain":"易错：二战的转折点是斯大林格勒战役，不是诺曼底登陆；中途岛战役是太平洋战场的转折点。"},{"level":"重点","text":"二战的性质与影响：二战是世界范围内反法西斯的正义战争；它彻底粉碎了法西斯主义和军国主义通过战争称霸世界的野心，给人类带来空前灾难（先后有 60 多个国家和地区、20 亿以上人口卷入，死亡 5000 多万人）；战后欧洲衰落、美苏崛起，形成美苏对峙的两极格局；促进了民族解放运动的发展和科学技术的进步。","explain":"「性质（反法西斯的正义战争）— 影响（格局、民族解放、科技、灾难）」是固定答题结构。"},{"level":"选择题","text":"雅尔塔会议、《波茨坦公告》的主要内容；莫斯科保卫战、中途岛战役、阿拉曼战役等重大战役。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。","中国是世界反法西斯战争的东方主战场，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为第二次世界大战全面爆发的标志是七七事变或德国进攻苏联。","1939 年 9 月 1 日德国突袭波兰、英法对德宣战，标志二战全面爆发；七七事变是中国全民族抗战的开始；1941 年苏德战争爆发标志二战规模扩大。","「全面爆发」与「中国全民族抗战开始」是两个不同层面的概念，材料题常把两者并置设陷阱。"],["认为诺曼底登陆是第二次世界大战的转折点。","二战的转折点是斯大林格勒战役（1942.7—1943.2）；诺曼底登陆开辟了欧洲第二战场，使德国陷入东西两面夹击，加速了法西斯德国的灭亡。","「战役的作用」表述必须准确：转折点、开辟第二战场、加速灭亡各不相同。"]]},{"type":"table","title":"中国抗日战争与世界反法西斯战争（中国史联动）（中国抗战在世界反法西斯战争中的地位与作用）","head":["比较项","中国抗日战争","世界反法西斯战争"],"rows":[["开始时间","1931 年九一八事变后开始局部抗战，1937 年七七事变后进入全民族抗战","1939 年 9 月德国突袭波兰，欧洲战场全面爆发；1941 年后扩大到全球"],["性质","既是民族解放战争，又是世界反法西斯战争的重要组成部分","世界范围的反法西斯的正义战争"],["主要战场","中国战场是世界反法西斯战争的东方主战场，长期牵制和消耗日本陆军主力","苏德战场是欧洲主战场，太平洋战场是另一重要战场"],["重大战役与事件","台儿庄战役、武汉会战、百团大战、第三次长沙会战","斯大林格勒战役、诺曼底登陆、雅尔塔会议"],["结果","1945 年 8 月 15 日日本宣布无条件投降，抗日战争取得胜利","1945 年 9 月 2 日日本签署投降书，第二次世界大战结束"],["历史意义","中国为世界反法西斯战争的胜利作出巨大贡献，也付出巨大民族牺牲","正义战胜邪恶、光明战胜黑暗，深刻改变了世界格局"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["两次世界大战与战后格局","把「凡尔赛—华盛顿体系 → 二战 → 雅尔塔体系与两极格局」串成一条线，考查格局的形成者、特征与结局，是材料大题最稳定的考法之一。"],["大国关系与绥靖政策的教训","以慕尼黑会议的材料考查「绥靖政策为什么加速了二战爆发」，进而要求谈对「面对侵略不能退让妥协」的认识。"],["中国抗战与世界反法西斯战争","给出中国战场牵制日军兵力或中国抗战贡献的材料，要求说明中国战场的地位，落点在家国情怀与世界意识。"],["应对危机的两种选择","对比美国罗斯福新政与德日走上法西斯道路，考查「同一场危机为什么走出两条不同道路」，是考查历史解释能力的高频题。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：法西斯与集体安全；地理：二战主要战场。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"历史现场 · 二战进程：从波兰到日本投降","head":["时间","经过"],"rows":[["1939 年 9 月 1 日","德国突袭波兰，二战全面爆发"],["1941 年 6 月 22 日","德国进攻苏联，苏德战争爆发"],["1941 年 12 月 7 日","日本偷袭珍珠港，太平洋战争爆发"],["1942 年 1 月","26 国签署《联合国家宣言》，世界反法西斯同盟形成"],["1942—1943 年","斯大林格勒战役，苏军转入反攻"],["1944 年 6 月 6 日","诺曼底登陆，开辟欧洲第二战场"],["1945 年 5 月 8 日","德国无条件投降"],["1945 年 9 月 2 日","日本签署投降书，二战结束"]]},{"type":"note","title":"现场解说","text":"二战是人类历史上规模最大的战争，给世界人民带来深重灾难，也推动了民族解放运动和科技发展。"},{"type":"list","title":"延伸阅读","items":["斯大林格勒战役：1942 年 7 月至 1943 年 2 月，苏军在斯大林格勒重创德军，是二战的重要转折点。 出处：吴于廑、齐世荣《世界史·现代史编》","诺曼底登陆：1944 年 6 月 6 日，美英盟军在法国诺曼底登陆，开辟欧洲第二战场。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 15 课；《联合国家宣言》原文","吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 列强侵华与中国人民的抗争","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-01"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】签字国政府……兹宣告：每一政府各自保证对与各该政府作战的三国同盟成员国及其附从者使用其全部资源，不论军事的或经济的。——《联合国家宣言》（1942 年 1 月 1 日，华盛顿）\n【材料二】我们唯一恐惧的就是恐惧本身……这个国家需要行动，而且现在就行动起来。——罗斯福 1933 年就职演说\n【材料三】抗日战争时期，中国战场是世界反法西斯战争的东方主战场。中国人民的抗战牵制和消耗了日本陆军的主力，为世界反法西斯战争的胜利作出了巨大贡献，也付出了巨大的民族牺牲。","source":"材料研读 · 经济大危机和第二次世界大战"}],"questions":[{"id":"h9b-u4-m1-q2","type":"short","stem":"（2）依据材料二、三并结合所学，概括世界反法西斯战争取得胜利的原因。（6 分）","answer":"①世界反法西斯同盟的建立，反法西斯国家互相配合、协同作战，是取得胜利的根本保证；②反法西斯战争是正义的战争，得到世界各国人民的广泛支持；③各国人民进行了英勇顽强的斗争、作出了巨大牺牲（如中国的全民族抗战、苏联的斯大林格勒战役、美国在太平洋战场的作战）；④斯大林格勒战役、诺曼底登陆等重大战役的胜利扭转了战局；⑤德意日法西斯发动的是侵略战争，失道寡助。此外，美国实行罗斯福新政增强了经济实力，也为反法西斯战争提供了重要的物质基础。","explain":"","tags":["第二次世界大战","历史解释"],"rubric":["世界反法西斯同盟的建立与协同作战（根本保证）","战争的性质是正义的反法西斯战争","各国人民的英勇斗争与巨大牺牲","重大战役扭转战局（斯大林格勒战役、诺曼底登陆）","法西斯侵略战争失道寡助（或美国国力增强提供物质基础）"]},{"id":"h9b-u4-q4","type":"choice","stem":"世界反法西斯同盟正式形成的标志是","answer":"B","explain":"1942 年 1 月 1 日，美、英、苏、中等 26 国签署《联合国家宣言》，标志世界反法西斯同盟正式形成。雅尔塔会议是 1945 年召开的战后安排会议，诺曼底登陆开辟欧洲第二战场，斯大林格勒战役是二战的转折点。","options":["雅尔塔会议的召开","1942 年 1 月 1 日《联合国家宣言》的签署","诺曼底登陆的成功","斯大林格勒战役的胜利"],"tags":["世界反法西斯同盟","时空观念"]},{"id":"h9b-u4-q5","type":"choice","stem":"第二次世界大战的转折点是","answer":"B","explain":"斯大林格勒战役（1942 年 7 月—1943 年 2 月）是苏德战场的转折点，也是第二次世界大战的转折点。诺曼底登陆开辟了欧洲第二战场，雅尔塔会议是战后的安排会议。","options":["莫斯科保卫战","斯大林格勒战役","诺曼底登陆","雅尔塔会议"],"tags":["第二次世界大战","历史解释"]},{"id":"h9b-u4-q6","type":"choice","stem":"1938 年，英、法、德、意四国首脑在没有捷克斯洛伐克代表参加的情况下，把苏台德区割让给德国。这一事件说明","answer":"A","explain":"慕尼黑会议把捷克斯洛伐克的苏台德区割让给德国，是绥靖政策达到顶峰的标志，助长了法西斯的侵略野心，加速了第二次世界大战的爆发。","options":["绥靖政策达到顶峰，加速了二战的爆发","法西斯国家的侵略被彻底制止","世界反法西斯同盟已经形成","德国的侵略野心得到有效遏制"],"tags":["慕尼黑会议","历史解释"]},{"id":"cat-9b-4-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 慕尼黑会议\n② 德国突袭波兰，英法对德宣战，第二次世界大战全面爆…\n③ 德国进攻苏联，苏德战争爆发\n④ 日本偷袭珍珠港，太平洋战争爆发","answer":"A","explain":"按时间顺序应为：①慕尼黑会议（1938 年 9 月）→②德国突袭波兰，英法对德宣战，第二次世界大战全面爆发（1939 年 9 月 1 日）→③德国进攻苏联，苏德战争爆发（1941 年 6 月 22 日）→④日本偷袭珍珠港，太平洋战争爆发（1941 年 12 月 7 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-3-g2","type":"choice","stem":"下列关于「第二次世界大战」的表述，错误的是","answer":"A","explain":"认为第二次世界大战全面爆发的标志是七七事变或德国进攻苏联——「全面爆发」与「中国全民族抗战开始」是两个不同层面的概念，材料题常把两者并置设陷阱。正确表述：1939 年 9 月 1 日德国突袭波兰、英法对德宣战，标志二战全面爆发；七七事变是中国全民族抗战的开始；1941 年苏德战争爆发标志二战规模扩大。","options":["认为第二次世界大战全面爆发的标志是七七事变或德国进攻苏联。","1939 年 9 月 1 日德国突袭波兰、英法对德宣战，标志二战全面爆发；七七事变是中国全民族抗战的开始；1941 年苏德战争爆发标志二战规模扩大。","世界反法西斯同盟的建立是战胜法西斯的根本保证：不同社会制度的国家可以联合起来，团结合作才能战胜共同的敌人。","第二次世界大战改变了世界格局：欧洲衰落、美苏崛起，雅尔塔体系取代凡尔赛—华盛顿体系，战后又演变为美苏对峙的两极格局。"],"difficulty":2,"tags":["九年级下册","第四单元","本课练习"]},{"id":"cat-9b-4-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1942 年 7 月至 1943 年 2 月，苏军在斯大林格勒重创德军，是二战的重要转折点。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"第二次世界大战；第二次世界大战的爆发与扩大：1939 年 9 月 1 日德国突袭波兰，英法对德宣战，二战全面爆发；1941 年 6 月苏德战争爆发、12 月太平洋战争爆发，二战规模空前扩大，达到最大规模。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第四单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-5-1","title":"第16课 冷战的发生与两极格局的形成","subtitle":"九年级下册 · 第五单元 第二次世界大战后的世界变化","grade":"9b","tags":["九年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第五单元 第二次世界大战后的世界变化"},{"k":"课时","v":"第16课 冷战的发生与两极格局的形成"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"二战后，美苏从盟友变为对手。1947 年杜鲁门主义出台，冷战开始；马歇尔计划援助西欧；1949 年北约成立，1955 年华约成立，两极格局形成。"},{"type":"note","title":"本课主线 · 因果链","text":"二战结束后，美苏因国家利益与意识形态的对立走向冷战：政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约对峙，1955 年两极格局最终形成；与此同时，西欧走向联合、日本迅速崛起、亚非拉国家纷纷独立，冲击着两极格局；1991 年苏联解体，两极格局结束，世界朝多极化方向发展。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1947 年 3 月","杜鲁门主义出台，冷战开始","美国公开宣称要「遏制」共产主义，标志美苏冷战开始；实质是干涉别国内政、称霸世界 · 重点"],["1947 年 6 月","马歇尔计划提出","即「欧洲复兴计划」，美国以经济援助帮助西欧恢复经济，是冷战在经济上的表现，同时加强了对西欧的控制"],["1949 年","德国分裂为联邦德国和民主德国","柏林危机后，德国分裂，成为欧洲冷战的焦点；1990 年两德统一"],["1955 年","华沙条约组织成立，两极格局最终形成","苏联与东欧 7 国签订《华沙条约》；以美苏为首的两大集团对峙局面（冷战对峙）最终形成 · 重点"],["1991 年","苏联解体","八一九事件后，12 月苏联 11 个加盟共和国签署《阿拉木图宣言》，苏联解体——标志冷战结束、两极格局终结 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1947 年 3 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"杜鲁门主义出台，冷战开始","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"1947 年 6 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"马歇尔计划提出","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"1949 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":73,"text":"德国分裂为联邦德国和民主德国","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"1955 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":101,"text":"华沙条约组织成立，两极格局最终形成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"1991 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"苏联解体","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"冷战的含义、开始标志与主要表现：冷战是二战后以美国和苏联为首的两大集团之间既非战争又非和平的对峙与竞争状态。1947 年 3 月杜鲁门主义的出台标志冷战开始；主要表现是政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约的成立，1949 年德国分裂是欧洲冷战的焦点。","explain":"「开始标志（杜鲁门主义）」「两极格局形成标志（1955 年华约成立）」必须分开记，这是最高频的时空陷阱。"},{"level":"重点","text":"冷战的影响与评价：两极格局下美苏势均力敌，在近半个世纪内避免了新的世界大战的爆发；但冷战使世界长期处于核战争的威胁之下，局部战争不断（朝鲜战争、越南战争），也给各国经济发展带来消极影响。1991 年苏联解体，冷战结束、两极格局终结。","explain":"评价要「一分为二」：客观上维护了总体和平，但严重威胁世界和平与各国发展。"},{"level":"重点","text":"苏联解体与东欧剧变：1989 年起东欧剧变，各国社会制度发生根本变化；1990 年两德统一；1991 年苏联解体，标志冷战结束和两极格局终结。苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正，直接原因是戈尔巴乔夫改革的失败，外部原因是西方国家的「和平演变」。","explain":"必背层级：根本原因（体制弊端）＞直接原因（改革失败）＞外部原因（和平演变）；不能把外部原因当根本原因。"},{"level":"次重点","text":"冷战中的对抗与局部战争：1948 年柏林危机、1962 年古巴导弹危机，以及朝鲜战争、越南战争等局部热战。","explain":""},{"level":"选择题","text":"马歇尔计划与杜鲁门主义的区别：前者是经济上的援助西欧计划，后者是政治上的冷战宣言；两者都是美国冷战政策的表现。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。"],["把马歇尔计划与杜鲁门主义混为一谈。","杜鲁门主义是政治上的冷战宣言（援助「自由国家」抵抗共产主义），马歇尔计划是经济上援助西欧复兴的计划。","同一政策的两条战线，常常作为材料并列出现，要求分别概括。"]]},{"type":"table","title":"世界格局的演变：两极格局与多极化趋势（中国史联动）（二战后世界格局的变动与中国的地位）","head":["比较项","两极格局（1955—1991）","多极化趋势（1991 年以来）"],"rows":[["主要力量","以美国为首的北约与以苏联为首的华约两大集团","美国、欧盟、日本、俄罗斯、中国等多个力量中心"],["基本特征","美苏冷战对峙、集团对抗，德国分裂为两个国家","呈现「一超多强」局面，多极化趋势不断加强"],["中国的地位","1971 年恢复在联合国的合法席位，1972 年中美关系开始正常化，国际地位逐步提高","改革开放后综合国力增强，成为推动世界多极化、维护世界和平的重要力量"],["共同规律","世界格局的变动取决于各国综合实力的消长，大国关系是关键","同左"],["对中国的启示","弱国无外交，发展才是硬道理","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["大国关系与冷战","以杜鲁门主义、马歇尔计划、北约与华约的材料，考查冷战的原因、表现与影响，常要求概括「冷战为什么没有演变为世界大战」。"],["世界格局的演变","把凡尔赛—华盛顿体系、雅尔塔体系（两极格局）与多极化趋势连成一条线，考查格局变动的原因与规律，是材料大题的高频结构。"],["中国史联动的改革比较","以苏联解体与中国特色社会主义的成功作对照，考查「改革为什么必须坚持正确方向、立足国情」，落点在制度自信。"],["亚非拉民族独立与发展","给出非洲独立进程或巴拿马收回运河主权的材料，要求说明殖民体系崩溃的过程与意义，并联系发展中国家的崛起对世界格局的影响。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：冷战与多极化；地理：北约、华约与地缘格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["铁幕演说","1946 年丘吉尔在美国富尔顿发表演说，称苏联和东欧被「铁幕」隔开，揭开冷战序幕。","吴于廑、齐世荣《世界史·现代史编》"]]},{"type":"kv","title":"人物卡片","items":[{"k":"杜鲁门","v":"美国总统，提出杜鲁门主义，冷战开始。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["杜鲁门主义：1947 年 3 月，美国总统杜鲁门在国会演说中提出遏制共产主义的主张，被视为冷战开始的标志。 出处：吴于廑、齐世荣《世界史·现代史编》","马歇尔计划：1947 年美国国务卿马歇尔提出援助欧洲复兴计划，促进西欧经济恢复，也加强了美国对西欧的控制。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 16 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】今天，几乎每一个国家都面临着两种生活方式的抉择……我认为，美国的政策必须是支持自由国家的人民抵抗少数武装分子或外来压力的征服企图。——杜鲁门 1947 年 3 月在国会发表的演说\n【材料二】美国应该尽力帮助世界恢复正常的经济秩序……我们的政策不是反对任何国家或任何主义，而是反对饥饿、贫穷、绝望和混乱。——马歇尔 1947 年 6 月在哈佛大学的演说\n【材料三】1991 年 12 月，苏联 11 个加盟共和国的领导人在阿拉木图签署宣言，宣布成立独立国家联合体，苏联解体。","source":"材料研读 · 二战后的世界变化"}],"questions":[{"id":"h9b-u5-m1-q2","type":"short","stem":"（2）综合三则材料并结合所学，说明冷战的主要表现，并分析苏联解体的原因及影响。（6 分）","answer":"主要表现：政治上出台杜鲁门主义；经济上推行马歇尔计划，援助西欧；军事上 1949 年成立北大西洋公约组织，1955 年苏联等国成立华沙条约组织，形成两大集团对峙，两极格局最终形成；1949 年德国分裂，欧洲成为冷战的重点地区。苏联解体的原因：根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；外部原因是西方国家的「和平演变」。影响：标志冷战结束、两极格局终结，世界格局向多极化方向发展；社会主义运动遭受严重挫折，但中国特色社会主义的成功证明社会主义制度具有强大的生命力。","explain":"","tags":["冷战","苏联解体","历史解释"],"rubric":["政治：杜鲁门主义","经济：马歇尔计划","军事：北约与华约的成立（两极格局最终形成）","苏联解体根本原因：高度集中的政治经济体制弊端长期得不到纠正","影响：冷战结束、两极格局终结、多极化趋势加强"]},{"id":"h9b-u5-q1","type":"choice","stem":"标志着美苏冷战开始的事件是","answer":"A","explain":"1947 年 3 月杜鲁门在国会发表演说，公开宣称要「遏制」共产主义，杜鲁门主义的出台标志美苏冷战开始。马歇尔计划是冷战在经济上的表现，北约与华约的成立标志两极格局最终形成。","options":["1947 年杜鲁门主义的出台","1947 年马歇尔计划的提出","1949 年北大西洋公约组织的成立","1955 年华沙条约组织的成立"],"tags":["冷战","时空观念"]},{"id":"h9b-u5-q2","type":"choice","stem":"标志着以美苏为首的两大集团对峙局面（两极格局）最终形成的事件是","answer":"C","explain":"1949 年北约成立后，1955 年苏联与东欧 7 国成立华沙条约组织，以美苏为首的两大集团对峙局面最终形成，两极格局由此确立。","options":["1949 年德国分裂","1949 年北约成立","1955 年华约成立","1962 年古巴导弹危机"],"tags":["两极格局","时空观念"]},{"id":"cat-9b-5-1-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 杜鲁门主义出台，冷战开始\n② 马歇尔计划提出\n③ 德国分裂为联邦德国和民主德国\n④ 华沙条约组织成立，两极格局最终形成","answer":"A","explain":"按时间顺序应为：①杜鲁门主义出台，冷战开始（1947 年 3 月）→②马歇尔计划提出（1947 年 6 月）→③德国分裂为联邦德国和民主德国（1949 年）→④华沙条约组织成立，两极格局最终形成（1955 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g2","type":"choice","stem":"下列关于「冷战的发生与两极格局的形成」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g3","type":"choice","stem":"下列结论中，属于「冷战的发生与两极格局的形成」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。","改革必须坚持正确方向、立足国情：戈尔巴乔夫改革背离社会主义方向、放弃党的领导，最终导致国家解体；中国改革开放坚持党的领导与社会主义道路，取得巨大成就。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1947 年 3 月，美国总统杜鲁门在国会演说中提出遏制共产主义的主张，被视为冷战开始的标志。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"冷战的发生与两极格局的形成；冷战的含义、开始标志与主要表现：冷战是二战后以美国和苏联为首的两大集团之间既非战争又非和平的对峙与竞争状态。1947 年 3 月杜鲁门主义的出台标志冷战开始；主要表现是政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约的成立，1949 年德国分裂是欧洲冷战的焦点。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-5-2","title":"第17课 二战后资本主义国家的变化","subtitle":"九年级下册 · 第五单元 第二次世界大战后的世界变化","grade":"9b","tags":["九年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第五单元 第二次世界大战后的世界变化"},{"k":"课时","v":"第17课 二战后资本主义国家的变化"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"二战后，资本主义国家加强国家干预，建立福利制度，经济恢复发展。欧洲走向联合：1967 年欧洲共同体成立，1993 年欧洲联盟成立。日本在美国扶植下经济迅速崛起。"},{"type":"note","title":"本课主线 · 因果链","text":"二战结束后，美苏因国家利益与意识形态的对立走向冷战：政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约对峙，1955 年两极格局最终形成；与此同时，西欧走向联合、日本迅速崛起、亚非拉国家纷纷独立，冲击着两极格局；1991 年苏联解体，两极格局结束，世界朝多极化方向发展。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1951 年、1967 年","欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立","法、意、联邦德国等六国从经济领域入手推进一体化，促进了西欧国家的经济发展和国际地位提高"],["20 世纪 60—70 年代","日本经济持续高速发展","日本成为资本主义世界仅次于美国的第二经济大国，并谋求政治大国地位"],["1993 年","欧洲联盟成立","在欧洲共同体基础上成立，欧洲一体化进程加快，成员国逐步使用统一货币欧元"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1951 年、1967 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"欧洲走向联合：欧洲煤钢共同体成立，欧…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"20 世纪 60—70 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"日本经济持续高速发展","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1993 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"欧洲联盟成立","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"西欧的联合与日本的崛起：欧洲从 1951 年煤钢共同体起步，1967 年成立欧洲共同体，1993 年成立欧洲联盟，一体化促进了西欧经济发展和国际地位提高；日本在美国扶植、制定适当经济政策、大力发展教育与科技等条件下迅速崛起，成为资本主义世界仅次于美国的第二经济大国，并谋求政治大国地位。","explain":"西欧与日本的崛起冲击了美国的霸主地位，是「多极化趋势」的重要内容，常与第六单元的多极化问题连考。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。"],["认为苏联解体的根本原因是西方国家的「和平演变」。","根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；西方国家的「和平演变」是外部原因。","「根本原因」要从内部制度与体制上找，这是唯物史观的基本要求。"]]},{"type":"table","title":"世界格局的演变：两极格局与多极化趋势（中国史联动）（二战后世界格局的变动与中国的地位）","head":["比较项","两极格局（1955—1991）","多极化趋势（1991 年以来）"],"rows":[["主要力量","以美国为首的北约与以苏联为首的华约两大集团","美国、欧盟、日本、俄罗斯、中国等多个力量中心"],["基本特征","美苏冷战对峙、集团对抗，德国分裂为两个国家","呈现「一超多强」局面，多极化趋势不断加强"],["中国的地位","1971 年恢复在联合国的合法席位，1972 年中美关系开始正常化，国际地位逐步提高","改革开放后综合国力增强，成为推动世界多极化、维护世界和平的重要力量"],["共同规律","世界格局的变动取决于各国综合实力的消长，大国关系是关键","同左"],["对中国的启示","弱国无外交，发展才是硬道理","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["大国关系与冷战","以杜鲁门主义、马歇尔计划、北约与华约的材料，考查冷战的原因、表现与影响，常要求概括「冷战为什么没有演变为世界大战」。"],["世界格局的演变","把凡尔赛—华盛顿体系、雅尔塔体系（两极格局）与多极化趋势连成一条线，考查格局变动的原因与规律，是材料大题的高频结构。"],["中国史联动的改革比较","以苏联解体与中国特色社会主义的成功作对照，考查「改革为什么必须坚持正确方向、立足国情」，落点在制度自信。"],["亚非拉民族独立与发展","给出非洲独立进程或巴拿马收回运河主权的材料，要求说明殖民体系崩溃的过程与意义，并联系发展中国家的崛起对世界格局的影响。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：冷战与多极化；地理：北约、华约与地缘格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["福利国家：国家通过社会保障制度提供医疗、养老、失业救济等，缓和社会矛盾，但也带来财政负担。 出处：2024 部编版九下第 17 课","欧洲一体化：1951 年欧洲煤钢共同体成立，1967 年欧洲共同体成立，1993 年欧盟成立，1999 年欧元问世。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 17 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u5-q5","type":"choice","stem":"在欧洲共同体的基础上成立、1993 年正式诞生的欧洲区域一体化组织是","answer":"B","explain":"1951 年成立欧洲煤钢共同体，1967 年成立欧洲共同体，1993 年在欧共体基础上成立欧洲联盟，欧洲一体化进程加快。北约与华约是军事政治集团。","options":["欧洲煤钢共同体","欧洲联盟","北大西洋公约组织","华沙条约组织"],"tags":["欧洲联合","时空观念"]},{"id":"cat-9b-5-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立\n② 日本经济持续高速发展\n③ 欧洲联盟成立","answer":"A","explain":"按时间顺序应为：①欧洲走向联合：欧洲煤钢共同体成立，欧洲共同体成立（1951 年、1967 年）→②日本经济持续高速发展（20 世纪 60—70 年代）→③欧洲联盟成立（1993 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g2","type":"choice","stem":"下列关于「二战后资本主义国家的变化」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g3","type":"choice","stem":"下列结论中，属于「二战后资本主义国家的变化」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：国家通过社会保障制度提供医疗、养老、失业救济等，缓和社会矛盾，但也带来财政负担。（2024 部编版九下第 17 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"二战后资本主义国家的变化；西欧的联合与日本的崛起：欧洲从 1951 年煤钢共同体起步，1967 年成立欧洲共同体，1993 年成立欧洲联盟，一体化促进了西欧经济发展和国际地位提高；日本在美国扶植、制定适当经济政策、大力发展教育与科技等条件下迅速崛起，成为资本主义世界仅次于美国的第二经济大国，并谋求政治大国地位。","explain":"材料出自2024 部编版九下第 17 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-5-3","title":"第18课 社会主义的曲折发展与奋起","subtitle":"九年级下册 · 第五单元 第二次世界大战后的世界变化","grade":"9b","tags":["九年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第五单元 第二次世界大战后的世界变化"},{"k":"课时","v":"第18课 社会主义的曲折发展与奋起"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"20 世纪 80 年代末 90 年代初，东欧剧变，苏联解体。1991 年 12 月，苏联解体，两极格局结束。中国特色社会主义道路取得巨大成就。"},{"type":"note","title":"本课主线 · 因果链","text":"二战结束后，美苏因国家利益与意识形态的对立走向冷战：政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约对峙，1955 年两极格局最终形成；与此同时，西欧走向联合、日本迅速崛起、亚非拉国家纷纷独立，冲击着两极格局；1991 年苏联解体，两极格局结束，世界朝多极化方向发展。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1955 年","华沙条约组织成立，两极格局最终形成","苏联与东欧 7 国签订《华沙条约》；以美苏为首的两大集团对峙局面（冷战对峙）最终形成 · 重点"],["1989 年起","东欧剧变","东欧各国社会制度发生根本性变化，社会主义运动遭受严重挫折"],["1991 年","苏联解体","八一九事件后，12 月苏联 11 个加盟共和国签署《阿拉木图宣言》，苏联解体——标志冷战结束、两极格局终结 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1955 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"华沙条约组织成立，两极格局最终形成","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":27.85,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":31.25,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":28.25,"text":"1989 年起","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":34.25,"text":"东欧剧变","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":34.65,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"1991 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"苏联解体","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"冷战的影响与评价：两极格局下美苏势均力敌，在近半个世纪内避免了新的世界大战的爆发；但冷战使世界长期处于核战争的威胁之下，局部战争不断（朝鲜战争、越南战争），也给各国经济发展带来消极影响。1991 年苏联解体，冷战结束、两极格局终结。","explain":"评价要「一分为二」：客观上维护了总体和平，但严重威胁世界和平与各国发展。"},{"level":"重点","text":"苏联解体与东欧剧变：1989 年起东欧剧变，各国社会制度发生根本变化；1990 年两德统一；1991 年苏联解体，标志冷战结束和两极格局终结。苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正，直接原因是戈尔巴乔夫改革的失败，外部原因是西方国家的「和平演变」。","explain":"必背层级：根本原因（体制弊端）＞直接原因（改革失败）＞外部原因（和平演变）；不能把外部原因当根本原因。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。","改革必须坚持正确方向、立足国情：戈尔巴乔夫改革背离社会主义方向、放弃党的领导，最终导致国家解体；中国改革开放坚持党的领导与社会主义道路，取得巨大成就。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为苏联解体的根本原因是西方国家的「和平演变」。","根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；西方国家的「和平演变」是外部原因。","「根本原因」要从内部制度与体制上找，这是唯物史观的基本要求。"],["认为东欧剧变、苏联解体说明社会主义制度行不通。","这说明苏联模式的失败，社会主义运动遭受严重挫折，但中国特色社会主义的成功证明社会主义制度具有强大的生命力。","要把「某一模式的失败」与「社会主义制度的失败」严格区分，这是材料题常见的立场类设问。"]]},{"type":"table","title":"苏联改革与中国改革开放（中国史联动）（中外对比：同样面临改革，为何结局不同）","head":["比较项","苏联（戈尔巴乔夫改革）","中国（改革开放）"],"rows":[["开始时间","1985 年起","1978 年中共十一届三中全会以后"],["指导思想","提出所谓「新思维」，放弃马克思主义的指导地位，全盘否定苏联历史","把马克思主义与中国国情相结合，走中国特色社会主义道路"],["经济改革","改革目标摇摆不定，未从根本上纠正计划经济体制的弊端","农村实行家庭联产承包责任制，城市推进国有企业改革，建立社会主义市场经济体制"],["政治改革","放弃党的领导，实行多党制，导致社会动荡、国家失控","坚持党的领导，坚持四项基本原则，稳步推进政治体制改革"],["结果","苏联解体，国家分裂，社会制度剧变","综合国力大幅提升，社会主义现代化建设取得巨大成就"],["启示","改革必须坚持正确方向、立足本国国情，必须坚持党的领导","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["大国关系与冷战","以杜鲁门主义、马歇尔计划、北约与华约的材料，考查冷战的原因、表现与影响，常要求概括「冷战为什么没有演变为世界大战」。"],["世界格局的演变","把凡尔赛—华盛顿体系、雅尔塔体系（两极格局）与多极化趋势连成一条线，考查格局变动的原因与规律，是材料大题的高频结构。"],["中国史联动的改革比较","以苏联解体与中国特色社会主义的成功作对照，考查「改革为什么必须坚持正确方向、立足国情」，落点在制度自信。"],["亚非拉民族独立与发展","给出非洲独立进程或巴拿马收回运河主权的材料，要求说明殖民体系崩溃的过程与意义，并联系发展中国家的崛起对世界格局的影响。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：冷战与多极化；地理：北约、华约与地缘格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"kv","title":"人物卡片","items":[{"k":"戈尔巴乔夫","v":"苏联领导人，推行改革失败，苏联解体。 出处：吴于廑、齐世荣《世界史·现代史编》"}]},{"type":"list","title":"延伸阅读","items":["东欧剧变：1989—1990 年，东欧各国社会制度发生根本变化，共产党失去执政地位。 出处：吴于廑、齐世荣《世界史·现代史编》","苏联解体：1991 年 8 月，苏联发生「八一九事件」；12 月，俄罗斯、乌克兰、白俄罗斯领导人签署协议，宣告苏联成立，苏联解体。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 18 课；《中国共产党简史》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】今天，几乎每一个国家都面临着两种生活方式的抉择……我认为，美国的政策必须是支持自由国家的人民抵抗少数武装分子或外来压力的征服企图。——杜鲁门 1947 年 3 月在国会发表的演说\n【材料二】美国应该尽力帮助世界恢复正常的经济秩序……我们的政策不是反对任何国家或任何主义，而是反对饥饿、贫穷、绝望和混乱。——马歇尔 1947 年 6 月在哈佛大学的演说\n【材料三】1991 年 12 月，苏联 11 个加盟共和国的领导人在阿拉木图签署宣言，宣布成立独立国家联合体，苏联解体。","source":"材料研读 · 二战后的世界变化"}],"questions":[{"id":"h9b-u5-m1-q2","type":"short","stem":"（2）综合三则材料并结合所学，说明冷战的主要表现，并分析苏联解体的原因及影响。（6 分）","answer":"主要表现：政治上出台杜鲁门主义；经济上推行马歇尔计划，援助西欧；军事上 1949 年成立北大西洋公约组织，1955 年苏联等国成立华沙条约组织，形成两大集团对峙，两极格局最终形成；1949 年德国分裂，欧洲成为冷战的重点地区。苏联解体的原因：根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；外部原因是西方国家的「和平演变」。影响：标志冷战结束、两极格局终结，世界格局向多极化方向发展；社会主义运动遭受严重挫折，但中国特色社会主义的成功证明社会主义制度具有强大的生命力。","explain":"","tags":["冷战","苏联解体","历史解释"],"rubric":["政治：杜鲁门主义","经济：马歇尔计划","军事：北约与华约的成立（两极格局最终形成）","苏联解体根本原因：高度集中的政治经济体制弊端长期得不到纠正","影响：冷战结束、两极格局终结、多极化趋势加强"]},{"id":"h9b-u5-q3","type":"choice","stem":"苏联解体的根本原因是","answer":"B","explain":"根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败，西方「和平演变」与东欧剧变是外部因素。","options":["西方国家的「和平演变」","高度集中的政治经济体制的弊端长期得不到纠正","戈尔巴乔夫个人的错误决策","东欧剧变的冲击"],"tags":["苏联解体","唯物史观"]},{"id":"h9b-u5-q6","type":"choice","stem":"东欧剧变的实质是","answer":"A","explain":"东欧剧变的实质是东欧各国的社会制度发生了根本性变化，由社会主义制度变为资本主义制度，社会主义运动遭受严重挫折。","options":["东欧各国的社会制度发生了根本性变化","东欧各国实现了民族独立","东欧各国经济体制的局部调整","东欧各国摆脱了苏联的控制但保留了原有制度"],"tags":["东欧剧变","历史解释"]},{"id":"cat-9b-5-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 华沙条约组织成立，两极格局最终形成\n② 东欧剧变\n③ 苏联解体","answer":"A","explain":"按时间顺序应为：①华沙条约组织成立，两极格局最终形成（1955 年）→②东欧剧变（1989 年起）→③苏联解体（1991 年）。","options":["①②③","②②③","③②③","①③②"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-3-g2","type":"choice","stem":"下列关于「社会主义的曲折发展与奋起」的表述，错误的是","answer":"A","explain":"认为苏联解体的根本原因是西方国家的「和平演变」——「根本原因」要从内部制度与体制上找，这是唯物史观的基本要求。正确表述：根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；西方国家的「和平演变」是外部原因。","options":["认为苏联解体的根本原因是西方国家的「和平演变」。","根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；西方国家的「和平演变」是外部原因。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1989—1990 年，东欧各国社会制度发生根本变化，共产党失去执政地位。（吴于廑、齐世荣《世界史·现代史编》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"社会主义的曲折发展与奋起；冷战的影响与评价：两极格局下美苏势均力敌，在近半个世纪内避免了新的世界大战的爆发；但冷战使世界长期处于核战争的威胁之下，局部战争不断（朝鲜战争、越南战争），也给各国经济发展带来消极影响。1991 年苏联解体，冷战结束、两极格局终结。","explain":"材料出自吴于廑、齐世荣《世界史·现代史编》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-5-4","title":"第19课 亚非拉国家的成长","subtitle":"九年级下册 · 第五单元 第二次世界大战后的世界变化","grade":"9b","tags":["九年级下册","第五单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第五单元 第二次世界大战后的世界变化"},{"k":"课时","v":"第19课 亚非拉国家的成长"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"二战后，亚非拉民族解放运动高涨。1947 年印度独立；1960 年非洲 17 国独立，被称为「非洲年」；1990 年纳米比亚独立，标志非洲殖民体系最终瓦解。古巴、巴拿马等也取得斗争胜利。"},{"type":"note","title":"本课主线 · 因果链","text":"二战结束后，美苏因国家利益与意识形态的对立走向冷战：政治上杜鲁门主义、经济上马歇尔计划、军事上北约与华约对峙，1955 年两极格局最终形成；与此同时，西欧走向联合、日本迅速崛起、亚非拉国家纷纷独立，冲击着两极格局；1991 年苏联解体，两极格局结束，世界朝多极化方向发展。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1990 年","纳米比亚独立","标志着帝国主义在非洲的殖民体系最终崩溃；此前 1960 年有 17 个非洲国家独立，被称为「非洲年」 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课要点示意图","caption":"示意图：考点层级与必背结论，详见下方","view":"tall","alt":"示意图：考点层级与必背结论，详见下方","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"重点","anchor":"start","size":3.5,"tone":"danger"},{"t":"text","x":18.5,"y":17,"text":"亚非拉国家的新发展：1947 年印度…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":38.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":42,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":39,"text":"次重点","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":45,"text":"冷战中的对抗与局部战争：1948 年…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":45.4,"x2":14,"y2":66.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":70,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":67,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":73,"text":"冷战是二战后美苏国家利益和意识形态对…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":73.4,"x2":14,"y2":94.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":98,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":95,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":101,"text":"苏联解体的根本原因是高度集中的政治经…","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":101.4,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"必背结论","anchor":"start","size":3.5,"tone":"ok"},{"t":"text","x":18.5,"y":129,"text":"苏联解体、东欧剧变说明苏联模式的失败…","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"亚非拉国家的新发展：1947 年印度独立（印巴分治）；1959 年古巴革命胜利，走上社会主义发展道路；1960 年 17 个非洲国家独立（「非洲年」）；1990 年纳米比亚独立，标志帝国主义在非洲的殖民体系最终崩溃；1999 年巴拿马收回巴拿马运河区的全部主权。发展中国家（第三世界）的兴起，成为国际舞台上的重要力量。","explain":"「民族解放运动 → 殖民体系崩溃 → 第三世界兴起 → 推动多极化」是这一考点的完整链条。"},{"level":"次重点","text":"冷战中的对抗与局部战争：1948 年柏林危机、1962 年古巴导弹危机，以及朝鲜战争、越南战争等局部热战。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。"],["认为苏联解体的根本原因是西方国家的「和平演变」。","根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；直接原因是戈尔巴乔夫改革失败；西方国家的「和平演变」是外部原因。","「根本原因」要从内部制度与体制上找，这是唯物史观的基本要求。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["大国关系与冷战","以杜鲁门主义、马歇尔计划、北约与华约的材料，考查冷战的原因、表现与影响，常要求概括「冷战为什么没有演变为世界大战」。"],["世界格局的演变","把凡尔赛—华盛顿体系、雅尔塔体系（两极格局）与多极化趋势连成一条线，考查格局变动的原因与规律，是材料大题的高频结构。"],["中国史联动的改革比较","以苏联解体与中国特色社会主义的成功作对照，考查「改革为什么必须坚持正确方向、立足国情」，落点在制度自信。"],["亚非拉民族独立与发展","给出非洲独立进程或巴拿马收回运河主权的材料，要求说明殖民体系崩溃的过程与意义，并联系发展中国家的崛起对世界格局的影响。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：冷战与多极化；地理：北约、华约与地缘格局。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["非洲年：1960 年，非洲有 17 个国家宣布独立，这一年被称为「非洲年」。 出处：2024 部编版九下第 19 课","纳米比亚独立：1990 年 3 月，纳米比亚宣布独立，标志着帝国主义在非洲的殖民体系最终崩溃。 出处：吴于廑、齐世荣《世界史·现代史编》"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 19 课；吴于廑、齐世荣《世界史·现代史编》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u5-q2","type":"choice","stem":"标志着以美苏为首的两大集团对峙局面（两极格局）最终形成的事件是","answer":"C","explain":"1949 年北约成立后，1955 年苏联与东欧 7 国成立华沙条约组织，以美苏为首的两大集团对峙局面最终形成，两极格局由此确立。","options":["1949 年德国分裂","1949 年北约成立","1955 年华约成立","1962 年古巴导弹危机"],"tags":["两极格局","时空观念"]},{"id":"h9b-u5-q4","type":"choice","stem":"1990 年纳米比亚获得独立，这一事件标志着","answer":"B","explain":"1990 年纳米比亚独立，标志着帝国主义在非洲的殖民体系最终崩溃。1960 年 17 个非洲国家独立被称为「非洲年」，非洲独立运动由此进入高潮。","options":["非洲独立运动的开始","帝国主义在非洲的殖民体系最终崩溃","世界殖民体系的开始形成","发展中国家开始崛起"],"tags":["民族解放运动","时空观念"]},{"id":"cat-9b-5-4-g2","type":"choice","stem":"下列关于「亚非拉国家的成长」的表述，错误的是","answer":"A","explain":"认为冷战开始的标志是马歇尔计划的提出或北约的成立——「冷战开始」与「两极格局形成」是两件事，两个时间点必须分别对应，不能互换。正确表述：1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","options":["认为冷战开始的标志是马歇尔计划的提出或北约的成立。","1947 年 3 月杜鲁门主义的出台标志冷战开始；马歇尔计划是冷战在经济上的表现；1949 年北约成立、1955 年华约成立标志两极格局（冷战对峙局面）最终形成。","冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-4-g3","type":"choice","stem":"下列结论中，属于「亚非拉国家的成长」的是","answer":"A","explain":"本课结论：冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["冷战是二战后美苏国家利益和意识形态对立冲突的产物；两极格局下美苏势均力敌，避免了新的世界大战爆发，但长期威胁世界和平与各国发展。","世界格局多极化趋势在冷战结束后加速发展；和平与发展是当今时代的主题，各国应加强合作、共同发展。","苏联解体的根本原因是高度集中的政治经济体制（斯大林模式）的弊端长期得不到纠正；西方国家的「和平演变」只是外部原因。","苏联解体、东欧剧变说明苏联模式的失败，社会主义运动遭受严重挫折；但中国特色社会主义的成功证明社会主义制度具有强大的生命力——改革必须坚持正确方向、立足本国国情。"],"difficulty":2,"tags":["九年级下册","第五单元","本课练习"]},{"id":"cat-9b-5-4-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1960 年，非洲有 17 个国家宣布独立，这一年被称为「非洲年」。（2024 部编版九下第 19 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"亚非拉国家的成长；亚非拉国家的新发展：1947 年印度独立（印巴分治）；1959 年古巴革命胜利，走上社会主义发展道路；1960 年 17 个非洲国家独立（「非洲年」）；1990 年纳米比亚独立，标志帝国主义在非洲的殖民体系最终崩溃；1999 年巴拿马收回巴拿马运河区的全部主权。发展中国家（第三世界）的兴起，成为国际舞台上的重要力量。","explain":"材料出自2024 部编版九下第 19 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第五单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-6-1","title":"第20课 当代世界发展的基本特点","subtitle":"九年级下册 · 第六单元 当代世界的主要发展趋势","grade":"9b","tags":["九年级下册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第六单元 当代世界的主要发展趋势"},{"k":"课时","v":"第20课 当代世界发展的基本特点"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"冷战结束后，世界格局向多极化方向发展，经济全球化、社会信息化深入发展，和平与发展仍是时代主题，但霸权主义、地区冲突、恐怖主义等问题依然存在。"},{"type":"note","title":"本课主线 · 因果链","text":"冷战结束后，和平与发展成为时代的主题：联合国与世界贸易组织成为支撑、协调世界政治和经济的两大支柱，经济全球化加速发展，世界格局朝多极化方向演进；与此同时，人口、环境、恐怖主义等全球性问题日益突出，任何国家都无法单独应对，中国提出构建人类命运共同体，为全球治理贡献中国方案。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1991 年","苏联解体后世界朝多极化方向发展","两极格局终结，美国成为唯一超级大国，欧盟、日本、俄罗斯、中国等多个力量中心崛起，呈现「一超多强」局面"],["2001 年 12 月","中国正式加入世界贸易组织","中国融入经济全球化的进程，促进了自身经济发展，也为世界经济增长作出贡献 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1991 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"苏联解体后世界朝多极化方向发展","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"2001 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中国正式加入世界贸易组织","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"经济全球化：20 世纪 90 年代以来趋势加速。表现是国际贸易和国际投资迅速增长、跨国公司影响增大、生产活动的全球化分工日益明显。影响：促进了世界经济发展和科技文化交流，为发展中国家提供引进资金技术的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险也会迅速传递。","explain":"评价必须是「双刃剑 + 趋利避害」，只答好处或只答坏处都要丢分。"},{"level":"重点","text":"世界多极化趋势：苏联解体后，美国成为唯一超级大国，但欧盟、日本、俄罗斯、中国等多个力量中心崛起，世界格局呈现「一超多强」局面，多极化趋势不断加强。多极化有利于遏制霸权主义、维护世界和平与稳定；中国综合国力的增强使其成为推动世界多极化的重要力量。","explain":"易错：多极化是「趋势」，新的世界格局尚未形成，不能说「多极格局已经确立」。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。","世界多极化趋势有利于遏制霸权主义和强权政治、维护世界和平与稳定；中国是推动世界多极化、维护世界和平的重要力量。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为世界多极化格局已经形成。","多极化是发展趋势，当前仍呈现「一超多强」局面，新的世界格局尚未最终形成。","「趋势」不等于「已形成」，这类绝对化表述通常判错。"],["认为经济全球化只有利或只有弊。","经济全球化是一把「双刃剑」：既促进世界经济发展与交流，也加剧了不平等与风险传递，所以要趋利避害。","凡涉及全球化、科技、互联网等话题，答题都要「两面看 + 说明态度」。"]]},{"type":"table","title":"中国国际地位的今昔变化：从巴黎和会到联合国与世界贸易组织（中国史联动）（中国史联动（八上—九下）：国家实力决定国际地位）","head":["比较项","1919—1945 年前","1945 年以来（尤其 1971 年后）"],"rows":[["国际会议上的处境","巴黎和会拒绝中国正当要求，把德国在山东的特权转让给日本；《九国公约》使中国回到被几个帝国主义国家共同支配的局面","1945 年成为联合国创始会员国和安理会常任理事国；1971 年恢复在联合国的合法席位"],["国际地位的性质","半殖民地半封建国家，处于任人宰割的地位","独立自主的主权国家，是维护世界和平与发展的重要力量"],["参与世界经济","被列强控制通商口岸与关税，被动卷入资本主义世界市场","2001 年 12 月加入世界贸易组织，主动融入经济全球化"],["对世界的贡献","承担战争赔款与不平等条约义务，为世界反法西斯战争作出牺牲却未得到应有地位","提出构建人类命运共同体与共建「一带一路」，为全球治理贡献中国方案"],["根本原因","弱国无外交，国家贫弱、制度落后","实现了民族独立，坚持改革开放与中国特色社会主义道路，综合国力大幅增强"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["全球化与多极化","以跨国公司的数据、国际组织材料或世界格局示意图设问，要求说明经济全球化的表现与双刃剑作用、多极化趋势的表现与意义，答题要「两面看 + 表明态度」。"],["中国与世界：国际地位与大国担当","把巴黎和会、《九国公约》与联合国、世界贸易组织、人类命运共同体串成一条线，考查中国国际地位变化的根本原因，落点在制度自信与家国情怀。"],["全球性问题的国际合作","以气候变化、公共卫生、恐怖主义等时事材料切入，考查「为什么必须国际合作」「中国方案是什么」，属联系现实的开放性试题。"],["科技与现代社会生活","以互联网、人工智能的材料考查科技对生产生活的双重影响，要求辩证评价并说明青少年应有的态度。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：人类命运共同体；地理：全球化与区域合作。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["多极化趋势：美国、欧盟、日本、俄罗斯、中国等力量中心相互制约，世界格局呈现「一超多强」并朝多极化发展。 出处：2024 部编版九下第 20 课","经济全球化：生产、贸易、投资、金融等在全球范围展开，跨国公司是主要推动者，带来机遇也带来风险。 出处：2024 部编版九下第 20 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 20 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】我联合国人民同兹决心，欲免后世再遭今代人类两度身历惨不堪言之战祸……维持国际和平及安全。——《联合国宪章》序言\n【材料二】期望通过达成互惠互利的安排，大幅度削减关税和其他贸易壁垒，在国际贸易关系中消除歧视待遇，以提高生活水平、保证充分就业……——世界贸易组织协定序言（译文）\n【材料三】气候变化、环境污染、人口增长、恐怖主义、重大传染病等全球性问题日益突出，任何一个国家都无法独自解决这些问题。中国提出构建人类命运共同体理念，倡导各国共商共建共享，为全球治理提供了中国方案。","source":"材料研读 · 走向和平发展的世界"}],"questions":[{"id":"h9b-u6-m1-q2","type":"short","stem":"（2）依据材料二、三并结合所学，说明经济全球化的表现与影响，以及中国应如何应对。（6 分）","answer":"表现：国际贸易和国际投资迅速增长，跨国公司的影响增大，生产活动的全球化分工日益明显。影响：经济全球化促进了世界经济的发展和科技、文化的交流，为发展中国家提供了引进资金、技术和先进管理经验的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险（如金融危机）也会迅速传递。应对：经济全球化是不可逆转的趋势，中国应顺应潮流、趋利避害——坚持对外开放，积极参与国际经济合作与竞争（如加入世界贸易组织），增强自主创新能力，维护国家经济安全；同时推动建立公正合理的国际经济新秩序，加强国际合作，共同应对全球性问题，倡导构建人类命运共同体。","explain":"","tags":["经济全球化","全球治理","历史解释"],"rubric":["表现：国际贸易与投资增长、跨国公司影响增大","积极影响：促进世界经济发展与科技文化交流","消极影响：发达国家主导，发展中国家处于不利地位","应对：趋利避害、坚持对外开放、维护国家经济安全","应对：推动国际经济新秩序、构建人类命运共同体"]},{"id":"h9b-u6-q3","type":"choice","stem":"1971 年，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利。这最能说明","answer":"B","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年是恢复合法席位，反映中国国际地位不断提高。多极化是发展趋势，不能说格局已经形成。","options":["中国开始成为联合国的会员国","中国的国际地位不断提高","联合国已被中国所控制","世界多极化格局已经形成"],"tags":["联合国","中国与世界"]},{"id":"h9b-u6-q4","type":"choice","stem":"对经济全球化，下列认识正确的是","answer":"B","explain":"经济全球化是一把「双刃剑」：促进世界经济发展与交流，也加剧了不平等与风险传递。它是不可逆转的趋势，各国应积极参与、趋利避害，同时维护国家主权与经济安全。","options":["经济全球化只有利于发达国家，发展中国家应拒绝参与","经济全球化是不可逆转的趋势，既是机遇也是挑战，应趋利避害","经济全球化已使各国发展水平趋于一致","经济全球化意味着国家主权可以放弃"],"tags":["经济全球化","历史解释"]},{"id":"h9b-u6-q5","type":"choice","stem":"冷战结束后，世界格局的发展趋势是","answer":"B","explain":"苏联解体后两极格局终结，美国成为唯一超级大国，欧盟、日本、俄罗斯、中国等多个力量中心崛起，世界呈现「一超多强」局面，多极化趋势不断加强，但新的世界格局尚未最终形成。","options":["两极格局进一步加强","呈现「一超多强」局面，多极化趋势不断加强","多极化格局已经完全形成","世界重新回到殖民体系"],"tags":["多极化","时空观念"]},{"id":"cat-9b-6-1-g2","type":"choice","stem":"下列关于「当代世界发展的基本特点」的表述，错误的是","answer":"A","explain":"认为世界多极化格局已经形成——「趋势」不等于「已形成」，这类绝对化表述通常判错。正确表述：多极化是发展趋势，当前仍呈现「一超多强」局面，新的世界格局尚未最终形成。","options":["认为世界多极化格局已经形成。","多极化是发展趋势，当前仍呈现「一超多强」局面，新的世界格局尚未最终形成。","经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。","世界多极化趋势有利于遏制霸权主义和强权政治、维护世界和平与稳定；中国是推动世界多极化、维护世界和平的重要力量。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-1-g4","type":"short","stem":"阅读材料，回答问题。\n材料：美国、欧盟、日本、俄罗斯、中国等力量中心相互制约，世界格局呈现「一超多强」并朝多极化发展。（2024 部编版九下第 20 课）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"当代世界发展的基本特点；经济全球化：20 世纪 90 年代以来趋势加速。表现是国际贸易和国际投资迅速增长、跨国公司影响增大、生产活动的全球化分工日益明显。影响：促进了世界经济发展和科技文化交流，为发展中国家提供引进资金技术的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险也会迅速传递。","explain":"材料出自2024 部编版九下第 20 课。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-6-2","title":"第21课 和平发展合作共赢的历史潮流","subtitle":"九年级下册 · 第六单元 当代世界的主要发展趋势","grade":"9b","tags":["九年级下册","第六单元"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第六单元 当代世界的主要发展趋势"},{"k":"课时","v":"第21课 和平发展合作共赢的历史潮流"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"和平与发展是时代主题。1945 年联合国成立，1995 年世界贸易组织成立，2013 年中国提出「一带一路」倡议，推动构建人类命运共同体。"},{"type":"note","title":"本课主线 · 因果链","text":"冷战结束后，和平与发展成为时代的主题：联合国与世界贸易组织成为支撑、协调世界政治和经济的两大支柱，经济全球化加速发展，世界格局朝多极化方向演进；与此同时，人口、环境、恐怖主义等全球性问题日益突出，任何国家都无法单独应对，中国提出构建人类命运共同体，为全球治理贡献中国方案。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响","head":["时间","事件","原因／影响"],"rows":[["1945 年 10 月 24 日","联合国正式成立","宗旨是维护国际和平与安全、促进国际合作；安理会五大常任理事国为中、法、俄、英、美 · 重点"],["1971 年 10 月","中国恢复在联合国的合法席位","第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，是中国国际地位提高的重要标志 · 重点"],["1995 年 1 月 1 日","世界贸易组织成立","取代关税与贸易总协定，与联合国一起成为支撑、协调世界政治和经济的两大支柱，推动世界贸易自由化 · 重点"],["2013 年","中国提出构建人类命运共同体理念","倡导各国共商共建共享，共同应对全球性问题，为全球治理提供中国方案，得到国际社会广泛认同 · 重点"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"wide","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":10,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":7,"text":"1945 年 10 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":13,"text":"联合国正式成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":13.4,"x2":14,"y2":20.77,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":24.17,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":21.17,"text":"1971 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":27.17,"text":"中国恢复在联合国的合法席位","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":27.57,"x2":14,"y2":34.93,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":38.33,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":35.33,"text":"1995 年 1 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":41.33,"text":"世界贸易组织成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":41.73,"x2":14,"y2":49.1,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":52.5,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":49.5,"text":"2013 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":55.5,"text":"中国提出构建人类命运共同体理念","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题","items":[{"level":"重点","text":"联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。","explain":"常与中国史联动：1971 年是「恢复合法席位」而不是「加入联合国」，表述必须准确。"},{"level":"重点","text":"世界贸易组织：1995 年 1 月 1 日成立，取代关税与贸易总协定；宗旨是通过市场开放、非歧视性和公平贸易等原则推动世界贸易自由化。它与联合国一起成为支撑、协调世界政治和经济的两大支柱。中国 2001 年 12 月正式加入，促进了中国经济发展，也为世界经济增长作出了贡献。","explain":"「世贸组织 1995 年成立、中国 2001 年加入」两个时间点常被互换设陷阱，要成对记。"},{"level":"重点","text":"构建人类命运共同体：面对气候变化、环境污染、人口增长过快、恐怖主义、重大传染病传播等全球性问题，任何国家都无法单独解决，需要各国合作。中国提出构建人类命运共同体理念，倡导共商共建共享，为全球治理贡献中国智慧和中国方案，得到国际社会广泛认同。","explain":"这是「中国方案」的固定答题落点，常与「一带一路」倡议、中国的国际贡献连考。"},{"level":"选择题","text":"联合国安理会五大常任理事国（中、法、俄、英、美）与「大国一致」原则；霸权主义、强权政治、恐怖主义是威胁世界和平的主要因素。","explain":""}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语","items":["面对全球性问题，各国应加强合作、共商共建共享；构建人类命运共同体是中国为全球治理贡献的方案，体现了中国的大国担当。"]},{"type":"table","title":"易错易混","head":["错误表述","正确表述","原因"],"rows":[["认为中国是 1971 年才加入联合国的。","中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","「加入」与「恢复合法席位」含义完全不同，是常见的表述类失分点。"],["把世界贸易组织与关税和贸易总协定混为一谈，或认为中国 2001 年是世贸组织的创始成员。","世界贸易组织 1995 年 1 月 1 日成立，取代关税与贸易总协定；中国于 2001 年 12 月正式加入。","两个时间点必须分别对应，选择题常把 1995 与 2001 互换。"]]},{"type":"table","title":"中国国际地位的今昔变化：从巴黎和会到联合国与世界贸易组织（中国史联动）（中国史联动（八上—九下）：国家实力决定国际地位）","head":["比较项","1919—1945 年前","1945 年以来（尤其 1971 年后）"],"rows":[["国际会议上的处境","巴黎和会拒绝中国正当要求，把德国在山东的特权转让给日本；《九国公约》使中国回到被几个帝国主义国家共同支配的局面","1945 年成为联合国创始会员国和安理会常任理事国；1971 年恢复在联合国的合法席位"],["国际地位的性质","半殖民地半封建国家，处于任人宰割的地位","独立自主的主权国家，是维护世界和平与发展的重要力量"],["参与世界经济","被列强控制通商口岸与关税，被动卷入资本主义世界市场","2001 年 12 月加入世界贸易组织，主动融入经济全球化"],["对世界的贡献","承担战争赔款与不平等条约义务，为世界反法西斯战争作出牺牲却未得到应有地位","提出构建人类命运共同体与共建「一带一路」，为全球治理贡献中国方案"],["根本原因","弱国无外交，国家贫弱、制度落后","实现了民族独立，坚持改革开放与中国特色社会主义道路，综合国力大幅增强"]]},{"type":"table","title":"联合国与世界贸易组织（支撑、协调世界的两大支柱（政治与经济））","head":["比较项","联合国（1945 年成立）","世界贸易组织（1995 年成立）"],"rows":[["性质","国际政治组织，是维护国际和平与安全的核心机构","国际经济组织，推动世界贸易自由化"],["宗旨","维护国际和平与安全，促进国际合作","通过市场开放、非歧视性和公平贸易等原则，推动世界贸易自由化"],["中国参与","创始会员国与安理会常任理事国，1971 年恢复合法席位","2001 年 12 月正式加入"],["共同作用","都是支撑、协调世界政治和经济的两大支柱，都推动国际合作","同左"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["全球化与多极化","以跨国公司的数据、国际组织材料或世界格局示意图设问，要求说明经济全球化的表现与双刃剑作用、多极化趋势的表现与意义，答题要「两面看 + 表明态度」。"],["中国与世界：国际地位与大国担当","把巴黎和会、《九国公约》与联合国、世界贸易组织、人类命运共同体串成一条线，考查中国国际地位变化的根本原因，落点在制度自信与家国情怀。"],["全球性问题的国际合作","以气候变化、公共卫生、恐怖主义等时事材料切入，考查「为什么必须国际合作」「中国方案是什么」，属联系现实的开放性试题。"],["科技与现代社会生活","以互联网、人工智能的材料考查科技对生产生活的双重影响，要求辩证评价并说明青少年应有的态度。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：人类命运共同体；地理：全球化与区域合作。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"table","title":"典故与成语","head":["典故／成语","释义","出处"],"rows":[["人类命运共同体","主张各国相互依存、休戚与共，共同建设持久和平、普遍安全、共同繁荣、开放包容、清洁美丽的世界。","2024 部编版九下第 21 课"]]},{"type":"list","title":"延伸阅读","items":["联合国：1945 年 10 月 24 日成立，是维护国际和平与安全的国际组织，中国是创始会员国和安理会常任理事国。 出处：《联合国宪章》","一带一路：2013 年习近平提出共建「丝绸之路经济带」和「21 世纪海上丝绸之路」倡议，促进沿线国家合作共赢。 出处：2024 部编版九下第 21 课"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 21 课；《联合国宪章》"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]},{"type":"quote","text":"【材料一】我联合国人民同兹决心，欲免后世再遭今代人类两度身历惨不堪言之战祸……维持国际和平及安全。——《联合国宪章》序言\n【材料二】期望通过达成互惠互利的安排，大幅度削减关税和其他贸易壁垒，在国际贸易关系中消除歧视待遇，以提高生活水平、保证充分就业……——世界贸易组织协定序言（译文）\n【材料三】气候变化、环境污染、人口增长、恐怖主义、重大传染病等全球性问题日益突出，任何一个国家都无法独自解决这些问题。中国提出构建人类命运共同体理念，倡导各国共商共建共享，为全球治理提供了中国方案。","source":"材料研读 · 走向和平发展的世界"}],"questions":[{"id":"h9b-u6-q3","type":"choice","stem":"1971 年，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利。这最能说明","answer":"B","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年是恢复合法席位，反映中国国际地位不断提高。多极化是发展趋势，不能说格局已经形成。","options":["中国开始成为联合国的会员国","中国的国际地位不断提高","联合国已被中国所控制","世界多极化格局已经形成"],"tags":["联合国","中国与世界"]},{"id":"h9b-u6-q6","type":"choice","stem":"面对气候变化、恐怖主义等全球性问题，中国为全球治理贡献的方案是","answer":"A","explain":"中国提出构建人类命运共同体理念，倡导各国共商共建共享、合作应对全球性问题，为全球治理贡献了中国智慧和中国方案，与霸权主义、贸易保护主义的做法根本不同。","options":["构建人类命运共同体","推行霸权主义和强权政治","实行贸易保护主义","退出国际组织，单独应对"],"tags":["人类命运共同体","家国情怀"]},{"id":"cat-9b-6-2-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 联合国正式成立\n② 中国恢复在联合国的合法席位\n③ 世界贸易组织成立\n④ 中国提出构建人类命运共同体理念","answer":"A","explain":"按时间顺序应为：①联合国正式成立（1945 年 10 月 24 日）→②中国恢复在联合国的合法席位（1971 年 10 月）→③世界贸易组织成立（1995 年 1 月 1 日）→④中国提出构建人类命运共同体理念（2013 年）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-2-g2","type":"choice","stem":"下列关于「和平发展合作共赢的历史潮流」的表述，错误的是","answer":"A","explain":"认为中国是 1971 年才加入联合国的——「加入」与「恢复合法席位」含义完全不同，是常见的表述类失分点。正确表述：中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","options":["认为中国是 1971 年才加入联合国的。","中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","面对全球性问题，各国应加强合作、共商共建共享；构建人类命运共同体是中国为全球治理贡献的方案，体现了中国的大国担当。","联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-2-g4","type":"short","stem":"阅读材料，回答问题。\n材料：1945 年 10 月 24 日成立，是维护国际和平与安全的国际组织，中国是创始会员国和安理会常任理事国。（《联合国宪章》）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"和平发展合作共赢的历史潮流；联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。","explain":"材料出自《联合国宪章》。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"cat-9b-6-3","title":"第22课 活动课 时事溯源","subtitle":"九年级下册 · 第六单元 当代世界的主要发展趋势","grade":"9b","tags":["九年级下册","第六单元","活动课"],"blocks":[{"type":"meta","items":[{"k":"册次","v":"九年级下册"},{"k":"单元","v":"第六单元 当代世界的主要发展趋势"},{"k":"课时","v":"第22课 活动课 时事溯源"}]},{"type":"note","title":"背景导读 · 这件事为什么会发生","text":"本课是活动课，通过时事溯源，把当代国际热点与历史背景联系起来，学习用历史眼光分析现实问题。"},{"type":"note","title":"本课主线 · 因果链","text":"冷战结束后，和平与发展成为时代的主题：联合国与世界贸易组织成为支撑、协调世界政治和经济的两大支柱，经济全球化加速发展，世界格局朝多极化方向演进；与此同时，人口、环境、恐怖主义等全球性问题日益突出，任何国家都无法单独应对，中国提出构建人类命运共同体，为全球治理贡献中国方案。"},{"type":"table","title":"时间轴 · 时间—事件—原因／影响（本课时间线未单列，以下为本单元完整时间轴，含相邻课时）","head":["时间","事件","原因／影响"],"rows":[["1945 年 10 月 24 日","联合国正式成立","宗旨是维护国际和平与安全、促进国际合作；安理会五大常任理事国为中、法、俄、英、美 · 重点"],["1971 年 10 月","中国恢复在联合国的合法席位","第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，是中国国际地位提高的重要标志 · 重点"],["1991 年","苏联解体后世界朝多极化方向发展","两极格局终结，美国成为唯一超级大国，欧盟、日本、俄罗斯、中国等多个力量中心崛起，呈现「一超多强」局面"],["1995 年 1 月 1 日","世界贸易组织成立","取代关税与贸易总协定，与联合国一起成为支撑、协调世界政治和经济的两大支柱，推动世界贸易自由化 · 重点"],["2001 年 12 月","中国正式加入世界贸易组织","中国融入经济全球化的进程，促进了自身经济发展，也为世界经济增长作出贡献 · 重点"],["20 世纪 90 年代以来","互联网迅速普及，人类进入信息时代","电子计算机与网络技术改变了生产方式与生活方式，也带来网络安全、信息鸿沟等新问题"]]},{"type":"figure","figure":{"id":"","title":"本课时间轴示意图","caption":"示意图：按时间先后排列，详见上方时间轴表","view":"tall","alt":"示意图：按时间先后排列，详见上方时间轴表","prims":[{"t":"dot","x":14,"y":14,"r":2,"tone":"accent"},{"t":"text","x":18.5,"y":11,"text":"1945 年 10 月 …","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":17,"text":"联合国正式成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":17.4,"x2":14,"y2":33,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":36.4,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":33.4,"text":"1971 年 10 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":39.4,"text":"中国恢复在联合国的合法席位","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":39.8,"x2":14,"y2":55.4,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":58.8,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":55.8,"text":"1991 年","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":61.8,"text":"苏联解体后世界朝多极化方向发展","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":62.2,"x2":14,"y2":77.8,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":81.2,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":78.2,"text":"1995 年 1 月 1…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":84.2,"text":"世界贸易组织成立","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":84.6,"x2":14,"y2":100.2,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":103.6,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":100.6,"text":"2001 年 12 月","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":106.6,"text":"中国正式加入世界贸易组织","anchor":"start","size":3.5,"tone":"main"},{"t":"arrow","x1":14,"y1":107,"x2":14,"y2":122.6,"tone":"muted","width":0.4},{"t":"dot","x":14,"y":126,"r":1.4,"tone":"main"},{"t":"text","x":18.5,"y":123,"text":"20 世纪 90 年代以…","anchor":"start","size":3.5,"tone":"accent"},{"t":"text","x":18.5,"y":129,"text":"互联网迅速普及，人类进入信息时代","anchor":"start","size":3.5,"tone":"main"}]}},{"type":"points","title":"中考考点分层 · 重点／次重点／选择题（本课单独考点较少，以下取本单元整体内容）","items":[{"level":"重点","text":"联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。","explain":"常与中国史联动：1971 年是「恢复合法席位」而不是「加入联合国」，表述必须准确。"},{"level":"重点","text":"世界贸易组织：1995 年 1 月 1 日成立，取代关税与贸易总协定；宗旨是通过市场开放、非歧视性和公平贸易等原则推动世界贸易自由化。它与联合国一起成为支撑、协调世界政治和经济的两大支柱。中国 2001 年 12 月正式加入，促进了中国经济发展，也为世界经济增长作出了贡献。","explain":"「世贸组织 1995 年成立、中国 2001 年加入」两个时间点常被互换设陷阱，要成对记。"},{"level":"重点","text":"经济全球化：20 世纪 90 年代以来趋势加速。表现是国际贸易和国际投资迅速增长、跨国公司影响增大、生产活动的全球化分工日益明显。影响：促进了世界经济发展和科技文化交流，为发展中国家提供引进资金技术的机会；但全球化由发达国家主导，发展中国家在国际竞争中处于不利地位，经济风险也会迅速传递。","explain":"评价必须是「双刃剑 + 趋利避害」，只答好处或只答坏处都要丢分。"},{"level":"重点","text":"世界多极化趋势：苏联解体后，美国成为唯一超级大国，但欧盟、日本、俄罗斯、中国等多个力量中心崛起，世界格局呈现「一超多强」局面，多极化趋势不断加强。多极化有利于遏制霸权主义、维护世界和平与稳定；中国综合国力的增强使其成为推动世界多极化的重要力量。","explain":"易错：多极化是「趋势」，新的世界格局尚未形成，不能说「多极格局已经确立」。"},{"level":"重点","text":"构建人类命运共同体：面对气候变化、环境污染、人口增长过快、恐怖主义、重大传染病传播等全球性问题，任何国家都无法单独解决，需要各国合作。中国提出构建人类命运共同体理念，倡导共商共建共享，为全球治理贡献中国智慧和中国方案，得到国际社会广泛认同。","explain":"这是「中国方案」的固定答题落点，常与「一带一路」倡议、中国的国际贡献连考。"}]},{"type":"note","title":"考点分级说明","text":"「重点」要能默写结论；「次重点」要能再认细节；「选择题」对应教材「了解」层级，多以单项选择、识图判断出现。"},{"type":"list","title":"必背结论与答题术语（本课结论未单列，以下取本单元必背结论）","items":["和平与发展是当今时代的主题。世界要和平、人民要合作、国家要发展、社会要进步，是不可阻挡的时代潮流。","经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。","世界多极化趋势有利于遏制霸权主义和强权政治、维护世界和平与稳定；中国是推动世界多极化、维护世界和平的重要力量。"]},{"type":"table","title":"易错易混（本课易错点未单列，以下取本单元易错易混）","head":["错误表述","正确表述","原因"],"rows":[["认为中国是 1971 年才加入联合国的。","中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","「加入」与「恢复合法席位」含义完全不同，是常见的表述类失分点。"],["把世界贸易组织与关税和贸易总协定混为一谈，或认为中国 2001 年是世贸组织的创始成员。","世界贸易组织 1995 年 1 月 1 日成立，取代关税与贸易总协定；中国于 2001 年 12 月正式加入。","两个时间点必须分别对应，选择题常把 1995 与 2001 互换。"]]},{"type":"table","title":"本单元命题角度（广州中考常见考法）","head":["命题角度","说明"],"rows":[["全球化与多极化","以跨国公司的数据、国际组织材料或世界格局示意图设问，要求说明经济全球化的表现与双刃剑作用、多极化趋势的表现与意义，答题要「两面看 + 表明态度」。"],["中国与世界：国际地位与大国担当","把巴黎和会、《九国公约》与联合国、世界贸易组织、人类命运共同体串成一条线，考查中国国际地位变化的根本原因，落点在制度自信与家国情怀。"],["全球性问题的国际合作","以气候变化、公共卫生、恐怖主义等时事材料切入，考查「为什么必须国际合作」「中国方案是什么」，属联系现实的开放性试题。"],["科技与现代社会生活","以互联网、人工智能的材料考查科技对生产生活的双重影响，要求辩证评价并说明青少年应有的态度。"]]},{"type":"note","title":"跨学科视角","text":"道德与法治：人类命运共同体；地理：全球化与区域合作。"},{"type":"h","text":"拓展学习 · 课本之外"},{"type":"list","title":"延伸阅读","items":["时事溯源的方法：选定事件—追溯历史渊源—查阅权威资料—区分事实与观点—形成有依据的判断。 出处：2024 部编版九下第 22 课「活动课」方法提示"]},{"type":"list","title":"本课拓展出处","items":["2024 部编版九下第 22 课"]},{"type":"links","title":"跨章节专题与专项训练","items":[{"t":"跨章节专题 · 两次世界大战与战后国际格局","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-05"},{"t":"跨章节专题 · 科技革命与人类社会","url":"/learn/history/pages/detail/detail?moduleId=hist-topics&entryId=ht-06"},{"t":"专题训练 · 小论文","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"},{"t":"专题训练 · 材料题","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[{"id":"h9b-u6-q1","type":"choice","stem":"世界贸易组织正式成立于","answer":"C","explain":"世界贸易组织于 1995 年 1 月 1 日正式成立，取代关税与贸易总协定。1945 年是联合国成立的时间，1971 年中国恢复在联合国的合法席位，2001 年 12 月中国正式加入世界贸易组织。","options":["1945 年","1971 年","1995 年 1 月 1 日","2001 年 12 月"],"tags":["世界贸易组织","时空观念"]},{"id":"h9b-u6-q2","type":"choice","stem":"中国正式加入世界贸易组织的时间是","answer":"D","explain":"2001 年 12 月，中国正式加入世界贸易组织，主动融入经济全球化的进程，促进了中国经济发展，也为世界经济增长作出了贡献。","options":["1971 年","1978 年","1995 年","2001 年"],"tags":["世界贸易组织","中国与世界"]},{"id":"h9b-u6-q3","type":"choice","stem":"1971 年，第 26 届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利。这最能说明","answer":"B","explain":"中国是联合国创始会员国和安理会常任理事国，1971 年是恢复合法席位，反映中国国际地位不断提高。多极化是发展趋势，不能说格局已经形成。","options":["中国开始成为联合国的会员国","中国的国际地位不断提高","联合国已被中国所控制","世界多极化格局已经形成"],"tags":["联合国","中国与世界"]},{"id":"cat-9b-6-3-g1","type":"choice","stem":"按时间先后排列下列事件，正确的是\n① 联合国正式成立\n② 中国恢复在联合国的合法席位\n③ 苏联解体后世界朝多极化方向发展\n④ 世界贸易组织成立","answer":"A","explain":"按时间顺序应为：①联合国正式成立（1945 年 10 月 24 日）→②中国恢复在联合国的合法席位（1971 年 10 月）→③苏联解体后世界朝多极化方向发展（1991 年）→④世界贸易组织成立（1995 年 1 月 1 日）。","options":["①②③④","②②③④","③②③④","①③②④"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-3-g2","type":"choice","stem":"下列关于「活动课 时事溯源」的表述，错误的是","answer":"A","explain":"认为中国是 1971 年才加入联合国的——「加入」与「恢复合法席位」含义完全不同，是常见的表述类失分点。正确表述：中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","options":["认为中国是 1971 年才加入联合国的。","中国是联合国的创始会员国和安理会常任理事国；1971 年第 26 届联大是恢复中华人民共和国在联合国的一切合法权利。","和平与发展是当今时代的主题。世界要和平、人民要合作、国家要发展、社会要进步，是不可阻挡的时代潮流。","经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-3-g3","type":"choice","stem":"下列结论中，属于「活动课 时事溯源」的是","answer":"A","explain":"本课结论：和平与发展是当今时代的主题。世界要和平、人民要合作、国家要发展、社会要进步，是不可阻挡的时代潮流。。其余三项是同一单元相邻课时的结论，不属于本课。","options":["和平与发展是当今时代的主题。世界要和平、人民要合作、国家要发展、社会要进步，是不可阻挡的时代潮流。","经济全球化是不可逆转的趋势，但要趋利避害：既要积极参与国际合作与竞争，又要增强自主创新能力、维护国家经济安全。","世界多极化趋势有利于遏制霸权主义和强权政治、维护世界和平与稳定；中国是推动世界多极化、维护世界和平的重要力量。","面对全球性问题，各国应加强合作、共商共建共享；构建人类命运共同体是中国为全球治理贡献的方案，体现了中国的大国担当。"],"difficulty":2,"tags":["九年级下册","第六单元","本课练习"]},{"id":"cat-9b-6-3-g4","type":"short","stem":"阅读材料，回答问题。\n材料：选定事件—追溯历史渊源—查阅权威资料—区分事实与观点—形成有依据的判断。（2024 部编版九下第 22 课「活动课」方法提示）\n（1）材料所述内容与哪一历史事件（现象）相关？\n（2）结合所学，概括这一事件（现象）的影响。","answer":"活动课 时事溯源；联合国的宗旨与作用：1945 年 10 月 24 日成立，宗旨是维护国际和平与安全、促进国际合作。它在维护世界和平、缓和国际紧张局势、解决地区冲突、促进国际合作等方面发挥了积极作用；但曾一度被大国操纵，作用受到制约。中国是联合国创始会员国和安理会常任理事国，1971 年恢复在联合国的合法席位，成为维护世界和平与发展的重要力量。","explain":"材料出自2024 部编版九下第 22 课「活动课」方法提示。作答时先据材料定位事件，再从课本结论归纳影响。","difficulty":3,"tags":["九年级下册","第六单元","本课练习","材料题"],"rubric":["准确写出事件名称","影响至少答出两个角度（政治、经济、社会、文化）","结合材料，不只抄结论"]}]},{"id":"hm-essay","title":"学史方法（一） 如何写作历史小论文","subtitle":"九年级下册 · 学史方法","grade":"9b","tags":["学史方法","方法指导"],"blocks":[{"type":"meta","items":[{"k":"出处","v":"2024 部编版九年级下册「学史方法」"}]},{"type":"note","title":"说明","text":"这是教材给出的方法栏目，具体步骤、模板与实战题已整理进「中考专题训练」，可直接点击下方链接进入。"},{"type":"links","title":"配套训练","items":[{"t":"进入对应专题训练","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-essay"}]}],"questions":[]},{"id":"hm-net","title":"学史方法（二） 如何运用网络资源","subtitle":"九年级下册 · 学史方法","grade":"9b","tags":["学史方法","方法指导"],"blocks":[{"type":"meta","items":[{"k":"出处","v":"2024 部编版九年级下册「学史方法」"}]},{"type":"note","title":"说明","text":"这是教材给出的方法栏目，具体步骤、模板与实战题已整理进「中考专题训练」，可直接点击下方链接进入。"},{"type":"links","title":"配套训练","items":[{"t":"进入对应专题训练","url":"/learn/history/pages/detail/detail?moduleId=hist-drills&entryId=drill-source"}]}],"questions":[]}];
